window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_035"]={"n":"于慎行","dyn":"明","poems":[{"t":"驱车上东门行","f":"五言古诗","c":["驱车上东门，回望咸阳路。","郁郁五陵间，累累多墟墓。","长夜号鼪鼬，秋风走狐兔。","牧竖游且歌，行人四面顾。","借问此何谁，昔时董与傅。","车马如流水，第宅通云雾。","富贵一旦空，忽如草间露。","阅水日成川，阅世人非故。","贤愚共一丘，千载为旦暮。","嗤彼道傍子，营营胡不寤。"]},{"t":"子夜歌十二首 其二","f":"五言绝句","c":["秋月照四壁，络纬当窗织。","徒闻机杼声，终夜不成匹。"]},{"t":"子夜歌十二首 其四","f":"五言绝句","c":["始欲识欢时，愿作同心结。","丝线不相逢，里许暗自别。"]},{"t":"子夜歌十二首 其九","f":"五言绝句","c":["枕上看月来，梦中与欢诀。","月自不相离，欢心不如月。"]},{"t":"子夜歌十二首 其十一","f":"五言绝句","c":["侬如水中石，波至亦累累。","欢如陌上尘，左右从风吹。"]},{"t":"子夜春歌 其一","f":"五言绝句","c":["朱景带碧楼，新风吹罗幌。","谁能怀春情，不发柔弦响。"]},{"t":"子夜春歌 其三","f":"五言绝句","c":["金屋燕初飞，长堤草已绿。","春蚕不作茧，思子何由续。"]},{"t":"子夜夏歌 其二","f":"五言绝句","c":["何处复无暑，月出湖水边。","汎舟芙蓉里，分明自取莲。"]},{"t":"子夜夏歌 其三","f":"五言绝句","c":["含桃初作花，畏恐旁人见。","今日食含桃，空条谁复盼。"]},{"t":"子夜秋歌 其二","f":"五言绝句","c":["凉风夜中来，白露凝如玉。","不敢拭清砧，捣衣乱心曲。"]},{"t":"子夜秋歌 其三","f":"五言绝句","c":["露井冻银床，秋风生桐树。","任吹桐花飞，莫吹梧子去。"]},{"t":"子夜冬歌 其二","f":"五言绝句","c":["万里覆寒云，千林飞素雪。","此时为欢愁，心如三伏热。"]},{"t":"子夜冬歌 其三","f":"五言绝句","c":["华茵倚重炉，璇房捲罗幕。","惊见雪花飞，谓是杨花落。"]},{"t":"续曲歌 其二","f":"五言绝句","c":["侬作博山炉，双烟吐不住。","郎如飘风吹，但将香引去。"]},{"t":"感怀二十首 其八","f":"五言古诗","c":["东出长安门，倚马息道周。","上有百年木，下有万古流。","华轩驰广陌，冠盖如云浮。","去者日以远，来者日以遒。","朱颜入朝市，皓首将安求。","应侯朝上书，蔡泽暮西游。","荣枯在俯仰，譬海浮水沤。","所以赤松徒，屣脱万户侯。"]},{"t":"杂诗八首 其四","f":"五言古诗","c":["北登辽阳城，顾望三韩道。","大海何萧条，白骨横野草。","下充蛟鱼食，上使乌鸢饱。","伤哉十万师，大半涂肝脑。","粟米量如沙，金帛积成岛。","功名诚可为，封疆在自保。","闭关谢远人，良图胡不考。"]},{"t":"杂诗八首 其六","f":"五言古诗","c":["延陵有长剑，宝若千金璧。","闭匣泣风雨，开匣干星日。","骏马与名都，罗列终不易。","服之适异土，见谓铅刀质。","徐君亦何为，神襟独尔识。","欲色在不言，心许成莫逆。","如何历聘归，墓门已有棘。","含意竟未伸，涕下空沾臆。","宰木集晨风，可以悬三尺。","寸心苟不渝，是物何足惜。","驱马去郊原，弃置如遗迹。","贤哉贵公子，交情固金石。","咄彼市门徒，景行宜自惕。"]},{"t":"杂诗八首 其八","f":"五言古诗","c":["神龙时未遇，蠖略蟠深渊。","不有浮云藉，何由润八埏。","鹍鹏随海运，一徙阴重玄。","扶摇非有负，羽翮安能旋。","远臣必有主，迩臣必有先。","商君因景监，五羖介穆贤。","内资富强业，外秉侯王权。","功名岂不伟，烈士无称焉。","行藏制在己，升沉制在天。","寸尺既可枉，寻丈宁无愆。","所以鲁连子，抗志青冥间。","只矢三军解，单辞六国全。","万钟苟不欲，屣脱如浮烟。","谅哉天下士，畴克与比肩。"]},{"t":"长安道","f":"古风","c":["东出灞陵桥，回望长安道。","烟花万户暖风轻，罗绮千门明月晓。","汉家宫阙郁岧峣，碧阁珠楼倚绛霄。","丞相衣冠苍玉佩，将军甲第赤栏桥。","平明内殿承颜色，日晏朝回行紫陌。","夹道金羁赭汗流，盈门绣辖朱尘塞。","人生得意自辉光，刺谒纷纭满路旁。","一笑看人回禄命，片言酬客腐肝肠。","小子胜衣皆受印，苍头结绶亦为郎。","貔虎三千陈列第，鸳鸯七十闭东厢。","银床月瑩流苏帐，翠幕烟浮玳瑁梁。","镫前北里千金舞，座上宜城九酝觞。","年去年来无旦暮，春花秋月依然度。","歌吹平连长乐钟，林园直接新丰树。","祗知娱乐不知忧，转眼荣华逐水流。","谁道冰山可永峙，谁言天雨可重收。","曾闻上将幽钟室，曾见元公赐养牛。","博陆门前罗鸟雀，平津邸内走鼪鼬。","古来世事浑如许，道上垂杨不解语。","唯有东陵旧日侯，瓜田看尽青门雨。"]},{"t":"大堤曲","f":"七言古诗","c":["大堤春尽花成雨，大堤女儿隔花语。","扬州估客四角幡，暮泊兰桡宿江渚。","芙蓉宝帓绿云鬟，翠簟银缸夜色寒。","倚瑟当垆春酒尽，卷帷望月晓装残。","石城一曲歌未足，日出天空江水绿。","含啼送客更多愁，肠断烟波万里秋。"]},{"t":"上云乐","f":"古风","c":["东厢食举百戏作，鱼龙曼衍中堂落。","华钟忽驻舞缀停，更进西方《上云乐》。","老胡家世是文康，紫髯深目华盖方。","白巾裹头火浣细，绿珠作带韎?长。","曾从海上栽若木，吹笙更截昆崙竹。","朝看阿母鬓成霜，夕见安期颜似玉。","却候明时日再中，朅来献赆玉门东。","流沙暮涉三万里，碣石天开百二重。","辟邪师子陈成列，赴曲声随箫鼓节。","汉苑白麟未足珍，宛城宝马空称绝。","老胡歌舞奏仙倡，为祝黄图日月长。","但愿百蛮九塞靖烽火，陛下长倾万岁觞。"]},{"t":"武定侯墓歌","f":"古风","c":["长安城西销客魂，故侯墓前双石门。","空梁无风蟏蛸挂，高台不夜鼯鼠奔。","行歌牧竖上陇首，守冢老兵眠树根。","道傍徙倚长叹息，千古此意谁与论。","当时贵宠真无匹，势倚青天回白日。","骖乘亲陪别苑游，行香日侍斋宫直。","元公铁券大国封，都护金章新样刻。","玉鞭蹀躞内厩马，雕盘络绎尚方食。","权相交驩亦扫门，彻侯受酒咸避席。","此时意气薄青云，睇笑看人宠辱分。","负郭园池田太尉，重城甲第霍将军。","求仙偏访烧铅客，亡命多归带剑群。","曲阁重楼春自驻，繁弦急管日初曛。","自言富贵无销歇，争见桑田海亦竭。","未央宫前请室开，咸阳道上车尘绝。","閒门行马卧莓苔，旧馆罦罳藏雨雪。","只今尺土闭空原，岁岁春啼杜宇血。","吁嗟嗟世皇二宠倾朝廷，前有武定后咸宁。","福过俱为万人指，法行再见七庙灵。","人间荣悴咸可数，古来金谷与郿坞。","前车已却后车驰，请君但看北邙土。"]},{"t":"双林寺歌","f":"古风","c":["道旁佛宫谁者筑，珠楼宝殿横山麓。","僧徒指点为予说，此寺方成主人逐。","忆昨十载气薰天，吐纳日月挥云烟。","外廷稍引三公势，内禁亲操六玺权。","出入钩陈留筦钥，笑谈甲观走金蝉。","建寺平侵贵主第，施僧直请大官钱。","输来多宝堆成塔，辇尽黄金布作田。","法宫梵宇何连曼，胜地名区看不断。","墓上林园学九陵，祠前楼阁成双观。","落成牛酒国亲供，建醮香花天女献。","吁嗟此寺独渺小，赤刀已欲盈千万。","我皇神威符世祖，距脱大奸俯地取。","郭家金穴入水衡，邓氏铜山归少府。","庐儿解玉乞街衢，宅妇怀簪随卒虏。","惟馀此寺在郊原，虹梁绮搆谁为主。","蛛网空悬梵铎风，青苔自锁玱琅雨。","盛衰转盼那不有，几年翻覆看如许。","君不见江陵城头土三尺，若敖馁鬼不来食。","一代贤豪此谓何，尔全首领恩亦极。"]},{"t":"雪后登楼看山歌","f":"七言古诗","c":["昨朝飞雪满大荒，登楼四顾天茫茫。","今朝登楼禁不得，吾与青山头并白。","筠床呼酒皛宇开，瑶华积作中天台。","对山遥劝一杯酒，平生与君为素友。","君今头白青有时，奈何吾鬓真成丝。"]},{"t":"雨中舟行","f":"五言律诗","c":["天阔雨冥冥，孤帆过驿亭。","云吞江树白，雾失晓峰青。","岸鸟迎船湿，河鱼出网腥。","生涯多少恨，无处异飘萍。"]},{"t":"题画","f":"五言律诗","c":["黯淡秋湖色，涵虚望渺然。","断桥横落日，远水出寒烟。","雁向平沙落，鸥依折苇眠。","吾家住湖上，閒杀采菱船。"]},{"t":"应制题画四首 其一 雪景","f":"五言律诗","c":["轻绡寒色动，不是月华开。","鸟道千岩迥，江光一径回。","虚无分玉树，彷佛想瑶台。","未拟歌黄竹，阳春遍九垓。"]},{"t":"应制题画四首 其二 烟雨","f":"五言律诗","c":["潇潇一幅上，秋气满枫林。","半似随风引，全疑夹雾阴。","远峰看处暝，疏树望来深。","笔底烟云色，争知用作霖。"]},{"t":"应制题画四首 其三 宣庙御笔汀鸟","f":"五言律诗","c":["笔端成大造，海鸟若相忘。","暮雨汀莎湿，春风岸芷香。","柳边迷落絮，云里带飞霜。","总为经天藻，长留羽翰光。"]},{"t":"应制题画四首 其四 鹌鹑","f":"五言律诗","c":["渺彼榆枋翼，丹青画作真。","静眠宫草日，閒傍苑花春。","顾影骄金距，逢场上锦茵。","非同珠树鸟，独用羽毛珍。"]},{"t":"邵伯湖夜泊","f":"五言律诗","c":["日暮倚兰桡，秋江正寂寥。","驿门斜对雨，郡郭远通潮。","急橹看商舶，寒灯见市桥。","隋堤前路近，欲听月中箫。"]},{"t":"长干","f":"五言律诗","c":["白门通市里，传是古长干。","陌柳藏鸦曙，秋潮带雨寒。","横塘归客断，子夜旧歌阑。","别是繁华地，休将六代看。"]},{"t":"秦淮","f":"五言律诗","c":["秋月秦淮岸，江声转画桥。","市楼临绮陌，商女驻兰桡。","云里青丝骑，花间碧玉箫。","不知桃叶水，流恨几时消。"]},{"t":"白沟河","f":"五言律诗","c":["西风吹易水，晓饭白沟河。","猎骑平原浅，渔舟别渚多。","地分燕赵敌，国蹙宋辽和。","今日逢全盛，卢龙尚枕戈。"]},{"t":"赠人为金吾郎二首 其二","f":"五言律诗","c":["陌上锦云连，期门校猎旋。","射声银作镝，蹑影玉为鞭。","撇草连双兔，凌空接两鸢。","应怜汉飞将，白首滞穷边。"]},{"t":"咏史","f":"五言律诗","c":["十八侍中郎，春深侍建章。","呼卢金戺侧，蹋鞠玉楼旁。","夜赐离宫酒，朝薰异国香。","可怜秦殿女，向月卷罗裳。"]},{"t":"上隔马岭旧寺","f":"五言律诗","c":["荒凉经古寺，迢递出层空。","路抱千峰转，天开一窦通。","残松疏雨后，颓瓦夕阳中。","犹有馀僧在，逢迎问转蓬。"]},{"t":"秋日南溪閒眺得李宗伯丈书","f":"五言律诗","c":["溪阁非无事，秋清日转长。","扫花安鹿砦，帖石补鱼梁。","高树留新雨，平波澹夕阳。","远书何意至，三读素心伤。"]},{"t":"冬至南郊扈从纪述和陈玉垒太史韵八首 其一","f":"七言律诗","c":["圣后乘乾奉帝禋，日躔南陆协灵辰。","九关肃启天门钥，万姓欢随御辇尘。","楼雪初融丹禁晓，葭灰微动玉衡春。","虚惭珥笔亲文物，实有《甘泉赋》未陈。"]},{"t":"冬至南郊扈从纪述和陈玉垒太史韵八首 其四","f":"七言律诗","c":["玉兰东畔画帘前，到处常随豹尾旋。","圣代仪文今日盛，儒臣雨露向来偏。","琅函赐锦驰中骑，宝鼎分餐出御筵。","斋室受釐应有问，朝回犹恐夜深宣。"]},{"t":"冬至南郊扈从纪述和陈玉垒太史韵八首 其五","f":"七言律诗","c":["绛阙阴沈启秘扃，銮舆肃穆款真庭。","霜凝碧落天衣湿，月上仙坛玉树青。","帝座三重开万象，云门六变走群灵。","祠臣秉笏香烟里，时向珠躔望景星。"]},{"t":"冬至南郊扈从纪述和陈玉垒太史韵八首 其六","f":"七言律诗","c":["绛节氤氲上太清，紫烟缥缈冠层城。","鹓行不动瑶池影，凤幄微闻玉藻声。","律应一阳璇象转，福凝五位泰阶平。","礼成回跸传行漏，百尺华灯阙下明。"]},{"t":"冬至南郊扈从纪述和陈玉垒太史韵八首 其七","f":"七言律诗","c":["灯火薰天夹路旁，属车旋处翠华张。","非烟拥盖璇霄丽，若月乘轮御陌长。","十里香花连泰畤，千门鼓吹彻昭阳。","皇诚已自通天贶，万祀应知宝祚昌。"]},{"t":"冬至南郊扈从纪述和陈玉垒太史韵八首 其八","f":"七言律诗","c":["紫气葱葱绕禁庐，南郊迎日履长初。","皇王礼乐光前殿，侍从声华满后车。","汉畤龙麟金匮纪，周台云物彩毫书。","雄文亦是乡人似，齐客谈天恐不如。"]},{"t":"馆课冬至斋居","f":"七言律诗","c":["缇室灰飞晷欲长，清斋仙馆坐焚香。","雪残楼阁虚琼树，月出簪裾满玉堂。","笔望五云迎舜日，心随一线入尧裳。","明朝负橐趋陪地，只在瑶坛帝座旁。"]},{"t":"葛端肃公挽章四首 其三","f":"七言律诗","c":["华年声价省郎游，一节冰霜到白头。","降岳神生星应昴，济川功就壑藏舟。","朱门旧第公槐影，落叶新阡宰树秋。","惟有故时双鹤在，月寒华表不胜愁。"]},{"t":"在告书怀柬可大","f":"七言律诗","c":["金门何事转愁予，日见红尘上锦裾。","祗为思归长数雁，几因多病欲焚鱼。","乡心瓦上三更雨，客计床头数卷书。","幸藉旬休聊闭阁，文园从此卧相如。"]},{"t":"病中遣怀","f":"七言律诗","c":["三月孤斋斗帐寒，十旬休沐主恩宽。","閒翻药裹呼儿晒，细检诗筒借客看。","千里乡心芳草绿，一年春色杏花残。","浮踪去住浑无赖，行路人间信是难。"]},{"t":"寄吴少溪宫录七十 其四 山居自述呈王对南相君","f":"七言律诗","c":["阙下班行旧日分，海边名姓少人闻。","一竿自钓南溪月，五㹀亲耕上阪云。","竹径常无猿报客，松关惟有鹤为群。","只缘不忘平生谊，塞雁来时屡梦君。"]},{"t":"寄吴少溪宫录七十 其六十六 宿云楼閒坐","f":"七言律诗","c":["久将心事付山灵，石几焚香对翠屏。","万里秋声云外雁，一天寒色雨边萤。","閒来只自烧茶灶，病里凭谁著酒经。","总为此中堪避地，不教人指少微星。"]},{"t":"恭闻东宫礼成志喜","f":"七言律诗","c":["午夜前星耀禁林，龙楼紫气晓来深。","当年苦竭愚臣悃，此日真知圣父心。","关塞烟销休战伐，江湖春至起讴吟。","瑶图亿万高皇统，只有神灵护至今。"]},{"t":"新都程君房寄墨数螺道中为税使所榷戏作志感","f":"七言律诗","c":["客卿闻已渡江涔，乌有何从问艺林。","楮国交游成落寞，松侯封爵付销沉。","思玄但检张衡赋，守黑空遵老氏箴。","为语中人休错误，隃麋原不化黄金。"]},{"t":"閒居述怀","f":"七言律诗","c":["未老归随鹿豕群，十年阅尽北山云。","神全瓦注原非巧，名混金瓯久未分。","岁晏谁能怀邓禹，功高自合谢田文。","华阳十赉皆君宠，九命何殊阙下闻。"]},{"t":"纪赐四十首 其一 丙子二月初与经筵进讲纪述","f":"七言律诗","c":["春云别殿倚平台，问道恭承步辇来。","讲席平依丹地转，经函近对御筵开。","凝旒晬穆闻天语，委佩从容列上台。","圣学方隆恩礼茂，儒臣长此奉康哉。"]},{"t":"纪赐四十首 其二 丙子七月初侍日讲纪述","f":"七言律诗","c":["内殿云深启法筵，隔屏初听玉音宣。","宫臣举案趋宸幄，阁相垂绅拱细旃。","壁影丝丝浮绣网，签头字字指瑶编。","冰兢祇惧终无补，未觉身依尺五天。"]},{"t":"纪赐四十首 其四 丙子九月工部奏进万历制钱式样赐讲官六人各一锭","f":"七言律诗","c":["汉苑新成少府钱，万年宝历赤文镌。","青凫出冶铜官奏，黄纸题名玉署传。","赵壹囊空留暂满，东方俸薄赐常偏。","五侯甲第虚成埒，未拟儒臣受宠年。"]},{"t":"纪赐四十首 其五 丁丑三月上亲洒宸翰大书责难陈善四字以赐","f":"七言律诗","c":["龙笺一幅日星光，天藻昭垂自尚方。","久向横经窥圣蕴，还因纳诲奉奎章。","琅函想见仙毫动，蓬室惊闻御墨香。","儒术承恩逢景运，非同常侍漫登床。"]},{"t":"纪赐四十首 其六 丁丑五月大旱雩祷上斋居御讲颁赐素蔬一盒","f":"七言律诗","c":["云汉忧歌岁事艰，桑林虔祷圣心殚。","祈年不辍金华讲，减膳犹分玉箸餐。","始见仙盘疑汎露，却尝宝馔是调兰。","崇朝肤寸纡宸想，霖雨应腾四野欢。"]},{"t":"纪赐四十首 其八 戊寅正月上出内府画册命讲官六人各题四幅分得宣庙御画二幅诗成奏上各赐银叶一包","f":"七言律诗","c":["百年壁府护仙葩，奉诏恭题睿览赊。","岂为丹青悬日月，欲凭翰墨发云霞。","叨荣乍捧银为叶，摛藻虚惭笔有花。","文学承恩逢盛典，黄金买赋未应誇。"]},{"t":"纪赐四十首 其九 戊寅正月上尚巾礼成群臣称贺赐白金文绮","f":"七言律诗","c":["负扆年来海岳安，春朝绣帻始胜冠。","龙楼拂曙天颜近，玉座垂旒日角宽。","九庙神灵应已慰，两阶环佩不胜欢。","迩臣幸奉青蒲对，珍赐还看出上阑。"]},{"t":"纪赐四十首 其十 戊寅正月进讲赐大红织成段衣一袭","f":"七言律诗","c":["讲殿朝朝圣渥频，赐衣又见出枫宸。","织成共识金梭巧，贡到初开锦样新。","色借宫云红近日，香浮仙佩暖宜春。","垂裳幸值轩唐理，补衮无劳愧许身。"]},{"t":"纪赐四十首 其十二 元旦赐门神挂屏葫芦等物岁以为常","f":"七言律诗","c":["节启青阳岁籥新，金人十二画为神。","韶华自合留天府，御气谁期洽近臣。","綵胜仍分仙禁缕，云屏况借汉宫春。","却怜寂寞扬雄宅，门巷恩光接紫宸。"]},{"t":"纪赐四十首 其十三 端午赐黄金艾叶银书灵符等物岁以为常","f":"七言律诗","c":["芙蓉阙下玉书宣，午日恩颁侍从前。","宝叶光分仙岛月，灵符香缀御炉烟。","岁时旧自荆人记，风俗曾经汉史传。","闻道宸游临太液，龙舟凤管画楼边。"]},{"t":"纪赐四十首 其十四 八月十七日万寿圣节赐白金文币及镂金万寿福禄篆字银书黄朱灵符等物岁以为常","f":"七言律诗","c":["华渚祥开禁籞天，恩光每觉近臣偏。","函加白璧来天上，锦散红云出日边。","裁就灵符华舜旦，镌成宝画纪尧年。","衔恩效祝惭无补，金鉴先时献御筵。"]},{"t":"纪赐四十首 其十六 十一月二十九日圣母万寿圣节赐金币镂金篆字黄朱灵符等物岁以为常","f":"七言律诗","c":["长乐凝和婺彩光，侍臣沾贶圣恩长。","璆琳内苑开银瓮，云锦天机隐御香。","鸟迹呈书仙算永，龙文纪瑞宝符黄。","朝来碧落箫《韶》度，内殿亲称万寿觞。"]},{"t":"纪赐四十首 其十七 冬至恭侍庆成大宴","f":"七言律诗","c":["南郊夜燎泰坛烟，内殿朝开大庆筵。","两陛衣冠承湛露，千门钟鼓震钧天。","亲瞻玉几云霄上，久汎仙杯日月边。","温旨三传咸已醉，欢声动地未央前。"]},{"t":"纪赐四十首 其十八 甲戌七月奏进穆庙实录赐白金文绮宴于南宫","f":"七言律诗","c":["紬书金匮愧非才，曾是先朝侍从来。","鹓列趋随兰检进，龙衣立待石函开。","濡毫每忆攀髯望，珥笔新承赐锦回。","大典已成鸿号永，圣心南面尚含哀。"]},{"t":"纪赐四十首 其二十二 赐画面川扇","f":"七言律诗","c":["九华綵扇贡巴东，午日承恩出汉宫。","云影金泥黄帕解，花开宝绘玉函空。","擎来濯锦江头月，动处披香殿里风。","自是君恩在怀袖，惟将皎洁矢丹衷。"]},{"t":"纪赐四十首 其二十三 赐鲜笋","f":"七言律诗","c":["殊锡光生玉笋班，曾从青简赋檀栾。","蒲筐乍解香盈座，锦箨初分绿满盘。","一饭疑含仙禁雨，三秋犹忆北窗寒。","惭无凤实仪千仞，祝有龙孙长万竿。"]},{"t":"纪赐四十首 其二十四 赐鲜藕","f":"七言律诗","c":["芙蓉别殿晓风凉，玉井灵根出水香。","荐熟方闻开寝庙，赐鲜已见布朝堂。","冰丝欲断鲛人缕，琼液疑含阆苑霜。","忆昨金鳌桥上望，红衣翠盖满银塘。"]},{"t":"纪赐四十首 其二十六 赐鲜枇杷","f":"七言律诗","c":["佳名汉苑旧标奇，北客由来目不知。","绿萼经春堆笼日，黄金满树入筐时。","江南漫道珍卢橘，西蜀休称荐荔枝。","千里梯航来不易，怀将馀核志恩私。"]},{"t":"纪赐四十首 其二十七 赐鲜桃李","f":"七言律诗","c":["讲罢传宣殿左厢，分将苞品灿盈筐。","宫桃剖出丹霞冷，仙李沈来碧玉香。","方朔瑶池人汗漫，安仁金谷赋荒凉。","怀恩正恐虚秋实，不羡春华吐艳阳。"]},{"t":"纪赐四十首 其二十八 赐鲜鲥鱼","f":"七言律诗","c":["六月鲥鱼带雪寒，三千江路到长安。","尧厨未进银刀鲙，汉阙先分玉露盘。","赐比群卿恩已重，颁随元老遇犹难。","迟回退食惭无补，仙馔年年领大官。"]},{"t":"纪赐四十首 其二十九 己夘春以病在告上疏乞归值圣体违和旋即万福再赐万喜金字白金文绮于私第拜恩","f":"七言律诗","c":["春朝华祝动仙班，寂寞词臣尚闭关。","七日曾疑游帝所，一春全未睹天颜。","簪符已奉期门送，金帛还从卧阁颁。","长使圣躬承昊贶，归山魂梦亦应閒。"]},{"t":"纪赐四十首 其三十一 癸未甲申三扈圣驾上陵赐大红织金曳撒鸾带等物","f":"七言律诗","c":["阁门五夜听传呼，受赐先从左阙趋。","绣带平悬金凿落，鞶囊斜挂锦襜褕。","行随豹尾陪天仗，立傍螭坳夹御炉。","却笑甘泉称侍从，不知原庙似今无。"]},{"t":"纪赐四十首 其三十二 甲申春月扈从车驾奉两宫圣母阅定寿宫赐綵花文绮等物","f":"七言律诗","c":["銮舆三驾出山隈，墨食欣传福兆开。","地拥真图连朔塞，天留紫盖作轩台。","两宫共倚璇丘望，万乘亲扶玉辇陪。","遥见黄门传散綵，红云朵朵下山来。"]},{"t":"纪赐四十首 其三十三 丙戌廷试读卷赐宴文华西室遣内监出陪例也","f":"七言律诗","c":["临轩五度擢英才，品第连朝直帝台。","香案前头文字进，殿门西畔俎筵开。","清班许从元公列，曲宴传教内监陪。","圣代得贤应有颂，遭逢惟祝泰方来。"]},{"t":"纪赐四十首 其三十四 丙戌秋月以皇次子生赐万喜金字綵花金币等物","f":"七言律诗","c":["西宫送喜到宸旒，侍从恩随禁苑优。","胜剪双枝花作綵，金镌万喜字当头。","他年茅土应藩汉，此日圭璋早颂周。","共识昭陵多王气，年年春色满龙楼。"]},{"t":"纪赐四十首 其三十五 丙戌冬至南郊扈驾圣母轸念天寒特赐姜苏杏仁一盒","f":"七言律诗","c":["黄门飞鞚到天坛，传道东朝赐讲官。","祇为甘泉劳扈从，特从温室下盘餐。","调兰欲动先春色，斮桂浑消午夜寒。","慈念殷勤知有望，惭无一字罄衷丹。"]},{"t":"纪赐四十首 其三十六 丁亥二月奏进大明会典赐白金文绮宴于南宫仍给三代诰命","f":"七言律诗","c":["九朝谟烈玉书藏，祖德宗功万祀昌。","汉代不须条故事，周家惟用考前王。","颁恩内省恩纶降，赐宴南宫广乐张。","就裹儒臣称最渥，特烦三锡下龙章。"]},{"t":"纪赐四十首 其三十七 戊子九月寿宫随驾步视宝城还于东廊称贺玉音宣劳赐茶并赉綵花文绮等物","f":"七言律诗","c":["朱楼绛阙冠层霞，玉■金支驻翠华。","元相幄中分御锦，侍臣冠上珥宫花。","仙城步阅教随驾，别殿常参命赐茶。","可道龙颜多喜豫，万年福地属皇家。"]},{"t":"纪赐四十首 其三十八 己丑六月三品考满荷蒙圣恩遣内使及门赍赐羊酒宝钞","f":"七言律诗","c":["典礼南宫侍禁筵，还因奏绩荷恩偏。","牢尊特遣中涓赐，楮币亲从少府传。","漫拟恩华同八座，犹将名字厕群仙。","多惭衮职曾无补，一卷牙签十四年。"]},{"t":"纪赐四十首 其四十 辛夘九月乞休得请钦遣内使赍赐路费宝钞次日又遣内使赍赐白金文绮盖六卿日讲各有特恩也","f":"七言律诗","c":["乞休十疏始抽簪，敕使连朝出禁林。","备物卿臣元自厚，殊荣讲幄旧来深。","初衣已卷天机锦，归橐犹函内殿金。","惭负宸慈何以报，惟将丹扆效馀箴。"]},{"t":"恭谒孝陵有述十四韵","f":"五言古诗","c":["圣迹开玄造，神都奠旧疆。","基图垂万祀，谟烈冠千王。","风雨园陵闭，衣冠寝用藏。","霞标悬绛阙，云际拱雕梁。","胜地盘龙虎，高丘下凤凰。","石麟秋作雨，铁马汗为霜。","落月铺金锁，飞花上玉床。","重关陈豹旅，濡露集鸳行。","扈跸群灵会，包茅九域将。","长江萦阁道，叠嶂列宫墙。","礼乐恢函夏，明威肃大方。","治成周六典，法画汉三章。","缥缈松楸路，昭回日月光。","小臣歌帝则，绳武祝今皇。"]},{"t":"题忠顺夫人画像四首 其一","f":"七言绝句","c":["燕支山色点平芜，染出春愁上画图。","一曲胡笳明月夜，边声又度小单于。"]},{"t":"题忠顺夫人画像四首 其二","f":"七言绝句","c":["边城新舞《柘枝》辞，降得浑邪罢汉师。","不道长安春色少，甘泉宫里画阏氏。"]},{"t":"题忠顺夫人画像四首 其三","f":"七言绝句","c":["天山猎罢雪漫漫，绣袜斜偎七宝鞍。","半醉屠苏双颊冷，桃花一片殢春寒。"]},{"t":"题忠顺夫人画像四首 其四","f":"七言绝句","c":["莲花宝铗绿云鬟，不脱襜褕款汉关。","枉杀白登城下画，虏中原自有红颜。"]},{"t":"夏日过二兄石淙别业同游洪范东流用韵六首 其一","f":"七言绝句","c":["十里行歌路欲迷，石桥曲径过龙溪。","村翁底事争相笑，驴背风吹白接䍦。"]},{"t":"夏日过二兄石淙别业同游洪范东流用韵六首 其二","f":"七言绝句","c":["桃花落尽武陵溪，碧草芊芊岸柳齐。","洞口主人今不在，青山如画鸟空啼。"]},{"t":"夏日过二兄石淙别业同游洪范东流用韵六首 其四","f":"七言绝句","c":["谷口花深日欲低，水边村落听鸡啼。","晚山更自多佳气，一带寒烟暮雨西。"]},{"t":"夏日过二兄石淙别业同游洪范东流用韵六首 其六","f":"七言绝句","c":["霸主荒坟俯碧溪，夕阳草树冷凄凄。","山泉带雨声何急，流到台前不向西。"]},{"t":"四月一日曹常侍园看花同冯用韫葛仲明二馆丈赋 其一","f":"七言绝句","c":["西城仙馆侍中家，别苑春深玉洞霞。","一曲歌声听不散，随风吹落小桃花。"]},{"t":"四月一日曹常侍园看花同冯用韫葛仲明二馆丈赋 其二","f":"七言绝句","c":["春红尽向野亭开，万绿轻阴锁碧苔。","独有梨花能似雪，尊前半拂舞衣回。"]},{"t":"四月一日曹常侍园看花同冯用韫葛仲明二馆丈赋 其三","f":"七言绝句","c":["垂柳池边见海棠，一枝寂寞倚残妆。","娉婷可奈移灯看，何处春愁不断肠。"]},{"t":"四月一日曹常侍园看花同冯用韫葛仲明二馆丈赋 其四","f":"七言绝句","c":["宫霞半吐玉阑干，春色迟迟上牡丹。","不是东风催未得，天香绰约不胜寒。"]},{"t":"题张学士閒云馆四首 其一","f":"七言绝句","c":["芙蓉江馆闭霏微，江面閒云拥钓矶。","春色不胜芳草绿，萋萋长似待人归。"]},{"t":"游仙诗","f":"五言古诗","c":["姑射一何高，高高凌绛阙。","上有两仙人，肌肤如玉雪。","不笑亦不言，藐与世人绝。","上谒逢真人，授我大药诀。","服药一玉箱，辽然五情热。","轻举步九霄，烟云忽若灭。","大鸟止城门，安知是令威。","徐市入东海，胡不采药归。","三山空波涛，孰别是与非。","大化自有运，寿命各有期。","追念古贤圣，往往为土灰。","汗漫不足道，六籍我所归。"]},{"t":"长歌行","f":"五言古诗","c":["宴坐北堂上，秋宇何清凉。","客心殊不乐，起视夜未央。","新月鉴空轩，列宿烂成行。","熠耀飞中庭，莎鸡号东厢。","仰见孤鸣雁，噭噭天南翔。","屣履步阶除，啸咤以慨慷。","少壮弄文史，思登君子堂。","青阳忽不待，玄发亦已苍。","百川正东流，大海何泱泱。","寒暑相迁次，日月互匿藏。","年命非金石，荣耀安得长。","自非不朽图，何以播馀芳。","抱兹千岁忧，俯仰中情伤。"]},{"t":"短歌行","f":"古风","c":["对酒当歌，朱颜未酡。","日月其除，不乐奈何。","周道茫茫，辟如羊肠。","葆身藏名，唯有醉乡。","阴木贞心，烈士苦颜。","微子之故，胡为永叹。","海水知寒，山石知雨。","忧来攻中，谁当告语。","河之悠悠，欲济无梁。","率彼旷野，霜露沾裳。","斮桂为橑，葺兰为宇。","美人不来，吾谁与处。"]},{"t":"虾䱉篇","f":"五言古诗","c":["醯鸡慕鼎俎，不知天地宽。","蜉蝣望朝夕，安能念岁寒。","小人固多逸，志士良不閒。","远涉四海岸，高举五岳巅。","俯视红颜子，磬折一何艰。","春华诚可悦，秋实无乃阑。","啸咤拥长剑，气薄曾云端。","品庶徒营营，安知达者观。"]},{"t":"饮马长城窟行","f":"五言古诗","c":["青青陵上柏，翘翘思远客。","远客在何方，长城道路长。","路长时复久，门外春杨柳。","杨柳正依依，君行胡不归。","食薤自知辛，食檗自知苦。","苦辛在人心，当复谁为语。","有鸟云中来，嗷嗷过我庭。","愿附一札书，达我沈忧情。","鸟辞天路远，哀鸣去不返。","去去莫复陈，亲疏自有因。"]},{"t":"善哉行","f":"古风","c":["秋风萧萧，白露为霜。","今日相欢，胡不尽觞。","游彼三山，绛阙煌煌。","道逢安朝，授我要方。","采苓采苓，于彼高冈。","日暮天寒，风吹我裳。","群鸟夜鸣，虎豹纵横。","踌蹰四顾，郁何芒芒。","白鹄晨号，在彼中阿。","啸匹不得，伤如之何。","东方渐高，明星没河。","毋复相思，沉吟啸歌。"]},{"t":"相逢行","f":"五言古诗","c":["相彼双阙间，车马夜行游。","相逢问君家，君家南陌头。","黄金为门枢，碧玉疏高楼。","中庭垂珠树，灵鸟翔庭陬。","长子侍中郎，中子大长秋。","小子胜揖拜，赐爵关内侯。","五日一洗沐，宾客满道周。","通名不敢进，雨汗交横流。","置酒高堂上，歌舞无时休。","越姬调鸣瑟，赵女弹箜篌。","一酌山岳寿，再酌江海酬。","行乐未及终，年岁忽已遒。","日匿西崦嵫，月出咸池隅。","日月有亏盈，荣华能久留。","所以古贤圣，视若烟云浮。"]},{"t":"燕歌行七解 其一","f":"七言古诗","c":["西风烈烈霜满庭，天寒波深列宿明。","孤堂四壁络纬鸣，念君远客忧思盈。","日月相逐逝不停，百川东下如建瓴。","谁能怀忧心不惊，抚时感事中怦怦。","就枕假寐不能成，揽衣起步露沾缨。","月出皎皎照前楹，群鸟栖树寒无声。","孤鸿何为中夜征，踯躅四顾伤人情，尔胡不归独屏营。"]},{"t":"燕歌行七解 燕歌行六解 其二","f":"七言古诗","c":["来日苦短去日长，四时代谢心茫茫。","为客置酒临中堂，吴歈齐讴出东厢。","引宫刻徵为乐方，悲音冽冽激中肠。","劳心惆忉不可忘，西风吹衣天雨霜。","列宿灿烂罗成行，双星明明在河梁。","咫尺不语空相望，何为含忧令心伤。"]},{"t":"燕歌行七解 其三 陌上桑","f":"五言古诗","c":["日出东南隅，照我邯郸宫。","邯郸有好女，颜色靡春风。","采蘩出城南，采桑出城东。","黄金为长钩，桂枝为大笼。","上襦绣鸳鸯，下裙绣芙蓉。","肌肤宛如玉，善态不可穷。","飞鸟见女来，厉翮凌高空。","游鱼见女来，潜游深渊中。","车人去其盖，舟人去其篷。","少年满路傍，叹息忘所从。"]},{"t":"燕歌行七解 其四 西门行","f":"古风","c":["出西门，歌且行。","今我不极乐，当欲何营。","江河水，东下如建瓴。","安能邑邑迫蹙，坐使华岁零。","策骏马，驾高轩。","召呼平生游，驰逐双阙间。","薰以香自烧，膏以明自煎。","鼎鼎百年内，胡为长不欢。","谁见仙人安期生，骖驾白鹿游三山。","谁见仙人安期生，骖驾白鹿游三山。","四时相递代，日月如转丸。","乘时修令名，毋为世所叹。"]},{"t":"燕歌行七解 其五 艳歌何尝行","f":"古风","c":["何为侘傺长吁。","但当饮旨酒，吹笙竽。","二十为侍中郎，三十执金吾。","四十虽不大贵，车马骎骎往来，公卿长者居。","但当在五陵，陌上快独呼。","鸡走狗被服襜褕。","男儿堕地，横绝四海，皇皇日夜，心一何愚。","畴昔相追随，斗酒从游盘。","一日不相及，中道与君成间关。","束发奉明主，忠诚夙所殚。","上有公家三尺，下为众庶所观。","彼美人子，何为营营，日夜诚足叹。"]},{"t":"燕歌行七解 其六 门有车马客行","f":"五言古诗","c":["门有车马客，驾言出汉关。","顾念平生游，枉迹问考槃。","倒屣出门迎，摄袂不及餐。","坐客置斗酒，握手论辛酸。","借问朝市中，荣枯多变迁。","金张自赫奕，丁傅相扳援。","新贵日更进，旧老日以残。","浅水有迅波，浮云无定端。","天时相代谢，世事诚艰难。","送客闭我门，偃仰窃自欢。"]},{"t":"燕歌行七解 其七 白头吟","f":"五言古诗","c":["朝为山上云，暮为川上雨。","变化在君心，然疑不得语。","今日为牛女，明日为参商。","参商不相待，安知秋夜长。","素心一何愚，自谓与众殊。","所贱菅与蒯，所贵玉与珠。","白石何累累，流水何潺潺。","水流石不转，人情中道还。"]},{"t":"满歌行","f":"古风","c":["适意能几何，日月不居，逝如江河。","裴回路岐，自使蹉跎。","遥望旧乡，郁何嵯峨。","心之烦忧，其端孔多。","炯炯多所念，鼎鼎欲何为。","举世如驰，拙者守道，智者趋时。","上观下获，以博铢锱。","岂不洵美，匪伊所思。","秋风既寒，昔蹈东海，一何盘桓。","流水出门，白云在山。","风尘挠予，去不遑安。","夙夜在公，凋此华颜。","天道难知，人胡可谋。","遗荣避世，师彼庄周。","凿坏踰垣，亦复何求。","楚楚贵人，不知春秋。","斗酒相呼，以游以遨。","岂伊异人，夙昔同袍。","莫小泰山，莫大秋毫。","直木先伐，薰香自烧。","尔不自夷，岁月其慆。","葆真缮性，含光自韬。","存神观化，睎彼松乔。"]},{"t":"箜篌引","f":"五言古诗","c":["今日斗酒会，为欢诚未央。","高堂罗尊俎，四座何清凉。","庖人出珍膳，嘉旨充圆方。","吴歈中酒发，赵瑟激清商。","丝竹洞心耳，悲至不尽觞。","为客起行游，游彼大道旁。","车马若流水，佩剑寒秋霜。","被服心所喜，聊且为乐康。","朱门多媚少，磬折有容光。","春华耀朝日，夕暮从风扬。","四时舍我逝，日月递相藏。","人生天壤内，譬鸟集枯桑。","何不适情志，恣君技所长。","含情欲何待，但为达者伤。"]},{"t":"独漉篇","f":"古风","c":["独漉独漉，山深水曲。","水曲回桡，山深折轴。","黄鹄高飞，横绝四极。","欲往从之，恨无羽翼。","转蓬离根，随风飞翻。","游子不归，慆此华年。","骐骥不驾，谁别逸足。","璞石不分，谁知良玉。","利剑在掌，可以割犀。","全身忘国，安用臣为。","龙欲上天，势须浮云。","岂无蹇修，不可以群。"]},{"t":"淮南王","f":"古风","c":["淮南王，慕灵仙，服食丹药求大年。","重楼十二罗五城，玉童吹箫作凤鸣。","左石室，右丹台。","枕中鸿宝不可开，咸阳帝子非仙才。","八公一去神鼎空，化为双白鹤飞云中。","飞云中，游天际，鸡犬无声空城闭。","茂陵神宫树成列，淮南丹灶狐兔穴。"]},{"t":"公无渡河","f":"古风","c":["公无渡河，河水汤汤，连山嵯峨。","电雨晦冥，龙伯来过。","吞舟锯齿，其族孔多。","公无凫跃之技，出没涛波。","又无宝璧与马，歆神之和。","往则沉溺，当奈公何。","善游固有数，请公无渡河。"]},{"t":"君子有所思行","f":"五言古诗","c":["登彼西山道，还顾重城阙。","皇居丽以佳，侯王多阀阅。","国典盛衣冠，军容陈斧钺。","鸡鸣内殿朝，日宴宾徒谒。","楚舞奏方阑，齐讴声未歇。","允兹七贵里，执手忱可热。","四郊既多垒，九土灾孔烈。","肉食何委蛇，忧时在岩穴。","旨哉周任规，陈力乃就列。"]},{"t":"董逃行","f":"古风","c":["西风木落天秋。","江寒露下霜流。","三星素月当楼。","芳筵嘉客娱游。","促觞接䣛淹留。","肴核充溢壶觞。","吴趋越艳登堂。","皎如星文电光。","丹唇素齿流芳。","歌声上薄楣梁。","瑶笙象管中微。","七盘奇舞何迟。","腕弱不任铢衣。","仙仙举手欲飞。","四座太息忘疲。","三清旨酒既醺。","都梁沉水氤氲。","腾觚献寿欣欣。","宾心既醉如焚。","意气激薄青云。","日月不居岁阑。","世道崄巇万端。","春华坐失渥丹。","何不被服罗纨。","逍遥永夕为欢。"]},{"t":"仙人篇","f":"五言古诗","c":["我闻列仙人，高举云中行。","游目陕四海，矫首跂太清。","翔鸾翊芝盖，白鹿骖华軨。","朝发玄都府，夕憩蓬莱城。","高风吹玉■，倏忽遂上征。","九关敞朱户，双阙郁峥嵘。","云汉流前除，白榆夹道生。","羡门与赤松，含笑窥轩楹。","饮我玄霜液，餐我琪树英。","回观八纮内，万有如蠛蠓。","跳丸一何迅，过驹逝不停。","大年等天地，末路安足营。"]},{"t":"结客少年场行","f":"五言古诗","c":["少年慕豪侠，意气凌高空。","生长五都市，结交六郡雄。","千金买紫燕，万户买吴鸿。","探丸渭城北，挟弹霸陵东。","杯酒笑相许，忼慨气填胸。","耻为小夫态，长慕国士风。","连营过细柳，逐寇出回中。","左击呼韩遁，右战谷蠡穷。","尘起塞云黑，日落秋原红。","韬戈报明主，长揖不论功。"]},{"t":"白纻舞歌晋体","f":"七言古诗","c":["兰膏明烛秋夜长，齐讴秦吹响洞房。","二八徐舞为仙倡，纨袖拂面飞朝霜。","游龙宛转双雁行，如却复进低且昂。","朱唇妙响含宫商，凝娇流态不可详。","弦悲管急欲断肠，人生百年如电光。","春华未落秋风凉，盘中美酒琥珀香。","凤腊麟脯充圆方，君今胡为不尽觞，生逢圣世乐且康。"]},{"t":"白纻辞鲍照体 其一","f":"七言古诗","c":["雕轩洞户组帐悬，垂珰结佩舞少年。","凝眸欲笑却复前，鸣弦激管流芳烟。","惊鸿乍散白鹄旋，如矜若怨姿变迁，低鬟拂袖私嫣然。"]},{"t":"白纻辞鲍照体 其二","f":"七言古诗","c":["月横星高四壁寒，秦筝激响赵瑟弹。","满堂霜雪飞罗纨，含宫咀徵曲未阑。","杳然流目意楚酸，春华委谢秋露漙，君今不采谁为欢。"]},{"t":"白纻辞鲍照体 其三","f":"古风","c":["张曲筵，陈芳醑，月下妖童白纻舞。","弦悲管促双袖举，桃花水边三月雨。","吴宫乌啼明星微，西风拂幌木叶飞，堂上烛灭君宁归。"]},{"t":"枯鱼过河泣","f":"五言古诗","c":["福集岂无端，祸臻亮有由。","枯鱼过河泣，悔从鲸鳄游。","扬鬐出溟海，振翼徙炎洲。","翻涛作风雨，喷浪成山丘。","旁顾无陵鲤，鳣鲔安足俦。","一朝宕海澨，潮落委遐陬。","红肌试砧斧，白骨聚蚍蜉。","横海既成观，盈尺亦满舟。","回首羡鲂鱮，游戏清波流。","慎旃远游子，濡足何所求。"]},{"t":"门有万里客","f":"五言古诗","c":["翩翩紫骝马，宛宛黄金珰。","客从何方来，悲吟坐我堂。","客从江上来，言向长安路。","海水白波长，茫茫不可渡。","我有绿绮琴，为君鼓三行。","谁为胶与漆，谁为参与商。","索索复索索，送子长安陌。","借问云间人，何如山中客。","山中无所赠，手把青兰枝。","一握何足道，但感同心辞。","别君日以深，送君日以远。","安危在盛名，努力加餐饭。"]},{"t":"江上曲","f":"七言古诗","c":["天津桥下杨花白，春风吹落东城陌。","城乌啼罢燕燕飞，飘霜流雪何霏微。","画堂窈窕连香阁，金屋春寒珠网薄。","芙蓉羽帐粉色香，万年枝上初日长。","可怜风吹过江去，相思望断江南树。"]},{"t":"阳春曲","f":"七言古诗","c":["绮疏旭日春风寒，风吹落花飘井栏。","飞来飞去玉柱端，美人掩镜鸣双环。","雕琴纤指当窗弹，含宫咀商曲欲殚。","辽然流想心不欢，天山积雪久未乾。","尺书欲寄陇道难，安能随风到玉关。","闺阴早霜岁欲阑，红颜寂寞空长叹。"]},{"t":"子夜歌十二首 其一","f":"五言绝句","c":["侬年三五时，双鬟垂两肩。","日在欢左右，不解取欢怜。"]},{"t":"子夜歌十二首 其三","f":"五言绝句","c":["不能识郎心，何用识郎面。","黄檗在深林，苦心谁得见。"]},{"t":"子夜歌十二首 其五","f":"五言绝句","c":["欢游横塘岸，侬望长安道。","昔为同心花，今成断肠草。"]},{"t":"子夜歌十二首 其六","f":"五言绝句","c":["年少不为乐，夷犹欲谁与。","不见东门花，落地如红雨。"]},{"t":"子夜歌十二首 其七","f":"五言绝句","c":["明旦沟水头，折柳牵郎衣。","郎心如流水，东去何时归。"]},{"t":"子夜歌十二首 其八","f":"五言绝句","c":["谁令冰不寒，谁令火不热。","雨霜涂前除，侬思底得绝。"]},{"t":"子夜歌十二首 其十","f":"五言绝句","c":["相逢不须臾，相看长脉脉。","木末采芙蓉，莲子何由得。"]},{"t":"子夜歌十二首 其十二","f":"五言绝句","c":["玉腕弄柔弦，清商吐未转。","何意凉风吹，使我肝肠断。"]},{"t":"子夜春歌 其二","f":"五言绝句","c":["春花浑欲笑，春鸟自成歌。","惆怅春皋上，含愁可奈何。"]},{"t":"子夜春歌 其四","f":"五言绝句","c":["正及春花时，采芳步华薄。","春风复无情，又欲吹花落。"]},{"t":"子夜夏歌 其一","f":"五言绝句","c":["开轩待远风，风来不吹面。","何如觅剪刀，裁作合欢扇。"]},{"t":"子夜夏歌 其四","f":"五言绝句","c":["别时杨花落，别后藕花芳。","惜往觉日短，望来觉日长。"]},{"t":"子夜秋歌 其一","f":"五言绝句","c":["严霜下空阶，促织声何烈。","夜中无人语，怀情望秋月。"]},{"t":"子夜秋歌 其四","f":"五言绝句","c":["别欢三春月，思欢九秋霜。","霜华上玄鬓，侬心底不伤。"]},{"t":"子夜冬歌 其一","f":"五言绝句","c":["朔风吹北林，玄冰结远岸。","君心非松柏，岁寒那不变。"]},{"t":"子夜冬歌 其四","f":"五言绝句","c":["忆欢不能寐，中夜涕纵横。","河流不应冻，是侬泪结成。"]},{"t":"上声 其一","f":"五言绝句","c":["木叶自欲黄，不待西风作。","闻郎歌上声，曲终泪已落。"]},{"t":"上声 其二","f":"五言绝句","c":["上声一何悲，柱促弦欲绝。","三叹未终极，已看鬓如雪。"]},{"t":"前溪 其一","f":"五言绝句","c":["郎从前溪去，不向前溪返。","水流无浅深，人心有近远。"]},{"t":"前溪 其二","f":"五言绝句","c":["前溪何潺潺，花流逐水去。","侬欲使花还，不能使水住。"]},{"t":"七日夜女歌 其一","f":"五言绝句","c":["长空起薄寒，明河流素月。","谁云一夕欢，可当经年别。"]},{"t":"七日夜女歌 其二","f":"五言绝句","c":["经年一水间，相望不相及。","莫卷七襄衣，是侬愁思织。"]},{"t":"碧玉歌 其一","f":"五言绝句","c":["碧玉好颜色，故是小家女。","笑倚金绣屏，不解挑郎语。"]},{"t":"碧玉歌 其二","f":"五言绝句","c":["碧玉十五馀，丝发不及肩。","理妆背面立，宛转得郎怜。"]},{"t":"续曲歌 其一","f":"五言绝句","c":["别时不知愁，别后空相忆。","日晚潮水来，渡头问消息。"]},{"t":"续曲歌 其三","f":"五言绝句","c":["本作双鸳鸯，忽为别鹄怨。","不是侬泪流，江水有时断。"]},{"t":"续曲歌 其四","f":"五言绝句","c":["脉脉闺阁中，常似千里别。","两心自分明，有如水上月。"]},{"t":"东飞伯劳歌","f":"七言古诗","c":["鸳鸯比翼翡翠吟，巫山湘水高且深。","可怜新妆映白日，芳脂艳粉当轩出。","银床试展金缕衣，绮疏月缀琉璃扉。","凝娇聚态语复咽，卷衣谢君心欲绝。","春风袅袅花气寒，长留可怜谁为欢。"]},{"t":"乌栖曲四首 其一","f":"七言绝句","c":["桃花如泥柳如雪，飘泊乘风无断绝。","青枫江上波色寒，郎今不渡春梦阑。"]},{"t":"乌栖曲四首 其二","f":"七言绝句","c":["白门栖乌夜未晓，参横月没霜皎皎。","金徒受水能几何，合欢日少别日多。"]},{"t":"乌栖曲四首 其三","f":"七言绝句","c":["芙蓉羽帐翡翠钩，月华当户河汉流。","微吟细酌欢未厌，城上乌啼明星烂。"]},{"t":"乌栖曲四首 其四","f":"七言绝句","c":["银床小簟云母屏，博山吐焰双烟青。","相看脉脉两无语，曼声一曲泪如雨。"]},{"t":"江南曲 其一","f":"古风","c":["金堤柳枝拂水黄。","桃花如焚众草香。","江南稚女歌春阳。","歌春阳，气若兰。","采江蓠，遗所欢。"]},{"t":"江南曲 其二","f":"古风","c":["春江漠漠朝气深。","丹霞紫露流满林。","踟蹰解佩伤春心。","伤春心，骋远目。","望平皋，草空绿。"]},{"t":"四时折杨柳歌 其一","f":"古风","c":["春风入上兰，鸟啼绿烟中，日耀桃李颜。","折杨柳，春去复来归，人去当归否。"]},{"t":"四时折杨柳歌 其二","f":"古风","c":["芙蓉散朱华，吐艳为谁芳，不采当柰何。","折杨柳，不畏秋浦空，愿得在欢手。"]},{"t":"四时折杨柳歌 其三","f":"古风","c":["问君何时归，明月凝前除，微霜下沾衣。","折杨柳，捣衣寄远人，夜凉不觉久。"]},{"t":"四时折杨柳歌 其四","f":"古风","c":["北风正烈烈，雨雪逐风飞，山深步道绝。","折杨柳，但保岁寒心，不道欢相负。"]},{"t":"感怀二十首 其一","f":"五言古诗","c":["皎皎天中月，照我虚堂壁。","抚枕心不夷，起视今何夕。","摄提指孟陬，年岁忽复易。","跳丸日夜驰，迫迫将焉适。","烈士怀贞心，夸毗营寸尺。","因时览群动，感叹无终极。"]},{"t":"感怀二十首 其二","f":"五言古诗","c":["皑皑原上霜，萋萋道傍草。","金石有销铄，人生安可保。","大化为炉锤，万物何缴绕。","达士耻近图，所思在远道。","荣瘁非有期，修名苦不早。","焉能自结束，坐向风尘老。"]},{"t":"感怀二十首 其三","f":"五言古诗","c":["日出上东门，桃李何灼灼。","回风中夜起，嘉树纷其落。","昔时五侯子，宝马黄金络。","北里吹笙竽，南邻钟磬作。","斗鸡出长杨，挟弹过平乐。","光采照云日，意气何轩霍。","高台一旦平，里巷飘飞藿。","不见东陵瓜，近在青门郭。"]},{"t":"感怀二十首 其四","f":"五言古诗","c":["迢迢泰山隅，渺渺无行迹。","猿鸟夹路啼，松桂百馀尺。","中有啸歌士，鸣琴卧泉石。","夕采山上薇，朝吸松间液。","放情凌绛霄，流目瞩四极。","宴息藐无言，中情多所适。","我欲往从之，惜哉无羽翼。"]},{"t":"感怀二十首 其五","f":"五言古诗","c":["薛公昔好士，珠履罗高堂。","酒酣指白日，各欲吐肝肠。","相印甫脱肘，门前迹已荒。","魏其盛宾客，田侯安敢望。","一绾大将组，车马盈路傍。","疏者为胶漆，亲者为参商。","朝暮市门改，贵贱交情伤。","灌夫与冯子，意气何飞扬。","悠悠数千载，此道久沦亡。"]},{"t":"感怀二十首 其六","f":"五言古诗","c":["朔风凄以厉，憭慄吹人衣。","玄云起大陆，雨雪何霏霏。","孤鸿号中夜，百卉具已腓。","长恐坚冰至，凛凛伤骨肌。","鸡鸣感时物，游子驾言归。"]},{"t":"感怀二十首 其七","f":"五言古诗","c":["白日回青阳，春草萋已绿。","游子忽不乐，沉吟聊踯躅。","踯躅将何为，念彼东山麓。","涧壑生白云，冈峦荫修木。","飞泉落绝壁，璆然写哀玉。","山水有至音，安用徵丝竹。","长揖陌上人，去来从所欲。"]},{"t":"感怀二十首 其九","f":"五言古诗","c":["陟彼高台上，天风吹我裳。","顾见双黄鹄，浩浩摩空翔。","振翮翳若木，矫翅凌扶桑。","羽翼岂不修，其如天路长。","横绝薄四海，中道以徬徨。","如何燕雀群，追逐令人伤。"]},{"t":"感怀二十首 其十","f":"五言古诗","c":["吾慕汉阴叟，灌园聊避世。","搰搰自行汲，不肯生机事。","掉首谢圣儒，比之为技系。","混沌虽假修，厥言良有味。","世人徒营营，心劳自憔悴。"]},{"t":"感怀二十首 其十一","f":"五言古诗","c":["三年雕一叶，为日已蹉跎。","木鸢徒跕跕，不能出网罗。","天巧固已凿，于世亦何加。","大圆惟混混，万木生条柯。","工者力常少，拙者力常多。","操斤代大匠，伤手将如何。"]},{"t":"感怀二十首 其十二","f":"五言古诗","c":["登彼蓟门道，东望渔阳城。","渔阳秋草落，万里阴云生。","鸣笳弥旷野，虏骑何纵横。","羽书东西驰，刁斗日夜鸣。","一战左贤遁，再战谷蠡惊。","白骨蔽榛莽，落日空原平。","成功苟如此，安得有吞声。"]},{"t":"感怀二十首 其十三","f":"五言古诗","c":["十五弄柔翰，操业游艺林。","纵志有遐览，颇见千古心。","委质事明主，岁月忽已深。","怀思敢不报，所愧在浮沉。","悲歌览青镜，长恐华发侵。","大块陶万籁，纤巨固殊音。","微尚在虚恬，经世非所任。","俛仰感白日，啸咤谁能禁。"]},{"t":"感怀二十首 其十四","f":"五言古诗","c":["家本东海裔，樵牧东山下。","先子秉儒术，歌音追大雅。","一吏稍浮沉，举世无知者。","眇予秉薄祜，宛洛随车马。","丘陇日以遥，松柏在原野。","风木无停音，雨露凄其洒。","一为皋鱼叹，零涕缘缨泻。"]},{"t":"感怀二十首 其十五","f":"五言古诗","c":["昔我珠树林，荧荧照琼岛。","子仲工文词，奇气何夭矫。","如何时不遇，岁宴空山道。","卞玉苟不开，谁知为世宝。","伤彼蕙与兰，含芳扬绿藻。","严霜被空谷，将欲同秋草。","用大世所难，咄唶令人老。"]},{"t":"感怀二十首 其十六","f":"五言古诗","c":["习习泽中鸟，斑斑五采质。","天寒游石梁，十步不得食。","一朝栖灵囿，羽翰生颜色。","餐君玉山禾，饮君丹霞液。","道旁有寒士，感之长太息。","拂拭岂不怀，人养非所适。","愿因晨风发，振我凌空翼。"]},{"t":"感怀二十首 其十七","f":"五言古诗","c":["大鹏运溟海，举翮触四隅。","鹪鹩巢一枝，栖息常有馀。","适志无小大，窥化有盈虚。","昔日五侯里，狐兔嘷其墟。","君平卜百钱，常有终岁储。","老氏戒止足，千古铭盘盂。"]},{"t":"感怀二十首 其十八","f":"五言古诗","c":["栎社有大树，轮囷以樛棼。","下枝蔽牛马，上干干青云。","匠伯睨不顾，终古绝斧斤。","翡翠巢南海，何尝慕世氛。","金丸落珍木，惟以羽毛文。","膏火为谁销，兰香徒自焚。","多材实身累，沉溟与道群。"]},{"t":"感怀二十首 其十九","f":"五言古诗","c":["六籍既已远，扬马不可作。","铅刀为湛卢，腊鼠称周璞。","伟哉二三子，将操郢匠凿。","胡为崇亢厉，亦复呈丹雘。","裂吻御寒菹，飘帷奏清角。","信美非大观，矩裁焉所托。","雅道和且平，治音安以乐。","不悲而嘘唏，皇风无乃薄。"]},{"t":"感怀二十首 其二十","f":"五言古诗","c":["黄帝游赤水，象罔得玄珠。","遇道皆如此，安用图与书。","奈何江左流，所味在清虚。","六籍皆糟粕，三坟为土苴。","得鱼可忘筌，无筌焉取鱼。","譬人适莽浪，伥伥将奚如。","悲哉道丧世，一叹徒愁予。"]},{"t":"古意十二首 其一","f":"五言古诗","c":["新知且莫欢，生离且莫悲。","忧来无定端，愁思当语谁。","夙昔同衾裯，中心怅有违。","何况万馀里，欲以见容辉。","君行忽已久，岁月不相守。","浮云蔽中天，凉风吹户牖。","忧来不可宣，浩叹成疢首。","黾勉加餐食，素心良不负。"]},{"t":"古意十二首 其二","f":"古风","c":["春夜一何永，置酒临高堂。","宾从列四座，广乐奏东厢。","清歌激流羽，琴瑟悲且良。","高张发促柱，哀音不可详。","沈吟欲何待，酌醴不盈觞。","人生天地间，辟彼隙驹光。","世路岂不怀，坎?多所伤。","乘时慎自保，为欢殊未央。"]},{"t":"古意十二首 其三","f":"五言古诗","c":["名都开大道，上有三重楼。","桂树罗棂牖，飞泉鸣道周。","盈盈楼上女，新妆丽且修。","当户弹鸣琴，皓齿发清讴。","一弹幽兰生，再弹白雪流。","游子在万里，邈焉无匹俦。","忽忽岁云晏，不知春与秋。","音稀和者寡，顾念徒怀忧。","游目送飞鸿，泪下不可收。"]},{"t":"古意十二首 其四","f":"五言古诗","c":["漫漫秋夜长，四壁凉风烈。","空庭流熠耀，高树号鶗鴂。","仰视玉绳垂，众星烂成列。","志士多悲心，忧来不可绝。","俯仰念昔游，流睇双龙阙。","同时有旧好，高举翔寥泬。","昔为雷与陈，今为秦与越。","永怀平生心，风尘非所阅。","麾手谢故人，长当从此决。"]},{"t":"古意十二首 其五","f":"五言古诗","c":["迢迢百尺楼，下俯长安道。","上有狭邪人，玉颜一何姣。","当户理琴歌，沉汉悲清晓。","本以倚门姿，委心结宴好。","良人逝不归，忧伤难独老。","顾匪姬与姜，悠悠亦何保。"]},{"t":"古意十二首 其六","f":"五言古诗","c":["湛湛江湘阯，萧萧芳树林。","褰华思有赠，馨香盈我襟。","美人渺千里，欲致无依因。","江寒风已厉，旷望愁人心。","且复置怀袖，聊以襞锦衾。"]},{"t":"古意十二首 其七","f":"古风","c":["瞻彼泰山岑，厥有孤生竹。","冉冉捎云霓，亭亭上岩谷。","凄凄岁欲寒，盈盈华色绿。","凉风振层阿，音响如哀玉。","高节抱贞心，可折不可曲。","顾见女萝枝，绸缪附乔木。","天霜降严威，零落成朴?。","所以君子心，邈然自结束。"]},{"t":"古意十二首 其八","f":"五言古诗","c":["我行秋江曲，睹彼蕙与兰。","紫茎发绿叶，秀色若可餐。","芳馨随风转，郁烈不能干。","采采不盈掬，思以遗所欢。","所欢在天杪，道路阻且难。","弃置委空谷，将随百卉残。","佩帏岂不充，无乃蒯与菅。","兰芳非有待，所佩诚足叹。"]},{"t":"古意十二首 其九","f":"五言古诗","c":["驱车东城道，言陟崇山阿。","茫茫顾四野，万木更条柯。","薄云出岩岫，绿水生微波。","四时更代谢，寒暑递相过。","日月化颜容，华发亦已多。","修名苦不早，秉烛嗟蹉跎。","览镜念平生，浩叹将如何。"]},{"t":"古意十二首 其十","f":"五言古诗","c":["暮秋多悲风，玄霜凝大泽。","驾言出行游，游彼重城北。","道旁何代丘，郁郁松与柏。","上有千里涂，下有万古宅。","不知王与侯，狐兔多遗迹。","人生匪金石，地上长如客。","新故递相寻，神巧不能测。","伤彼道旁子，矫性何迫隘。","宠利既内营，荣名多外饰。","交战汩衷和，鬒发日夜白。","胡不放情志，逍遥以永夕。"]},{"t":"古意十二首 其十一","f":"五言古诗","c":["猗顿慕营殖，日夜谋钱刀。","大贵多所伤，空令意气豪。","鼎鼎百年内，辟海流风涛。","忧煎伐天性，此生无已劳。","所以古达士，四海捐鸿毛。","安能为物役，长使心忉忉。","仙人羡门子，邈矣非吾曹。"]},{"t":"古意十二首 其十二","f":"五言古诗","c":["凉风戒秋节，岁事聿已暮。","蟋蟀吟前除，玄雁号空度。","委心怀所思，邈望关山路。","卒岁念无衣，为织机中素。","沉忧结梦魂，嬿婉如相遇。","离合在须臾，抚枕不知处。","良晤不可追，佳期多所误。","引领望明月，悲啼知天曙。"]},{"t":"馆课初入翰林自述","f":"五言古诗","c":["初日照高树，内苑归新凉。","苑中有芳桂，清芬闻我堂。","连云步七阁，绿简何焜煌。","虫书错绮绣，缃帙纷琳琅。","对此倚长叹，置卷发慨慷。","念本榆枋翼，早弄琼琚章。","迥心托千古，大雅规翱翔。","熙哉觏皇圣，文化浃埏荒。","眷言辟九畹，树此椒兰芳。","菉葹恧嘉植，偃蹇充其傍。","离离岂不玩，所需纫帏囊。","素修苟不植，何以答虞黄。","大猷渺玄漠，抽绪开微茫。","先民有高矩，祗奉思皇皇。","愿将袜线微，裁君云锦裳。","愿以径寸辉，垂君珩与璜。","良时不可失，荣名不可忘。","勉哉惜居诸，皇图巩未央。"]},{"t":"馆课代此日不再得","f":"五言古诗","c":["秋夜一何永，北斗横西楼。","客子不能寐，揽衣起行游。","俯视清水波，到海无停流。","仰观明月光，四五忽如钩。","惊风飘白驹，岁事聿已遒。","夸夫逐荣宠，日夜将焉求。","志士营世业，常怀千岁忧。","鹪鹩抢榆枋，鸿鹄摩天游。","托心各有谓，谁能识所由。","大禹古贤圣，寸阴矢远谋。","千载谅吾师，努力追芳犹。","不然日月迈，老大将安尤。","慎旃怀令图，勿为达士羞。"]},{"t":"馆课代迢迢牵牛星","f":"五言古诗","c":["漫漫银汉流，耿耿横天路。","盈盈河畔女，灿灿临长渡。","轧轧弄金梭，飒飒鸣如诉。","展转不成章，踯躅倚谁顾。","睆彼牵牛星，负轭何迟暮。","旧欢谅已陈，新约期难遇。","脉脉恨河梁，悠悠不得度。","揽佩坐徘徊，涕泗纷交鹜。"]},{"t":"馆课雪夜讲庄义","f":"五言古诗","c":["寒风吹朔雪，霏霏日云暮。","广庭列瑶阶，空林挺琼树。","有伟高堂上，宗工陈矩度。","抠衣侍绛帷，悬河启谆谕。","大道既具陈，玄史亦纷骛。","载阐南华篇，探彼环中趣。","卓哉漆园吏，齐论归逍遥。","葆光守天府，泰宇悬高标。","乘元御六气，九万恣扶摇。","解牛怅四顾，梦蝶纷飘飖。","大知一万物，众籁空调刁。","太息至人远，梦觉何寥寥。","蟪蛄与彭祖，物化竞一朝。","指马得真诠，心斗聿云消。","归去夜未艾，三尺方瀌瀌。","嘘㗳不得寐，隐几坐萧条。"]},{"t":"阁试抵璧捐珠","f":"五言古诗","c":["赵氏有良璧，连城不可索。","抱之会渑池，鼓瑟声何迫。","魏侯得明珠，径寸馀光泽。","照彼辚辚车，不阻函关轭。","哲王固有贵，所贵非瑰奇。","请观垂裳后，帝则昭良规。","四表谅已格，列辟咸师师。","犹惇玩物儆，惕若兴遐思。","晔晔结绿珍，丸石投空谷。","辉辉明月光，湮潭委鱼目。","岂不怀至宝，怀宝倾天禄。","宫中径寸珠，可易千人粟。","宫中盈尺璧，可筑千家屋。","珠饥不可食，毋自枵民腹。","玉寒不可衣，无裤歌声蹙。","所以唐虞理，光华烛海隩。","澹然宝无为，茅茨坐穆穆。"]},{"t":"馆课观兰亭修禊图","f":"五言古诗","c":["嘉辰属元已，迟晷流芳年。","邈思东堂会，遐想华林篇。","忽披曲水图，幅素渺绵连。","茂林蔚翠岭，华薄被芳田。","紫燕翔且嬉，丹英婉欲然。","斐云荫修竹，飞观开琼筵。","澄澄绿水波，萦曲流其前。","游娱有嘉客，冠服何翩翩。","朱轩解兰皋，罗坐临回川。","金卮乘波进，素俎激流还。","或沉翠纶没，比目惊重渊。","或揽绿藻柯，击棹浮青莲。","缓带既覆爵，或藉百卉眠。","亦或扼素腕，握管挥云笺。","中怀多忼慨，意态何蹁跹。","将无瑶池侣，夕饮昆崙天。","亦云山阴会，祓禊徵群贤。","风流迥千古，遗想托云烟。","至今兰亭下，曲水流潺潺。"]},{"t":"代作白头吟","f":"五言古诗","c":["蔚彼高树林，上有双鸣禽。","请君罢欢宴，听妾白头吟。","儿时同里居，追逐亭台下。","妾弄青丝绳，郎骑碧竹马。","十六始嫁君，花靥垂两鬟。","宛转郎左右，何时不可怜。","妾意尚疑新，郎心忽已旧。","不是故情疏，自是新恩厚。","玉台对明镜，红颜未应老。","炎天弃团扇，凉风何太早。","君如云中雁，妾如枝上花。","雁飞自有处，花落向谁家。","戚戚复戚戚，世事不可必。","但恨识君初，两心望如一。","含情欲谁语，揽涕背人流。","君心如明月，不照妾心愁。","道逢故家人，寄书予父母。","嫁女事贵人，不如田家妇。","田家虽苦辛，白头长相守。"]},{"t":"晋阳男子行","f":"五言古诗","c":["太原有男子，壮烈世所无。","身长九尺馀，白晰好眉须。","自负良家子，募作材官徒。","腰中辘轳剑，横击当路衢。","并州恶少年，见之伏且趋。","一朝览青镜，侘傺空堂隅。","三日不出户，忽然见彼姝。","绰绰夫容颜，盈盈玉雪肤。","蛾眉娟且长，高髻堕马梳。","脱我金锁甲，系我绣罗襦。","挂我白貂帽，珥我明月珠。","委心怀嬿婉，不惜健儿躯。","昔为云中鹄，今为水上凫。","昔者一何厉，常关十石弧。","今者何柔曼，巧笑倾城都。","仰视浮云驰，变化不须臾。","茫茫窥元运，玄黄无乃渝。","世人但云好，不必称丈夫。"]},{"t":"寄赵少虚先生四首 其一","f":"五言古诗","c":["空谷有佳人，素质明秋霜。","凌风拾翠羽，皎皎双明珰。","负薪日惨廪，怨此江路长。","红颜委中野，三叹以徬徨。","倾城难可再，一顾何茫茫。","念此不得寐，啸咤令心伤。"]},{"t":"寄赵少虚先生四首 其二","f":"五言古诗","c":["岱宗海上来，西蹴千峰倒。","虎岫何崔嵬，倬彼空城道。","下有啸歌客，翛然澹怀抱。","十年不下堂，腐心著玄草。","藻翰纵横流，百家如电扫。","如何鲜良觌，落落荒山老。","青葱松柏颜，敷华不在早。","君其爱景光，修名以为宝。"]},{"t":"寄赵少虚先生四首 其三","f":"五言古诗","c":["亲交匪一日，先子同衣裯。","渺质亦何知，忘年接胜游。","别君殊未久，忽复成三秋。","岁月何其迅，道路阻且周。","尺素远方来，慰我心烦忧。","一读再三叹，躧履下重楼。","玄霜弥大野，神物蟠深湫。","我心匪不念，悢悢无轻舟。"]},{"t":"寄赵少虚先生四首 其四","f":"五言古诗","c":["青鸟云中翔，遗我尺锦翰。","卷中有新赋，丽若金琅玕。","华藻耀朝日，悲啸曾云端。","俯身视陈宋，昂首接建安。","大雅久寥廓，文章忽欲殚。","夫子驼高驾，啾啾鸣玉銮。","举世徒徊徨，焉知若所观。","景行不可得，寤寐坐长叹。"]},{"t":"夜发杨柳青望天津海口","f":"五言古诗","c":["夕泊大堤口，雨气侵肌骨。","舟子不得停，鸣桨中夜发。","闻道海门近，惊栗不敢越。","渔灯隐遥浦，箫鼓声未歇。","人语烟中村，舟横沙上月。","岸接远流平，树入回波没。","不睹潮涨奇，安知溟渤阔。","喔喔天鸡鸣，东望苍烟裂。","霞生赤城峤，日出扶桑窟。","胧胧五云里，欲吐金银阙。","钟鼓罗宫廷，百辟修朝谒。","整衣顾我仆，神情坐超忽。"]},{"t":"送朱可大南还三首 其一","f":"五言古诗","c":["驱车渔阳坂，四野何苍苍。","我友驾言迈，去去天一方。","踟蹰一斗酒，相送渡河梁。","岂无弦歌曲，可以佐杯觞。","仰视浮云驰，苍白忽相望。","黄鹄一为别，悲鸣声正长。","何况同心子，当为参与商。","人生如浮梗，良会安可常。","俛仰感平生，岂不结中肠。","愿为双飞翼，送子以翱翔。"]},{"t":"送朱可大南还三首 其二","f":"五言古诗","c":["相思郁以纡，我怀多苦辛。","苦辛将何道，念此平生亲。","总角从君游，奄忽二十春。","岁月一何迫，白日如飙尘。","恩深不可报，情至日以新。","两心托金石，何乃慕雷陈。","风波一相失，怨彼江路津。","日长苦道远，缱绻竟不申。","岂无里巷游，邈若胡与秦。","久要苟不替，燕越如比邻。","何必岐路侧，空为儿女仁。"]},{"t":"送朱可大南还三首 其三","f":"五言古诗","c":["步出燕东门，海月聿已晓。","班马萧萧鸣，流猋来远道。","江湖深且长，南望令人老。","感彼荆卿徒，烈风世所少。","怀恩不返顾，长虹日中缟。","平原三千士，风期一旦扫。","咄嗟世上儿，论交何草草。","愿持岁寒心，皓首长相保。"]},{"t":"东海有贞妇为冯太安人赋","f":"五言古诗","c":["东海有贞妇，烈志青云齐。","本家辽水上，远嫁海门西。","夫君璠玙器，射策黄金墀。","伯氏籍天府，两叔印累累。","何意苍梧云，飘飘不复返。","日落湘水深，泪向南天远。","程婴存赵祀，磊磊万古声。","徒死亦何为，雪涕出瑶京。","故家千里道，郁悒令人老。","不作逐风萍，宁为负霜草。","秋闺素机冷，露夜青灯微。","生儿不识父，泣尽负儿衣。","雪中千仞松，岁事聿已寒。","其下无俗植，所植桂与兰。","兰苕何青青，桂华自成树。","上有一翠鸟，飞向天门去。","陈书叫九关，一读一潺湲。","此事不可道，酸辛感圣颜。","锦函天上来，吹落五云表。","蜺衣何鲜泽，凤吹转绵邈。","儿跪长叹息，愿母加餐食。","日月有亏盈，荣名不可极。"]},{"t":"送太常贾卿册封亲藩","f":"五言古诗","c":["北斗挂城阙，河汉东南流。","我友怅明发，驾言远行游。","玉节耀横轭，黄金饰马头。","悠悠涉河济，去去登旧丘。","前驱二千石，逢迎王与侯。","念子何当返，寒暑聿云周。","河梁临往路，顾念今人忧。","有酒不满觞，为我且复留。","匪无陌上交，其如道不谋。","眷言在同志，何以喻绸缪。"]},{"t":"书吴门韩封君友兰卷二首 其一","f":"五言古诗","c":["南国有逸叟，蜚遁吴山阿。","畏荣避轩冕，韬景耽云萝。","谁结同心契，揽此秋兰柯。","契合在空谷，纫佩交如何。","月出鼓鸣琴，一奏郢人歌。","彼美握香子，南陔咏方多。"]},{"t":"书吴门韩封君友兰卷二首 其二","f":"五言古诗","c":["兰苕何猗猗，结根在秋坂。","皓露夕以零，靡迤风自远。","幽人秉冲尚，眷言树九畹。","匪资服媚荣，将以华岁晚。","生不当门户，馀香流茂苑。","郁彼背堂萱，相对方婉婉。","持此永年寿，愿言加餐饭。"]},{"t":"春日过李宛平于美","f":"古风","c":["春风历皇邑，宫草萋其绿。","良辰感客心，行游北城曲。","有美怀绂人，卧阁方避俗。","开尊华轩夕，延我酌?醁。","散帙有馀览，瑩情无近瞩。","纵横今古谈，日宴未云足。","嘉会匪有期，深衷一何笃。","眷兹一笑欢，宿心谐所欲。","相彼双阙间，涂轨多局促。","道旁磬折子，胡为自结束。","兰香匪为人，鹄白不日浴。","泠然物外赏，愿言偕芳躅。"]},{"t":"书楚刘封君乡贤卷","f":"五言古诗","c":["昔有灌园者，忘机不忘力。","邈彼鹿门人，躬耕不可即。","此风一以渺，韦素多雕饰。","皇皇頫仰谋，日夜靡知息。","何哉楚江父，身隐名独植。","入敦仁孝模，出为里闬式。","不惜千金装，而将一诺亟。","中堂树兰桂，芳飙闻四域。","生不学宫游，没从学宫食。","诸生奉卮豆，长吏匡且策。","贵贱等隙尘，尸祝无终极。","同时圭绂儿，名氏谁复识。"]},{"t":"送朱金庭李棠轩二太史奉使册封","f":"五言古诗","c":["圣朝睦藩服，策命临侯王。","近臣发皇邑，于役天一方。","行行日以迫，相送上河梁。","清葭戾中野，班马鸣路旁。","远望长风起，夕雨下沾裳。","乐饮未及釂，仆御已严装。","征人怀远路，游子望故乡。","停舟问沧海，驱马过泾阳。","君如双黄鹄，各自东西翔。","我如晨明月，望彼参与商。","托交固金石，别促会当长。","愿言整夙驾，览风陈国章。"]},{"t":"送于子冲上泽州太守二首 其一","f":"五言古诗","c":["凉秋聿云暮，烈风飘人衣。","念子远行迈，整驾出郊畿。","徬徨以中夜，起视明星微。","出祖城南隅，握手不能归。","孤鸿号中野，木叶纵横飞。","聚散一如此，素心亦已违。","惟有双鱼札，慰我长渴饥。"]},{"t":"送于子冲上泽州太守二首 其二","f":"五言古诗","c":["古者不可作，交道久茫茫。","念我二三子，总角共翱翔。","欢衷如日月，别思苦参商。","五马向路驰，俛仰情内伤。","问子今何适，驱车陟太行。","曲坂造云日，溪谷深且长。","人情多崄巇，世路固难量。","勉哉怀令德，叱驭有遗芳。"]},{"t":"送赵瀫阳殿读上广东宪副","f":"五言古诗","c":["凛凛岁事寒，重云蔽城阙。","游子欲何之，驱车适南越。","南越万馀里，江深安可涉。","鸢堕五溪云，猿号修岭月。","耿耿烈士颜，世路无工拙。","况握黄金章，名在诸侯列。","我皇眷迩臣，赐环不赐玦。","惟是同心人，欢情中道缺。","踟蹰在广路，悢悢不能诀。","砥如水中石，皎如山上雪。","直道谅已难，忧心未云掇。","吾将从此辞，长歌栖林樾。"]},{"t":"题云间林谏议重寿卷","f":"五言古诗","c":["云间有逸叟，德声穆若兰。","缅昔谐良觏，登堂揖鹖冠。","肌肤瑩玉云，两颊渥如丹。","大饮呼五白，清夜不知阑。","一往谢朝市，戢景吴江湍。","涉海掇瑶草，临流倚翠竿。","借问此何为，言奉北堂欢。","北堂有寿母，百岁以盘桓。","晨羞沆瀣滓，夕进雕胡盘。","老人为儿啼，七十戏堂端。","殊事闻远近，眇然使我叹。","鱼翼不可并，纯祜世所难。","况复青云客，为时麟与鸾。","两世有宠命，服之吉且安。","飘飘千馀岁，娱乐未云殚。"]},{"t":"杂诗八首 其一","f":"五言古诗","c":["蔚彼蒿下田，中有双黄爵。","五步逢一饮，十步逢一啄。","仰见鸿鹄游，六翮翔寥廓。","岂不愿从之，道远将安托。","天寒多野风，四面张罦络。","苏合作弹丸，历历空中落。","鼎俎苟不干，蒿下亦已乐。"]},{"t":"杂诗八首 其二","f":"五言古诗","c":["陟彼高台上，四顾临郊畿。","下有清冷水，寒流日夜微。","何来孤鸣雁，啸匹空中飞。","天风一以厉，烈烈吹毛衣。","稻粱既不慕，葭菼亦已稀。","茫茫在中野，日暮将安归。","我欲负尔去，惜哉羽翼违。","长吟望云汉，祗使心劳悲。"]},{"t":"杂诗八首 其三","f":"五言古诗","c":["巫山不为高，湘水不为深。","结交宁在广，所贵相知心。","朝云既晻霭，暮雨复涔淫。","顷刻更变化，安知阳与阴。","交情苟如此，世轨良岖嵚。","将邀羡门子，天路相追寻。"]},{"t":"杂诗八首 其五","f":"五言古诗","c":["所思在何许，在彼沅与湘。","何以问遗之，解此双明珰。","葺兰结菌桂，室宇何芬香。","佳人殊不至，望望天南方。","烟波弄白日，容与凌风翔。","江空岁云晏，零露成朝霜。","不忍弃所宝，且复自徬徨。","端居有馀玩，思远徒劳伤。"]},{"t":"杂诗八首 其七","f":"五言古诗","c":["名都有士女，居在城南端。","前庭树桐梓，后阁罗苕兰。","齐纨为上襦，鲁缟为中单。","援琴理清曲，惠声穆且閒。","惜哉岁不与，憔悴空江湍。","芳华一以谢，烈心不可干。","蹇修为谁使，遗我双瑜环。","朱衣从千骑，宁可一为欢。","闻此窃自叹，立身诚独难。","贵亦各有慕，贱亦各有安。","岂伊霜雪质，能睎桃李颜。","敛襟谢媒氏，自下重门关。"]},{"t":"饮鲍庄泉石淙","f":"五言古诗","c":["行歌涉沂泗，暂偕鱼鸟欢。","碧草夹修逵，炎风吹我冠。","道旁有嘉树，四月秋声寒。","俯见石淙水，突出成潺湲。","清虚涵云日，滴沥锵瑶环。","主人有逸兴，为我陈盂盘。","解衣坐鱼笱，挥手截素湍。","瑩彻青玉镜，照我颜色丹。","泠泠漱琼液，飞沫尽可餐。","祓洛未为盛，临濠惬所观。","迟晖速短炬，走海无停澜。","能将双蓬鬓，逐彼两跳丸。","长谣望前路，于此且盘桓。"]},{"t":"石窦泉","f":"五言古诗","c":["石窦泉异哉，此窍何年凿。","湓流鸣地底，砅岩成大壑。","骇浪悬且腾，惊湍飞复薄。","歘如玉壶倒，靃似春雷跃。","片片广陵涛，洒作霜天鹤。","增浇旋石濑，猗靡龙鳞络。","淈汩入回渊，欲去复疑却。","孟公酷好奇，取瓢承濆瀑。","我亦一俯首，慡然心魄愕。","四月衣袂寒，共谓秋霜落。","嗟哉造化工，于此固橐籥。"]},{"t":"从泗上归宿杜太学庄舍","f":"五言古诗","c":["暮从川上来，两袂涵清辉。","回首睇泉皋，苍茫紫烟飞。","相挈入村舍，解鞍控板扉。","牛羊深巷入，鸡犬空墙依。","中庭有花树，郁郁何葳蕤。","山月在帘牖，星河亦已稀。","宛然林壑姿，顾视朝市非。","主人有旨酒，行吟聊共挥。","避世岂在远，此中可忘归。"]},{"t":"登峄山绝顶有怀贾大卿石葵","f":"五言古诗","c":["兹山一何高，岱宗青未极。","峻削玉芙蓉，去天不盈尺。","我来啸良偶，杖策探奇迹。","窈窕寻幽壑，岖嵚扪绝壁。","俛首瞰虹霓，四望寥天一。","重阴万里生，游目忽不怿。","睇彼东南陬，山川含奥邑。","沧浪如衣带，半挂青岩色。","中有素心人，寤歌方宴息。","欲往一相觌，其如修路隔。","据彼孤桐枝，临此万仞石。","愿因天风吹，达我心相忆。","曲终弦欲绝，抚琴长叹息。"]},{"t":"曝经石","f":"五言古诗","c":["朝下天门关，夕憩曝经石。","此石自何年，斜倚万仞壁。","叠嶂洒飞泉，匹练百馀尺。","水底玉篆分，了然成鸟迹。","其文乃上古，读之茫不识。","谁参雪窦禅，永示金仙迹。","渌池低宝树，宛见祥河出。","兀坐听潮音，洗耳心方寂。"]},{"t":"送范涵虚太史入闽","f":"五言古诗","c":["卧病谢人徒，块焉处寥廓。","客从何方来，缄书投我橐。","开缄见故人，我心忽不乐。","问子今何适，行行入瓯骆。","瓯骆日南陬，思客春梅落。","冉冉江中云，迢迢海上郭。","太息念我曹，十载依铜爵。","云胡乖羽翮，南北成离索。","惊飙拂林树，洪流奔大壑。","凤栖无静柯，龙游安所托。","闻君有良剑，旧在丰城凿。","佩之入山海，不能逢不若。","宝此千金质，百鍊焉能铄。","今我方无为，草玄惟寂寞。"]},{"t":"寄张洪阳殿读豫章四首 其一","f":"五言古诗","c":["月出何皎皎，照我堂南端。","愁人苦难夜，踯躅起长叹。","长叹将何思，念我平生欢。","江湖万馀里，道路阻且难。","孤雁过我庭，悲鸣风正寒。","愿传尺素书，报尔青琅玕。","书成在怀袖，涕下不能看。"]},{"t":"寄张洪阳殿读豫章四首 其二","f":"五言古诗","c":["昔我从良友，翩然游帝傍。","有如双黄鹄，厉翮起高翔。","风波一相失，天路何阻长。","三秋为一日，噭噭遥相望。","周周啸俦匹，衔羽正徬徨。","麋鹿索其群，孤号在莽苍。","咄咄久沉吟，为君心内伤。"]},{"t":"寄张洪阳殿读豫章四首 其三","f":"五言古诗","c":["海上有浮云，郁郁双龙阙。","何意回飙吹，翳此瑶台月。","风雨忽冥冥，九关不可谒。","直木忌为材，甘井常先竭。","人生百年内，鼎鼎何超忽。","日月跳两丸，谁鍊黄金骨。","富贵亦何为，芳华有时歇。","寄声问所钦，好食山中蕨。"]},{"t":"寄张洪阳殿读豫章四首 其四","f":"五言古诗","c":["王阳方结绶，贡禹亦弹冠。","虞卿为其友，解印去邯郸。","千金重然诺，百折不辞艰。","穷达相与俱，飞沈岂异端。","末世逐荣宠，斯道亦已难。","袅彼女萝枝，缠绵诚可叹。","君为千尺松，我为一握兰。","兰松不相结，惟以共岁寒。"]},{"t":"寄习豫南太史闽中二首 其一","f":"五言古诗","c":["飒飒双鸣鹤，集彼玉树林。","凌风振逸响，各有九霄心。","如何乖羽翼，形影互飞沈。","君滞炎海上，我栖梁父阴。","伫立望川梁，江路迥且深。","岂无一札书，飞鸟不怀音。","眷彼越乡叹，感此年岁侵。","一为同心谣，涕下沾衣襟。"]},{"t":"寄习豫南太史闽中二首 其二","f":"古风","c":["日夕登高台，悠悠望南海。","南海不可从，万里阴云霭。","念我同心人，留滞方何在。","一出咸阳门，岁事数已改。","眇眇睇空江，晔晔生兰?。","日晏江水寒，美人殊不采。","如何桃李颜，含笑扬光彩。","保尔岁寒心，芳华自晻霭。"]},{"t":"送田钟台宫谕视篆南都二首 其一","f":"五言古诗","c":["东风入上阑，众草靡靡绿。","有客远行游，倚舟河水曲。","河水深且长，帆樯千里瞩。","金陵佳丽都，洵美多旧俗。","石渠对图史，吏隐谐所欲。","奈何卑栖子，风尘独踯躅。","缘木谅难工，积薪空自束。","极眺远行云，愿作双黄鹄。"]},{"t":"送田钟台宫谕视篆南都二首 其二","f":"五言古诗","c":["别日一何久，会日一何难。","浮云满天地，游子路间关。","为君置斗酒，四座惨无欢。","仰视明星辉，俯观沟水澜。","聚散谅无准，浮沈宁足叹。","少年多意气，碌碌非所安。","愿敦久要谊，相期以岁寒。"]},{"t":"夏日邀朱令君饮楮村石淙","f":"五言古诗","c":["山公在襄阳，日醉习池月。","歌声起铜鞮，至今名未歇。","我侯有仙标，邈与世人绝。","抱琴出邑郭，来采石淙蕨。","石淙何潺湲，流水喷玉屑。","萧飒洞壑鸣，五月寒人骨。","方塘一片石，混沌本无缺。","自从庖羲来，画作赤文裂。","远望峡水流，犹似天山雪。","此中有真赏，欲语不可说。","扫苔卧石坪，山月归可挈。"]},{"t":"七月十五夜同朱令君吴文学汎舟北溪","f":"五言古诗","c":["抱病卧江海，屡经故国秋。","闭门览群动，自得静者谋。","仙宰有逸兴，强我北渚游。","时值七月望，寒蝉叫新秋。","槐柳夹修岸，山鸟鸣啁啾。","搴帷望孤屿，回桡背古丘。","歌声上云汉，玉管吹汀洲。","须臾绿烟灭，好月尊前浮。","皎如瑶台镜，泻作金波流。","仙人垂素足，桂树枝相樛。","扫石布瑶斝，弄水惊素鸥。","风飘寒梧响，露下莎鸡愁。","清景不可奈，中夜仍淹留。","归路怅明发，此欢焉可求。"]},{"t":"登华不注绝顶","f":"五言古诗","c":["齐都多名山，兹山独邈绝。","中峰带湖水，华顶留寒雪。","一枝玉芙蓉，翠黛若可掇。","我来凌青冥，倚啸紫云裂。","岚气互氤氲，波光半明灭。","平野碧烟浮，长堤春树没。","流览望扶桑，欲见蓬莱阙。","云间逢真人，举手问宝诀。","泠然紫芝想，了与红尘别。","佳游难再得，梦想何可辍。"]},{"t":"泉上","f":"五言律诗","c":["偶坐泉上石，暂与人境隔。","天光涵清虚，水木有佳色。","心对游鱼閒，目送孤云白。","凉飙山际生，微雨天欲夕。"]},{"t":"送杨庐山户部左迁淮阳","f":"古风","c":["华月出高牖，新猋激广轩。","斗酒酌良夜，君怀胡不欢。","昔艺名城树，今握画省兰。","作吏既彊项，为郎亦苦颜。","如何流云景，奄忽无定端。","言从淮海至，又客淮海?。","掺袂即往路，永啸涕汍澜。","騄骥志千里，松柏厉岁寒。","壮心苟不渝，坎?亦何叹。","去矣崇令图，久要慎莫谖。"]},{"t":"寿四明沈封君九十","f":"五言古诗","c":["林类不知隐，行吟聊带索。","伏生老嗜经，于道为糟粕。","何如海上闾，三老同赐爵。","上老冰雪肌，下老颜如渥。","中老正敷愉，九十骨矍铄。","释智绝町畦，纵心游恬漠。","有子汉列卿，名在石渠阁。","洗沐一来归，六传欢城郭。","玉笈绿绨封，宝驷黄金络。","华旌既绥绥，綟绶何若若。","上堂问起居，跪进丹丘药。","群从歘相从，翩如鸾与鹤。","仙气结云霞，君恩散林壑。","翁其爱玉体，延年千岁乐。"]},{"t":"题王母图寿新建张太夫人","f":"五言古诗","c":["西山一何高，上有列仙馆。","阿母几何年，皬然霜发短。","丹室搆琼英，霞衣出火浣。","上元受宝诀，双成吸玉管。","俯视瑶水波，几度清且浅。","青鸟云中遨，飞鸣正睍睆。","玉函堕真图，仙气人间满。","侍中岁星魂，燕喜何衎衎。","取彼玗琪实，跪进车渠盌。","若木晓晖长，桃花春气缓。","一奏玄云谣，永欢阆风苑。"]},{"t":"哭弟三首 其一","f":"五言古诗","c":["严霜下前除，朔风凄以烈。","今夕复何夕，同生成永别。","疾疢能几时，音容忽已灭。","稚子号中闺，阿母啼成血。","有兄滞天隅，之死不及诀。","仰视云间鸿，呼群中断绝。","俯观庭中树，琼枝已再折。","永啸涕如雨，沈忧鬓成雪。","岂不怀大观，至情畴能掇。"]},{"t":"哭弟三首 其二","f":"楚辞体","c":["天地有大运，物化莽茫茫。","蟪蛄一何促，彭聃一何长。","摧心叹吾弟，茂龄成夭伤。","明珠沉碧海，神剑蚀精光。","念子平生日，沈痛结中肠。","俎几设虚奠，旨酒盈素觞。","魂兮无不适，当复来我旁。","屏营望南阜，揽涕下沾裳。"]},{"t":"哭弟三首 其三","f":"五言古诗","c":["昔我过里门，诀尔衢路侧。","操袂对宾友，悲风声正迫。","犹言生离苦，知作穷泉隔。","含意恨未伸，生死各脉脉。","眷怀握手地，心折秋山陌。","人生一世间，忽如逆旅客。","谁能以蘧庐，噭噭号真宅。","三复桑户吟，一哀聊自释。"]},{"t":"拟门有万里客行送胡孝廉孟韬孟韬为其先君求志远走长安云","f":"五言古诗","c":["门有万里客，摄衣造我堂。","风尘著眉目，车马倚道傍。","问子今何为，执手涕沾裳。","自隐匡山隅，承欢乐且康。","三复南陔咏，旋废蓼莪章。","饮棬悲鸣木，陟岵悽严霜。","日月既不处，遗德亦未忘。","幽兰委涧沚，无风谁为扬。","愿子片石书，永我寸草肠。","以兹冒炎暑，屣履涉江湘。","我闻再三叹，俛仰以徬徨。","亦有明发怀，感此中情伤。","念君苦行役，且复尽一觞。","修词谅非任，其敢沫馀芳。","君怀双虹剑，耿耿明星光。","一当万乘主，为宝诚难量。","如何慕皋鱼，空为孺子怆。","归其保玉体，天路以翱翔。"]},{"t":"题张中丞傅野万玉山房卷","f":"五言古诗","c":["吾慕竹溪逸，爱此竹树林。","悠然展幅素，绿玉何萧森。","万竿挺寒翠，千亩横素阴。","亦有高节士，结庐江水浔。","夹池乱橘柚，拂槛锵球琳。","讵开蒋诩径，但抚山公琴。","朅来仙省游，双管耀华簪。","截彼虬龙簳，写兹鷟鸑音。","无为眷荆渚，寤宿增遐心。","此君在几席，可以澹尘襟。","念本孤生植，冉冉泰山岑。","愿为琅玕赠，徙倚一长吟。"]},{"t":"送王宫庶师竹请告南旋","f":"五言古诗","c":["凛凛岁云晏，雨雪弥中林。","念子即往路，河梁阻且深。","廿年事明主，谓比双南金。","国恩岂不怀，胡然有远心。","东皋解悬耜，中谷发鸣琴。","松萝夹户牖，山水流玉音。","何如长安游，舆马日骎骎。","素衣一以染，华发又欲侵。","蹇予鲁狂生，于今亦越吟。","送尔结长想，极目青山岑。"]},{"t":"贞妇吟为长安潘氏母赋","f":"五言古诗","c":["中庭何所有，艺彼竹与兰。","竹兰被户牖，玉树罗堂端。","天风西北吹，众香越以繁。","借问此何居，言之辛且酸。","本家东海上，羁旅在长安。","良人早见背，遗婴亦已单。","秉心在冰檗，谁能惜盛颜。","杨枝耀春华，柏枝凌岁寒。","岂无青阳辉，良非我所观。","补衣为儿襦，辍食为儿餐。","儿从长者游，断发佐儿欢。","以此持门户，幸不堕衣冠。","我闻慕且悲，此义世所难。","共姜名不沫，文母节未殚。","试为贞妇吟，一倡再三叹。"]},{"t":"上外舅秦翁生辰","f":"五言古诗","c":["近亲同里门，远亲异乡邑。","何况舅甥欢，津梁千里隔。","宿昔忝乘龙，门阑在咫尺。","阿翁豪且贤，雅称闾右室。","迟暮无它男，所托惟女息。","廿年随宦游，庭阶亦寥寂。","中岁鞠两雏，恩勤瘁心力。","女儿在襁褓，男儿操纸笔。","翁媪岁时来，抚摩均自出。","伊予久怀归，蹉跎年岁逼。","恻怆骨肉情，含辛念非一。","两雏忽相牵，长跪绕我膝。","届兹中元秋，阿翁弧矢日。","宾从列中堂，杯觞行络绎。","儿母在天隅，间阔增烦悒。","请耶篹片词，寄我离孙臆。","我闻两雏言，吟叹心戚戚。","孩抱亦何知，母慈良可识。","翁今七十三，媪亦过七十。","丹颜未全改，缜发但稍白。","矫矫矍铄姿，少壮或不及。","海桑千仞枝，池桃千岁实。","郁郁岱山松，累累丈人石。","持此寿翁媪，永列丹台籍。","时和复年丰，娱乐加餐食。","早晚归山樊，聚首多夷怿。","挥翰为长歌，歌阕情未极。"]},{"t":"冬夜方胥成过访","f":"五言古诗","c":["玄云结重阴，北风凄且寒。","端居寡言宴，惜此芳岁阑。","客从远方来，入门正其冠。","解装出所有，赠我青琅玕。","其物有光耀，握之感且叹。","华镫列堂隅，酌醴羞盘餐。","片言意气合，昵若平生驩。","风雅久沦替，学海多狂澜。","众目徒荧荧，谁为旷古观。","问君四方志，前路何漫漫。","时俗贱文史，世事多艰难。","勉哉树芳轨，荣名不可殚。"]},{"t":"春日寄陈从训","f":"五言古诗","c":["上日临高台，平堤草已绿。","感物动我思，骋望春江曲。","春江不可涉，幽人在空谷。","葺彼桂兰宇，好此萝薜服。","舒啸穆鸾凰，结佩锵琼玉。","居依戴颙宅，游踵焦君躅。","岂无席上珍，风尘匪所欲。","一为倾盖言，相期违世俗。","十年旷良觌，念子心烦促。","寤寐岂不谐，绵道如川陆。","悠悠河上鱼，渺渺云中鹄。","缅怀一札书，徒勤万里目。","眷言崇令名，加餐以为祝。"]},{"t":"题崔仲素郡丞抚松亭","f":"五言古诗","c":["藐彼海上山，云气何寥廓。","中有孤丘亭，苍茫临大壑。","约壁荃与兰，涂材匪丹雘。","亭端亦何有，长松双落落。","下根盘虬龙，上干栖鸾鹤。","泠风无时休，秋霜被已薄。","主人北州牧，解组耽恬漠。","亭中谐寤言，松下恣盘礴。","月出鼓鸣琴，永夜声萧索。","载咏彭泽吟，古今偕至乐。","顾见泰山隅，五株良有托。","万古称秦官，贞心无乃怍。","请移植此亭，为假山中爵。","食彼偓佺伦，共鍊延年药。"]},{"t":"閒居述怀","f":"五言古诗","c":["白日御飙轮，西下何其速。","河流东到海，日夜波声蹴。","人生正百年，荣华不满目。","君今亦胡为，沈吟长蹢躅。","北里有良友，南邻多旧族。","相羊山水间，声若丝与竹。","斗酒可相娱，极宴适所欲。","何必宛洛游，裘马相徵逐。","制命固在我，无为自局促。"]},{"t":"新春独坐有念","f":"五言古诗","c":["青阳布岁和，鼓籥回嘉律。","如何后皇心，条风犹惨慄。","七日不出门，块焉坐斗室。","咄嗟顾庭除，感念端非一。","岂无闾巷欢，亦多朝市匹。","白首尽如新，谁为胶与漆。","避世良所欣，延龄岂有术。","人生陶大块，飘如驹过隙。","苟欲役风尘，何物关名实。","旨哉盈觞酒，优游以永日。"]},{"t":"元夕家宴示诸子侄","f":"五言古诗","c":["端居逢节序，中情鲜所欢。","常华既云瘁，谷风良不完。","佳夕谢宾徒，且复陈盘餐。","丱弁既列侍，孩抱亦团圞。","尊酒日云晏，华镫烂以繁。","九枝兰桂烬，四照玻瓈丹。","笑语不知疲，迢迢清夜阑。","永怀家门念，俛仰固多端。","依栖幸不远，蕃硕已可观。","慎旃各努力，保作诚为难。"]},{"t":"泰山对酒赠冯琢吾少宰","f":"五言古诗","c":["晨登泰山坂，四顾何茫茫。","浮云蔽若木，旭日开扶桑。","阴晴倏忽变，登顿多苍黄。","长风四面至，烈烈吹我裳。","客子驾言迈，行行陟帝乡。","前有一尊酒，临此万仞冈。","绸缪亦何念，展转不尽觞。","结交眷金石，怅别怀参商。","高举步万里，游目涉四荒。","其雨怨杲日，若济思舟航。","努力事明主，庶令泰道昌。"]},{"t":"灵岩送别琢吾","f":"五言古诗","c":["山馆夜不寐，起视明星微。","北斗挂楹牖，天河垂欲晞。","客行一何遽，申旦从此辞。","十年聊一晤，此后长相思。","斗酒不得醉，涕下沾裳衣。","君如山上云，作雨弥天施。","我如涧中石，抱此不化姿。","浮沈各有以，本自相因依。","寸心苟不渝，安在合与离。","愿言保黄发，待子成功归。"]},{"t":"寄题朱金庭宗伯逍遥楼一首","f":"五言古诗","c":["我有同声偶，宛彼天南隅。","十年旷色笑，万里违音书。","坐逢越方人，跪问今何如。","方修南华义，闭迹重楼居。","重楼何缥缈，回架名山隅。","星月宿雕槛，虹霞带绮疏。","云门列遥障，剡水周前渠。","冥韬寡谈宴，遐眺多讴歈。","违哉旷士怀，自执环中枢。","鹪鴳栖非隘，鹍鲸润岂馀。","至游苟有托，焉适非吾庐。","君今息溟海，吾亦耽枋榆。","室遐人尚迩，年往意未疏。","恨无双飞翼，径度三山闾。","永言鬯玄旨，婆娑以自虞。"]},{"t":"蜀山湖游太宰吴介肃公精舍感述","f":"五言古诗","c":["渺渺汎平湖，亭亭望孤屿。","秋风莽萧瑟，川光澹容与。","昔有素心人，此焉耽宴处。","下帷探道帙，闭关谢尘侣。","狎从鸥鸟嬉，遐慕鸿鹄举。","国卿岂不崇，视若鸢与鼠。","遗构今尚存，高芬畴克旅。","白云去不还，寒山静无语。","景行不可得，回桡徒延伫。"]},{"t":"寿周燕川封君为司理周君作","f":"五言古诗","c":["逖彼潇湘水，北流云梦阴。","钟灵孕华阅，宝树何萧森。","长公楚山玉，仲甫荆南金。","叔君何所韫，葆此席上琛。","力田笑株守，谈经轶陆沈。","甫志蓝田璧，旋鸣单父琴。","政声弥汉沔，士誉播江灊。","自振双凫羽，还成五桂林。","名郎负奇采，天阙彯华簪。","执法奎娄野，扬芬岱岳岑。","奏牍荷殊宠，陟岵劳远心。","秦云睇庵薆，蜀道歌岖嵚。","愿言蕲寿祉，酌斗思愔愔。","长跪再有献，所献非球琳。","玄霜十洲采，瑶草三山寻。","服此颜如渥，无使华发侵。","汉水谁谓广，湘水谁谓深。","聊挹沧溟润，流君世泽吟。"]},{"t":"冬日得冯少宰用韫书问寄谢一首","f":"五言古诗","c":["北风一以厉，雨雪何漫漫。","江湖莽浩淼，周道阻且艰。","故人在千里，寄我双罗纨。","织成不惜远，为念衣裳单。","感兹平生意，提挈再三叹。","别离未觉久，年光忽欲阑。","幸有裘与褐，可以禦岁寒。","七章匪不丽，所适燠且安。","卷衣置箧笥，怊怅不能谖。"]},{"t":"题睢阳鲁夫人贞寿卷","f":"五言古诗","c":["伯姬鲁国女，作嫔仪宋宫。","委身殉烈焰，名与天壤终。","伊谁嗣良轨，请歌贞媛风。","淑灵禀鸿造，典训开儒宗。","生年汶阳里，远嫁梁园东。","君子秉明谊，德心协所崇。","瑟琴谐雅调，环琯多庄容。","嬿婉未及竟，陨弃号苍穹。","秋霜激素质，朝日明丹衷。","和丸佐儿诵，停杼代儿舂。","日永非在夏，宵长非在冬。","奄忽岁年迈，拮据堂构隆。","永怀背堂念，不受清台封。","贞如幽涧柏，含翠凌高空。","皎如旋渊玉，吐耀干长虹。","母师飨嘉号，女史图芳踪。","一为凫鹄叹，感慕何时穷。"]},{"t":"慰宗侯玄同契丈居庐","f":"五言古诗","c":["端居岁云晏，雨雪涂周行。","寒夜不得寐，起坐思天方。","天方有良友，皎若圭与璋。","间者阔闻问，匪谓殊津梁。","方修倚庐礼，自废蓼莪章。","天风号林树，乌鸟鸣声长。","曾闵既人纪，皋连亦国良。","吾邦贤圣里，风轨敦侯王。","愿言一往慰，我马摧以黄。","居诸谅已迅，霜露多悽怆。","光前固有道，孺慕徒为伤。","君其勉餐食，锡类方未央。"]},{"t":"谢少傅蛟门沈公书问","f":"五言古诗","c":["徙倚步中庭，仰见飞黄鹄。","黄鹄自何方，遗我一尺牍。","开牍见所钦，慰借温如玉。","为寄双织成，无非锦与縠。","卷书置怀袖，感叹不能读。","匪无远道思，畏此川涂曲。","间别十馀年，故情犹尔笃。","欲以报绸缪，山云不可掬。","天道有盈虚，人情多蹢躅。","狐白岂不珍，褐衣亦已燠。","苟存岁寒心，不在违所欲。"]},{"t":"题吴母贞裕卷二首 其一","f":"五言古诗","c":["卫姜植特操，邹孟秉义方。","贞哉延陵母，旷古嗣遗芳。","素衷矢皎日，烈质凝秋霜。","笄总奉君子，瑟琴静且良。","一为终天诀，掩镜销铅妆。","晨炊井床冻，夜绩釭辉凉。","中庭长琼树，复汎崇兰光。","璇室有彤管，名与星岳长。","永言歌黄鹄，三叹沾人裳。"]},{"t":"题吴母贞裕卷二首 其二","f":"五言古诗","c":["女贞既有树，女清亦有台。","不如母师号，云汉天昭回。","丹泥北堂耀，璇榜深闳开。","表闾与锡命，流耀江海隈。","子为簪笔史，倚柱称瑰材。","孙为含香吏，抗章胡壮哉。","家声一以振，母节益以恢。","正气凛千古，荣名肃九垓。","歌言树令轨，以拯流风颓。"]},{"t":"瑞谷谣为郡伯刘公赋","f":"五言古诗","c":["我服汶阳陇，穫彼麻与菽。","道逢拾穗人，轩眉行鼓腹。","问言何所钦，吾邦有仁牧。","濊泽若雨旸，庶徵协寒燠。","芃芃万宝登，穰穰三秋熟。","旧闻嘉禾名，今见嘉禾蔟。","一茎二三岐，多者至五六。","异亩荐周塍，合颖标唐箓。","惠露洒琼皋，条风披广麓。","上充德政符，下锡氓庶福。","不谓憔悴馀，欢声洽比屋。","我闻三叹言，地宝一何渥。","有渊不产珠，有田不产玉。","固知圣后心，所贵惟民谷。","愿以鲁史书，仰佐豳风祝。","昊贶感皇仁，流膏丰海隩。"]},{"t":"题郑双峰先生乡贤卷册","f":"五言古诗","c":["谷口有逸民，秉耒在岩穴。","儒宗遁北海，牧伯钦高节。","二公世所师，岂伊青紫列。","谁者嗣流光，华胄栖东越。","握椠谢公车，服陇耽邮畷。","独行州里孚，笃谊神明彻。","生不采芹游，没从舍菜醊。","典礼旷无前，清芬耿不灭。","神报一何延，永锡钟遗厥。","亦有公衮褒，金书貤象阙。","种木百年阴，种德百年烈。","末俗徒皇皇，芳规胡不晰。"]},{"t":"题邵武丞郑公名宦传册","f":"五言古诗","c":["古者侯与卿，侐寝无遗迹。","桐乡一啬夫，至今有社稷。","民志谅难谐，德声允无斁。","邈哉邵武丞，乃与千秋匹。","蚤耽竹素编，暮随升斗檄。","十载和鸣琴，鸾凤栖枳棘。","折狱照覆盆，赋政悬尺籍。","老挂武夷冠，云卧仙岩碧。","犹馀棠树阴，清风满旧邑。","长吏备时烝，泽宫参侑食。","赤绂岂无人，伊谁分半席。","柳勒武功铭，韩记蓝田璧。","娄江笔如椽，亦永循良绩。","公真不负丞，是为黄绶式。"]},{"t":"纪梦二首 其一","f":"五言古诗","c":["昔梦游阊阖，谒帝明光宫。","天衣冯玉几，顾笑回春风。","眷言苦行役，赐酒盈金钟。","飶芬满襟袖，色瑩玻瓈空。","吸之不能半，已觉衰颜红。","洗爵再拜谢，幸免倾侧容。","小臣升斗器，既醉心怦忡。","沈湎岂不愉，无乃灾微躬。","大福谅不再，君恩既有终。"]},{"t":"纪梦二首 其二","f":"五言古诗","c":["梦从化人游，虞我以奇巧。","平地疏清渠，中有萍与藻。","游鱼三五头，淫裔何鲜姣。","良无波涛惊，似有云气绕。","临流羡且观，不知床月皎。","记念在恍忽，踌蹰至天晓。","梦中幻已灭，寤言复何道。"]},{"t":"将进酒","f":"古风","c":["君不见洛阳城东桃李花，暮时红雨早时霞。","又不见瑶台素月飞银阙，三五蟾光四五缺。","人生行乐不须愁，富贵豪华电露流。","昔时鼎盛五侯里，今时零落成荒丘。","长安贵人眼中数，规名规利何太苦。","日中走马平津第，绛尘拂衣汗成雨。","白衣苍狗在须臾，雷公駍鍧震下土。","扬雄寂寞默守玄，贾谊太息将安补。","青玉案，紫霞杯，与君沽酒临高台。","烹龙炰凤白日暮，清歌妙舞香风来。","朝不从骐骥游，暮不从黄鹄栖。","浮名碌碌果何有，天地于我如醯鸡。","茫茫吹万同一吷，曾史桀蹠皆电灭。","君今少壮复不饮，坐使红颜镜中歇。","红颜销歇奈尔何，华发萧萧日以多。","直须枕藉杯中酒，莫问浮沉海上波。"]},{"t":"巫山高","f":"七言律诗","c":["巫山高高不可极，十二芙蓉入天碧。","楚王馆前暮雨飞，流烟凝翠湿仙衣。","兰词半吐卷衣去，渺渺行云不知处。","日高枕上听猿声，惆怅高唐梦不成。"]},{"t":"有所思","f":"古风","c":["有所思，乃在萧关道。","玉井苍苔岁月深，门前细路生春草。","春草如烟秋月缺，路远魂飞不可越。","祗听关山笛里声，登楼旷望肝肠绝。","东来有鸟正西飞，愿寄一书到海涯。","鸟辞天长去不反，藏书怀袖衣带缓。"]},{"t":"战城南","f":"古风","c":["去年战，龙城南，今年战，乌丸北。","海门半夜风雨声，岛屿微茫天地黑。","边营嗷嗷新鬼号，头颅乱落芙蓉刀。","平明幕府歌钟起，白璧黄金北斗高。","夷奴垂鞭出海峤，回首辽阳马上笑。","可怜膏血满野涂，异方饱死原上乌。","至今愁望零支道，白草寒霜万骨枯。"]},{"t":"朱鹭篇","f":"七言古诗","c":["昆明池水金堤曲，朱鹭飞来春草绿。","红楼紫殿度香风，片片丹霞水上宿。","王孙苏合作弹丸，飞落碧空池水寒。","网丝漠漠如烟织，敛翅裴回不可即。","朱鹭朱鹭何纷纷，避人引子叫入云。","刻画白头人不识，海边笑杀素衣群。"]},{"t":"轻薄篇","f":"七言律诗","c":["长安九陌花初发，细马轻车看不歇。","五陵少年游冶郎，开颜发艳朝日光。","珠窗绣网烟如织，明月楼中夜吹笛。","双燕西飞底不知，衔泥飞出碧梧枝。"]},{"t":"乌夜啼","f":"七言古诗","c":["金陵城头秋月深，城乌夜半啼高林。","闺中思妇桃红烛，斜倚寒窗听不足。","低鬟无语湿罗衣，起视明星河汉微。"]},{"t":"贾客乐","f":"七言古诗","c":["广陵贾子江东客，大艑珂峨倚江侧。","朱楼绣箔月如霜，醉卧垆头小玉床。","五更解船大江去，鼍浪鲸风何处住。","洞庭秋水接天来，五两成林夜半开。","西登三峡立百丈，滟滪如牛不得上。","环环布帆欲退飞，猿鸣一声泪沾衣。","钱刀睹快狎风色，归来金多头已白。","同时陇上饭牛子，睡起烟皋夜吹笛。"]},{"t":"对酒行送朱廷评可大左迁汝州别驾","f":"古风","c":["朱君朱君，为我楚舞，我为君歌。","金尊绿酒春风过，天长道远可奈何。","尔不能汎汎与凫俱上下，一朝海水生白波。","我今送尔万里长河道，歌声一阕令人老。","上有悲鸣噭噭离群啸匹之春鸿，下有萋萋断肠草。","断肠西去思悠悠，洛水齐山两地愁。","平生不作儿女态，今日为君双涕流。","朱君朱君，与尔登高丘，望远海。","茫茫尘世不知年，秦皇汉武今安在。","天生豪俊必有用，如君自是人间才。","纵然落魄江海上，浮云于我何有哉。","朱君朱君，尔今且饮三百杯。"]},{"t":"行路难送可大","f":"古风","c":["典我千金裘，共醉千钟酒。","何处正愁人，月落青门柳。","长跪问行子，君今何所之。","海风五六月，岂是客游时。","北上太行坂，羊肠诘曲何时返。","南去渡长河，津梁隔阂生风波。","蛟龙出游云雨多，雷公砰訇奈若何。","行路难，难未已，何当与子浮沧溟，一挂长风三万里。"]},{"t":"白马篇送可大","f":"古风","c":["白马黄金羁，蹀躞沟水头。","君今且莫去，为我暂淹留。","昔我束发年，与子同出入。","幸承明主恩，并列金闺籍。","行彼长安途，宛如双飞翼。","自谓连行两不离，岂知一旦成分析。","我栖东海岸，君去洛阳游。","天津桥下水，不尽古今愁。","陆机名高翻见妒，贾生胡遭绛灌仇。","人心对面如山海，世情交道何悠悠。","丈夫得意自有数，岂能与蜉蝣翠羽楚楚争春秋。","为君笑尽一杯酒，弹剑悲歌醉未休。"]},{"t":"明妃曲送可大","f":"古风","c":["妾本名家子，十五颜如玉。","罗绮闭重闺，羞道黄金屋。","君王选秀色，早岁入深宫。","三年不召见，憔悴泣春红。","同时入宫人，一一锦屏中。","芳颜自倚能倾国，肯学他家买画工。","祗怜寂寞深宫里，不道风尘边塞起。","君王一顾不可留，蛾眉远嫁三千里。","红颊两行啼，边城草色萋。","今宵胡地月，昨夜汉宫鸡。","汉宫桃李春如雪，此时缄怨辞丹阙。","但使君心悟画图，不惜龙沙愁夜月。"]},{"t":"鸣雁行寄赵瀫阳年兄南粤","f":"古风","c":["鸣雁发，云中羽。","翮摩天举何意长，风来吹向潇湘渚。","连行接翼不忍分，忽然散落如风雨。","洞庭波寒木叶稀，霜空嘹唳常苦饥。","迢迢故国日已非，闻弦虚惊使我欷。","今复弹射将安归，不及衔泥双燕飞。","金窗绣户春日微，一为鸣雁行，三叹沾人衣。"]},{"t":"江南曲","f":"七言古诗","c":["萧萧烟雨秋江口，两岸青旗拂细柳。","估客初回锦缆舟，妖姬正熟银槽酒。","珠楼宛转画桥东，油壁轻舟绮绣中。","桃叶江前对明月，莫愁湖上起西风。","繁华莫唱江南曲，吴宫旧草茫茫绿。"]},{"t":"关山月","f":"七言古诗","c":["陇头流水何年别，戍客辞家心欲绝。","横笛寒吹塞上声，春闺近对关前月。","如花小妇翠眉低，览镜愁生玉面啼。","十年征戍音尘断，不得云中半纸题。","织成锦字空自叹，椷愁那到玉门西。"]},{"t":"行行且游猎篇为于子冲赋","f":"七言古诗","c":["渔阳九月阵云黑，使君叱拨桃花色。","酒酣弄辔意气豪，呼鹰出猎燕然侧。","黄间欲挽倚宝刀，银镝飞过双青骹。","千群玄鹿大如兕，排风蹠地走且号。","日斜勒马原上立，萧条狐兔无遗迹。","书生自学万人敌，为君却扫阴山北。"]},{"t":"洛阳道","f":"古风","c":["汉宫乌啼天欲晓，平明试马东城道。","银鞍玉勒五花骢，十八承恩拜侍中。","春寒花满披香殿，温室璇房夜开宴。","呼卢一掷赐锦袍，百和轻烟经宿散。","君不见咸阳三月花如雨，卷衣泪落秦宫女。"]},{"t":"采莲曲","f":"七言律诗","c":["芙蓉江上秋风烈，采莲少女沙棠楫。","红颜耀日总疑花，翠袖凌烟浑胜叶。","月高船重花欲稀，渐听花间笑语微。","停桡忽忆巴陵道，怅望烟波涕满衣。"]},{"t":"杯槃舞歌","f":"古风","c":["吹鸾箫，考鼍鼓，四座停酌看槃舞。","七槃宛转一匕举，左翻右覆势如取。","九日落天星作雨，晦明灭没不可睹。","观者叠迹色怖沮，跳丸弄剑安足数。","夜长酒多弦管清，收槃按节作缓声。","月高露下天宇平，向来巧拙虚无形。"]},{"t":"凤台曲","f":"古风","c":["未央宫前桃李花，柳枝烟袅御陌斜。","贵主初临万年馆，小侯新试七香车。","香车绣幰开长乐，十里天街铺锦箔。","台上乘鸾白管箫，楼头走马黄金络。","赐衣分得御袍香，宝玦珊瑚佩带长。","朝游歌管金张第，暮入风流赵李场。","君不见陇西老将头白尽，百战不博通侯印。"]},{"t":"阁试征西将军出塞歌","f":"七言古诗","c":["榆关九月寒风早，玄霜已白边城草。","敌骑朝侵策勒营，将军夜出祁连道。","关山晓月度龙沙，马上芙蓉吐剑花。","连营画地传刁斗，十万军声静不哗。","期门少年健如虎，束发从军思报主。","画角寒销玉塞云，铁衣冷拂金城雨。","援枹执鼓何雄哉，笑看楼兰动地来。","合围瀚海浑无敌，转战皋兰未肯回。","紫骝汗血归来后，肘背黄金大如斗。","胡床坐解月支头，割鲜笑釂蒲萄酒。","酒泉亭障接乌孙，辎重如山入塞门。","五云阙下报天子，万里封侯安足论。"]},{"t":"馆课沙堤行","f":"七言古诗","c":["汉家宫阙五云里，复道连绵正相倚。","建礼门前绮陌开，铜龙楼下沙堤起。","沙堤迤靡属东城，十里宫槐绿影横。","街官闾吏传呼过，堤上堤下人不行。","黄麻早下平津阁，万玉班高元宰爵。","华毂遥从天上来，沙堤半自云中落。","沧海桑田事未真，人间富贵等流尘。","只言避世金门客，曾见沙堤几度新。"]},{"t":"题桃川图赠鍊师张子故西苑方士也","f":"古风","c":["我歌桃川图，旧识桃源客。","骨青发短双颊红，十年卖药长安陌。","自言本是武陵人，花落花开不记春。","姓名偶被先皇识，选列仙官侍紫宸。","紫宸宫阁天中起，西苑繁华如梦里。","铜盘百尺落秋空，绮幕千门照流水。","祠坛队队羽衣群，鹤盖霓裳拥圣君。","黄金白璧年年赐，豹髓鸾膏夜夜焚。","当时等辈俱光采，算袋裶衫揖上宰。","曾窥阿母降瑶台，更访安期入东海。","海上重来鬓已秋，鼎湖龙去水空流。","夹城辇路多青草，别殿宫官半白头。","承恩旧侣知何处，闻逐云中鸡犬去。","惟馀野迹走风尘，却忆桃花源里住。","我闻此语涕沾膺，世事从来不可凭。","君今莫说丹砂事，松柏萧萧冷茂陵。"]},{"t":"赠邬秀才汝翼","f":"古风","c":["白头自如新，倾盖自如故。","西风萧索朔雁号，江南老生来何暮。","我闻吴楚之间多大雅，布衣往往称作者。","才情不复论三唐，直薄西京接枚马。","君乎君乎何壮哉，握笔一扫倾群材。","凄风寒迸金石裂，长涛怒激天地回。","眼前浮沉那足数，文章有真心自苦。","胡为乎，敝裘零落双眼白，一夜商歌泪如雨。","我为歌一阕，君为尽一杯。","白雪谁怜楚客调，黄金空筑燕王台。","看君落魄今何似，古来才人亦如此。","莫言得意自有时，人生所贵成名耳。"]},{"t":"送业师黄东野先生左迁卫辉郡博","f":"七言古诗","c":["渔阳城下多秋草，渔阳城头秋月晓。","凉风飒飒吹客心，驱车远下三河道。","三河地接太行秋，倚剑悲鸣回紫骝。","满堂击筑吾不乐，黯淡胡为赋远游。","先生落落闽中彦，束发床头开万卷。","赋成尽拟似相如，待诏金门不召见。","明光宫里落双凫，握绶江城兴不孤。","推毂难逢北海荐，抱经却授西河徒。","青毡莫道成萧索，博士古来官不薄。","买骏终归郭隗台，登龙本出孙弘阁。","垂髫旧日鲁诸生，负笈从游济北城。","十年不立门前雪，望断江南万里程。","蓟门烟树今何夕，白露满庭空水碧。","一尊相对夜色寒，挑尽青灯话夙昔。","长歌忽漫是离筵，不尽浮云黯远天。","淇园到日应相忆，万竹寒声沸百泉。"]},{"t":"弹铗歌为郓樊生赋","f":"七言古诗","c":["君家阀阅高东鲁，亦近樊城传旧土。","两朝八座祖与孙，后代簪缨仍接武。","尔亦翩翩帝里游，茱萸锦带鹔鹴裘。","紫云阙下弹双铗，来向朱门傅小侯。","朱门修巷临长道，翠阁琼楼相映好。","明月时闻内苑笙，春风日蹋芳堤草。","高堂上客号三千，侠少风流独迥然。","斗鸡南陌争金距，走马东城揖玉鞭。","相逢斗酒多倾倒，胡姬垆头天未晓。","汾阳甲第贵盈门，那作樵渔空自老。","蓟门春尽雨茫茫，汶水梁山路阻长。","锦衣归向桥边过，不是青丝马上郎。"]},{"t":"荆门歌送沈澄川太史奉使楚藩","f":"七言古诗","c":["荆门望望渺何许，横跨三巴控三楚。","高台落日大王风，明月空江帝子渚。","侍臣持节下蓬菜，三楚豪游意壮哉。","银扉朱邸江边峙，玉检金泥阙下开。","青门柳枝日未午，胡姬压酒当花坞。","聚散浑如陌上云，别离苦恨尊前雨。","驿楼官树潞河西，七十长亭路不迷。","赠客几投青玉案，当歌一听白铜鞮。","南登即向巴陵道，苦竹香枫相映好。","旆指芙蓉泽畔花，槎凌鹦鹉洲边草。","兰台仙馆白云秋，飞盖争随上客游。","应教非同灵运赋，怀乡不上仲宣楼。","嗟君声名何炜煜，彩笔惊人珠万斛。","论道三年侍石渠，校书乙夜开天禄。","长安春色正霏微，侍从翩翩满禁扉。","早看方朔归金马，莫学相如恋锦衣。"]},{"t":"夜郎歌送贾谏议德修奉使黔中临问属夷酋长","f":"七言古诗","c":["燕城客舍经春草，落花如雪閒不扫。","故人忽作夜郎行，离心沟水长安道。","与君追逐竞高踪，翩翩矫若双飞龙。","春风共载承明笔，晓月同趋长乐钟。","嗟君风度何磊磊，夙昔大名满东海。","千言倚马疾如飞，赋成四座腾光彩。","一列金闺法从班，朝朝鸣玉侍天颜。","牵裾折槛偶然事，谏草琅琅动九关。","夜郎越巂天南土，万里夷荒开幕府。","倚剑秋回七泽云，挂帆夜渡三湘雨。","天书远向百蛮开，辫发番君夹道来。","啸咤风雷震山岳，白日罔两何有哉。","金杯红烛月鸣杵，酌酒与君对君语。","区区离合安足陈，怀抱平生吾与汝。","春晴日观转愁予，十二河山锦不如。","莫诧故林偏得到，吾将走马深嵓居。"]},{"t":"白将军歌为吉轩令君赋","f":"古风","c":["君不见关西故将五陵豪，束发从军受六韬。","莲花玉剑浮云骑，横击阴山塞月高。","又不见五云楼阁春窈窕，射策彤庭海日晓。","碧衣行尽长安陌，玉勒银鞍弄騕袅。","君家甲第陇云东，文武家声霄汉通。","已看彩凤鸣秦苑，早见仙凫出汉宫。","三年试政齐城宰，万树名花何罨蔼。","函关却望紫气深，姑射山中春未改。","将军矍铄状如何，七十犹能击缶歌。","廉颇善饭英风在，马援凭鞍壮志多。","封侯万户吾何有，庭种芳兰门种柳。","结束还徵侠少游，十千一醉新丰酒。","齐城东去是三山，弱水蓬莱路不艰。","郎君跪乞长生药，为驻仙人千岁颜。","吾闻黄河东来三万里，横亘榆关天际起。","将军世泽亦如此，累累肘后何足比。"]},{"t":"投笔歌送侯兄上清浪参将","f":"古风","c":["昔年谒告黄山侧，西风送尔游京国。","我来昨日入明光，送尔南登古夜郎。","相逢相送何其迫，踟蹰沟水令心伤。","翩翩尔自佳公子，丞相勋名在国史。","中丞踔跞本如龙，汗血神驹更千里。","关西老将力不如，鲁国诸生名大起。","十年不售昭王台，辕下长鸣泣未已。","尔时投笔大昂藏，仗剑悲歌去故乡。","两臂常开十石弩，千金笑入五陵场。","横行直贯单于幕，手缚楼烦紫塞旁。","六骡已遁一骑返，雪花如席高云黄。","马首血悬月氐器，小妇垆头索酒尝。","赤囊一日奏阙下，锦鞚飞尘朝建章。","三十男儿好身手，腰悬两绶黄金珰。","旄头已落胡天久，郅支呼韩同稽首。","不闻天子猎长杨，却召将军屯细柳。","西南未罢伏波军，都护金章大如斗。","生年自有封侯骨，弹铗长歌劝君酒。","长歌未已涕沾裳，客子浮云各一方。","两甥牵裾啼不去，一双白璧腾精光。","大者日受三四卷，小者学语声琅琅。","顾我犹多离别叹，怜君不作儿女肠。","吁嗟乎，桂水横烟不可迫，流入牂牁天地坼。","湘潭七十五长亭，羡尔今为万里客。","旌节遥连铜柱阴，楼船直压鲸波白。","诸部蕃王伏道周，千群将吏喧江泽。","玄猿暝啸跕鸢惊，正使豪游壮心魄。","春江瑶草绿可折，何当寄我长安陌。"]},{"t":"送业师郑舒轩先生署教海宁同子冲可大二君","f":"古风","c":["蓟门四月杨花白，丹凤城南送行客。","两生击筑酒欲阑，先生默默不尽欢。","我今为歌行路难，忆昔振翮闽海滨，才名踔绝无与伦。","腹中万卷已成笥，笔底千言若有神。","数奇不逢得意荐，赋成谁念马卿贫。","十年汉阙泥穿履，几度燕城桂作薪。","道傍明珠真按剑，枥上骅骝空绝尘。","长歌投袂出门去，江上聊开绛帐春。","绛帐青毡殊不恶，东南山水堪游乐。","千峰夕翠入讲堂，一枕夜潮浸郡郭。","东风桃李色方深，秋雨芙蓉颜自若。","天生豪俊岂无心，不合先生长落拓。","君不见会稽寒士西入秦，公车不收小吏嗔。","偶然怀中探尺绶，黄金系肘意气新。","又不见新丰市中贳酒客，寒贱时逢里媪谪。","一日忽承内殿宣，青骢蹀躞生颜色。","人生得意自有时，世事浮沈那可知。","还看独对彤庭问，接迹夔龙集凤池。"]},{"t":"听琴篇呈李雪沪先生","f":"七言古诗","c":["雨鸣潇潇风满壁，虚堂孤坐春草夕。","何来两客登我堂，坐索瑶琴鼓前席。","吾家焦尾旧无弦，世路逢人不解传。","丈人锦囊出绿绮，为我挥手松风前。","宫声一曲试瀛洲，文物翩翩禁苑游。","人间帝子铜龙馆，海上仙人绛玉楼。","倏忽凉飙飘四屋，新声转作潇湘曲。","沙清石碧江水寒，月明叫入汀洲宿。","弦悲调急声转微，满堂击节泪沾衣。","幽兰白雪何要眇，此意世人知者稀。","丈人自是贤豪客，横琴呼酒双眼白。","借我朱弦三尺强，试理清商入萧索。"]},{"t":"匡庐山人歌寄胡少白文学","f":"古风","c":["庐山之高高入天，孤峰秀出真青莲。","峰悬石镜何年影，照尽彭湖三万顷。","平开双阙赤霞浮，翠嶂丹厓万木秋。","飞涛倒泻银河水，洒入长江九派流。","青山亦不摧，流水亦不绝。","谢公行处空云烟，东林旧迹莓苔灭。","豫章胡生才且雄，匣中玉剑双飞龙。","拂衣欲出人间世，走卧匡庐第一峰。","香炉云气飘山阁，明灭千岩与万壑。","雨急朝闻岭上猿，月寒夜听江皋鹤。","有时结束帝城游，侠骨常轻万户侯。","上书北阙不待报，笑卧胡姬旧酒楼。","垆头日高金管歇，杨花茫茫春雨雪。","此时弹剑却归来，脱帽长歌舞秋月。","胡生胡生无与伦，心雄万夫步绝尘。","英贤古乃起屠钓，何况儒术逢昌辰。","彭蠡为君腹，瀑布为君口。","俯瞰洞庭波，吸作一杯酒。","但欲浇尔胸中万古之垒块，风尘䠥?吾何有。","胡生胡生何时与尔同上匡庐巅，足蹑星虹礼南斗。"]},{"t":"赠于子冲大参请急南旋","f":"七言古诗","c":["长安城头秋雨繁，长安城下双朱轓。","去年忽向洛阳道，今年却入长安门。","谁道分司非达宦，谁言朝请不承恩。","行边惯试渥洼马，到阙仍依白虎幡。","忆昨匈奴入边塞，陇坂以西杀气昏。","右方王将旃庐满，北地烟尘士女奔。","元臣庙略驰三殿，上将戎轩历五原。","青海几经传尺檄，玉关依旧有游魂。","翻令蛮府提锋锐，欲扫干戈静塞垣。","谢公谈笑亦何易，贾生流涕亦太烦。","竞说请缨临瀚海，争言倚剑出昆崙。","尔曹落落不入眼，此事悠悠谁与论。","我今但欲拂衣去，斗酒悲歌意气存。","看君四十头未白，勉加餐食无多言。"]},{"t":"寿李北山先生八十","f":"古风","c":["君不见扶桑之下一杯水，一峰突出三千里。","其北有济西有濮，当代词坛宗二李。","济南修文地府深，濮阳垂老卧空林。","同时已抱千秋恨，异调俱称大雅音。","江淮当日嗟流落，尚玺先朝官不薄。","双袖天风逐鸟还，一竿秋水知鱼乐。","至人遗形在杜机，如翁达生识者稀。","不从北阙怀簪绂，不向西山采蕨薇。","安期大药欺人久，石家金谷谁能守。","有田但种东陵瓜，有钱但买宜城酒。","只今号作北山人，素发丹颜八十春。","蹑屐当閒青玉杖，呼卢时侧紫纶巾。","半酣击缶耳稍热，笑拥如花歌未歇。","洛阳七贵眼中尘，长安五陵原上月。","天道有盈日有虚，得名得寿福已馀。","璇闺况继中郎业，金匮还传太史书。","中郎太史亦尔尔，君家柱下差足拟。","请为小著五千文，藏在白云封中石闾底。"]},{"t":"商丘沈封君画竹歌","f":"七言古诗","c":["梁王修竹不可识，千秋草合平台迹。","平台主人墨君友，扫出檀栾一千尺。","醉沈淋漓幅素看，枝枝茜翠若可餐。","笔端乍觉烟云绕，堂上时惊风雨寒。","寒声槭瑟生绡起，如在湘江秋色里。","湖州以后称太常，此幅神真良足拟。","主人种竹旧成林，千里提封自作阴。","蟠根出地成龙骨，劲节凌霄引凤吟。","高堂日远悲风木，手泽凄凉馀半幅。","他日尚书阁上图，应写平台万竿绿。"]},{"t":"寿临邑邢封君七十长歌","f":"七言古诗","c":["邢翁济北之名族，世代门庭罗绣毂。","长公谏草青蒲伏，群从咸登天府录。","翁独翛然在岩谷，芝房萝壁薜荔服。","牛角挂经眠抱犊，学儒不干五斗禄。","种田往往皆成玉，瑶环瑜珥多如簇。","一枝炯炯先出椟，名都十五不敢赎。","天风吹作华林木，走马春城十二街，雕龙翠殿三千牍。","少年出宰称民牧，召入文昌锦被襆。","白简绨囊临仗读，云梦汪洋舟万斛。","长风直下千里速，姓名已在金瓯覆。","方底诏函貤半幅，玉绳兰检何熠煜。","翁冠柱后衣锦縠，行年七十方瞳绿。","出门柴车声轣辘，季方持杖元方仆。","齐眉仙姥膺多福，阆苑春开阿母桃，渭川日长封君竹。","山中八月酒新熟，玉盘琥珀四座馥。","松枝自煮石溪蔌，珠履满堂绮障促。","千金称寿起相属，参差玉管间琴筑。","主人浮白自捧腹，生事惟馀陶令杯，年华不问君平卜。","我家乡邑不朝宿，郎君旧谊敦羔鹜。","蹇予抱拙长碌碌，弹铗归来头不沐。","仙闾东望地可缩，缄词且效如川祝。"]},{"t":"代作朱宪使双寿长歌","f":"古风","c":["嵚崟大伾山，西遮黎阳口。","白马遥盘匏子堤，黄河如带东南走。","东南万里入蓬瀛，毂转雷奔大壑惊。","长淮一泻不知岁，至今惟见山峥嵘。","山上丹厓合翠谷，别有日月非尘俗。","问言谁向此中隐，西台使君茅作屋。","使君早日客长安，襆被香分画省兰。","兵符一领辽海震，戎轩再驾朔漠寒。","閒心旧爱春山蕨，忽解绯衫辞帝阙。","黎阳一卧几经年，醉弄大伾山上月。","山月沈沈吐玉楼，绿萝飞花碧草秋。","有时更涉沧洲趣，钓艇烟蓑对白头。","松间鼓琴俯流水，猿鹤夜声清心耳。","少年记作金闺游，一经又见金闺起。","珠袍锦带开旧箧，走马曲江春色里。","只今花树满河阳，亦有槐阴如市里。","使君年岁七十强，红颜玉骨何昂藏。","郎君自献南山曲，戏取宫袍作舞裳。","齐眉玉案双尊酒，皬然又睹西王母。","雕盘绮食罗秋堂，凤箫象管无不有。","仙家缥缈六鳌峰，五城楼台春气浓。","大伾如块河如一杯水，使君笑挟两茅龙。"]},{"t":"寄送贾石葵大卿之任南都","f":"七言古诗","c":["昨夜南山射猎归，松窗醉卧星露微。","五更乌啼窗月白，酒醒梦见长安客。","平明厩吏来相闻，为见春帆驻浦云。","春帆信宿不知处，建业澄江杳然去。","缄书送君江水长，此时脉脉空断肠。"]},{"t":"岱西山人歌寿何吏部敬庵","f":"古风","c":["君不见岱宗之山海上起，云霞沃宕三千里。","七十二峰峰插天，西支半落清河水。","山川回合势连绵，灵气应钟不世贤。","大名谁者齐北斗，岱西山人行地仙。","山人旧隐双龙阙，左省含香陪上列。","共道诗名水部传，更闻启事山公绝。","一时流品入陶甄，简要清通世所珍。","三十朱轮行宝陌，衣香风动洛阳尘。","素心忽忆栖岩谷，解组归来双鬓绿。","玉树多从院宇生，兰房近傍烟云筑。","山人修翛六十馀，赪颜绰约玉不如。","载酒时游广里月，垂竿閒钓锦川鱼。","石闾有伴餐瑶草，玉几金床春色晓。","人问已自有蓬瀛，何人更说蓬瀛好。","为翁亢节歌欲长，琼卮起寿春茫茫。","泰山若砺海水竭，大年不凋齐日月。"]},{"t":"大伾山亭图歌为朱令君赋","f":"古风","c":["谁持一幅绡，扫作千林碧。","奇峰华嵂浮烟空，秀色横分白马迹。","山下草堂瞰古城，百花潭水飞春英。","长杨翠柏蔽云日，静听似闻风雨声。","亦有高台临灌莽，岧峣百尺浮云上。","何人月夜舒长啸，一声遥和竹林响。","台下悠悠河水来，乱帆东去接天回。","青山一片明湖里，翠黛光摇宝镜开。","春风满岩杏花裂，光中乍见轻烟灭。","赩如赤城霞，皎若天山雪。","修竹檀栾碧万竿，清风瑟瑟动庭兰。","了然潇湘色，对此心神寒。","西北一亩丘，厥形如负局。","仙人对弈挥素手，华山几更春草绿。","我披此图开心颜，一时坐我烟霞间。","恍如身到辋川曲，目中已自无尘寰。","又似桃花源里去，碧流红雨不知处。","黎阳仙翁圣代英，欲卧沧浪绝世名。","一朝解绂谢天子，杳然自写丹青里。","有子重看上苑花，河阳万树还相似。","仙翁可望不可亲，绘为此图传世人。","真游莫讶人间少，方丈蓬莱别有春。"]},{"t":"桃花岭图歌寿太宰杨梦山先生","f":"古风","c":["长安三月烟如织，上苑桃花看不极。","主人旧是武陵人，别有春林千树色。","千树万树玉岭赊，烂漫风前十里花。","细缬半含仙掌露，繁枝齐吐赤城霞。","主人数椽筑洞口，手植城堤几十亩。","笛里香分画阁梅，楼头艳拂金堤柳。","花间漉酒醉朱颜，石几松床自闭关。","不遣红尘来陌上，惟容流水到人间。","只道林中聊可住，芳菲又满咸阳路。","扫尽玄都观里泥，栽成濯锦江头树。","还将幅素写花源，半染山光半水痕。","拂拭自疑真境近，不知春色在公门。","君不见度索山前花落晚，千年一结条支卵。","东方先生太苦饥，啖馀半核如金椀。","又不见仙人子晋遨五城，白鹤朝骖海上行。","缑山瞥见花成雨，沈醉吹残月夜笙。","主人亦住三山岛，瑶池仙种分来早。","花开几度笙几曲，日上扶桑春未老。"]},{"t":"炙兔行为于子冲赋","f":"七言古诗","c":["渔阳大使齐大侠，行边数奏甘泉捷。","千金饱士士欲死，领向狐奴山下猎。","黄榆九月号北风，双鞬怒马如盘空。","弓影向天毛羽落，弦声撇地霜草红。","绿眼健儿马前走，血悬两兔■贯首。","传火无烦玉鼎调，擘肩未假鸾刀剖。","鸱夷吐酒复不住，月氏漆器在左手。","酒酣握槊还大叫，笑谓鲁生尔能否。","沙头月出燕云黑，枕藉相看头不帻。","平生肝胆向谁倾，说著世人双眼白。","羽猎虚随卜祝群，词人亦自树功勋。","试问陇西李都尉，雄材肯数霍将军。"]},{"t":"燕子矶歌呈李棠轩宫谕","f":"七言古诗","c":["大江西来万里白，建业青山两岸划。","山根片石凿不断，斗入江流数千尺。","我来扫石上高空，直蹑忽恍开鸿濛。","回涛细齧鷟鸑岭，悬厓倒瞰鼋鼍宫。","魂摇骨慄不得语，衔杯邈望蒹葭渚。","萧萧木叶满江流，却是千帆万帆雨。","雨馀返照江水红，赤城吐色江水中。","须臾海月东山出，睡龙欲动金波溢。","水晶为盘玉镜开，秋光寒泻玻瓈台。","客怀跌宕不可奈，散发呼酒天风来。","西望采石若可挈，长江之水亦应裂。","君家供奉去几时，不见今时江上月。"]},{"t":"猎兔歌","f":"古风","c":["南山猎兔如猎虎，万骑合围昼伐鼓。","壮士齐关十石弧，王孙自拨千钧弩。","兔走入窟窟草平，长林落日欢人声。","铦戟利剑不得刺，汗流蹋足空屏营。","君不见北山老翁手握矢，臂解一鹘狡兔死。"]},{"t":"卖珠行","f":"七言古诗","c":["卖珠老妇发半白，提筐日走宫城陌。","遍谒朱门不得休，斜倚道旁长叹息。","自言本是绿珠俦，夫婿先朝万户侯。","锦衣夜直铜龙阙，画栋朝开碧玉楼。","尔时秀色新承选，二八嫂婷集内馆。","小阁微风倚翠屏，閒房落月调金管。","罗衣宝靥不胜春，十斛明珠掌上新。","只言华屋长如海，不道沧溟亦作尘。","当时世事一朝变，郿坞黄金实内殿。","剑履三千帐下空，鸳鸯七十池边散。","前年曾向旧门过，新主承恩骤玉珂。","今年又望门前道，行马半残生绿草。","繁华憔悴看如昨，覆雨翻云何闪烁。","桥上年年阅水流，宫前岁岁看花落。","我闻此语涕沾裳，世事悠悠不可量。","祗应汉代麒麟阁，千古名垂日月光。"]},{"t":"双桂行寿宜兴蒋郡丞","f":"古风","c":["堂前双桂树，堂上双樽酒。","太湖一曲住者谁，淮南秋色落君手。","使君潇洒豪且贤，东方千骑何翩翩。","一日上书抛紫绶，走种阳羡山间田。","山田种秫收不薄，荆溪如画堪行乐。","桂花已见湖上开，桂子还闻月中落。","月中清影碧天秋，花下斑衣对白头。","陶令归来浑是醉，徐卿老去百无忧。","不见玄都观里桃，不见灞陵桥畔柳。","桃花吹作素衣尘，柳色歌残行客口。","谁能向桂花树下日陶然，万斛天香近酒边。","燕山五枝君不羡，蒋家三径益可传。"]},{"t":"招山人歌","f":"七言古诗","c":["城中山人常苦多，山中山人常苦少。","我来杖策入山中，山人门外迹如扫。","闻道长安方大索，髡钳赭尽荷衣色。","今朝司狱中书，昨日平津座上客。","大国并容何事无，防川防口无乃渝。","山人有山归亦得，慎莫出走越与胡。"]},{"t":"亭山洞歌上周师七十生辰","f":"七言古诗","c":["岱宗西来未了青，结作秀山山似亭。","亭坳石洞何窈窕，千峰万峰罗作屏。","山翁少时隐山麓，数椽桃花源上屋。","鹖冠凭几暮云生，牛角挂经春雨足。","偶然随牒入燕城，博士惊传墨绶荣。","赤县郎官原应宿，兰台循吏早书名。","人间月旦吾何有，那能折腰为五斗。","抛却河阳县里花，归来彭泽门前柳。","山中回首隔风尘，绿发方瞳白袷巾。","烟霞半结游仙侣，弧矢还逢献寿辰。","此时凉飙入户牖，华轩松桂参差茂。","有孙能采泽宫芹，有儿能致宜城酒。","银河耿耿月上钩，座客谁者飞觥筹。","同游门巷多苍藓，旧学生徒已白头。","请翁拍浮莫辞满，人生七十古亦鲜。","试探洞里玉函书，海水何时复清浅。"]},{"t":"甲午五月朱可大自江右来访相见喜极对酒放歌","f":"古风","c":["别君春花落，思君春鸟啼。","春风吹远梦，夜夜到湖西。","只言尺素迷江树，不道隔年即相遇。","元方执御季常随。","德星应卜贤人聚。","揽衣出迎雨满衣，秉烛相看暑气微。","炎天命驾三千里，如此交情古亦稀。","笑杀山阴一夜舟，笑杀平原十日酒。","把杯脱帽双眼白，放歌大叫无不有。","与君譬如双吴钩，神精会合自有由。","兴君譬如双飞燕，差池羽翼时相见。","莫将逐客当沈沦，自是江湖合有人。","试观青海营中月，试望长安陌上尘。","羡君红颜发盈帻，我已如霜镜中白。","回头三五少年时，半百光阴如过客。","赤绳系日那得还，长鲸吸海几时乾。","灯前起舞劝君酒，何处含情可尽欢。"]},{"t":"雪中登楼看山歌","f":"古风","c":["月中看山不辨色，雪中看山不辨影。","阑前九叠锦屏张，一时幻作虚无境。","苍茫颢气万里通，轻琼冷絮飘鸿濛。","阎浮几许还遭劫，色界由来总是空。","忆昨筑楼对城缺，本为看山亦看雪。","那令有雪却无山，倚楼满目成㵳泬。","山亦非真无，雪亦非常有。","自顾梦觉身，至竟谁为偶。","此时欲说已忘言，拍阑且尽杯中酒。"]},{"t":"雪中菊花小歌","f":"七言古诗","c":["去年九月雪雨集，菊花吐向雪中泣。","今年十月菊始开，雪花又落黄金罍。","繁华何意同萧瑟，冷蕊疏枝一半白。","罗绮三千梦早春，却将铅粉妆佳色。","素影关山夜欲流，寒香寂寞楚天秋。","不知陶令吟时醉，正是袁安卧处愁。","篱边吾亦怜吾友，苦节贞心成素首。","试看东园桃李花，霜前零落今何有。"]},{"t":"冬日送方胥成北游临邑访邢子愿侍御一首","f":"七言古诗","c":["黄石山头雪未晴，黄石山前送客行。","天寒岁暮白日驶，北风猎猎吹冠缨。","看君殊少风尘色，击剑长歌双眼白。","少年曾慕五陵豪，老去犹为万里客。","只今蹑屩远行游，湖海茫茫路阻修。","举世何人重词赋，布衣无策干王侯。","山中萧条鲜所有，解衣衣君劝君酒。","平生肝胆向谁尽，但说邢公不离口。","邢公好士无与伦，千金散尽家苦贫。","此时无忌还留赵，何客冯驩可入秦。","君今又向犁丘去，马首残阳明远树。","山头望君酒欲醒，相思并在君行处。"]},{"t":"游蜀山湖歌示任城王甥季辅","f":"古风","c":["昔闻钜泽湖，漭沆三百里。","自从中作宋公渠，两岸长虹夹汶济。","我家湖北缆扁舟，住近沧浪不解游。","王郎亦住湖南曲，携我来探水国秋。","叩舷湖口渺然入，洲渚萦回望不极。","荷芰残花棹底分，鸥凫乱影帆前失。","波心宛在一丘悬，直上苍茫尽水天。","万顷泓淳沈碧落，千林黯淡入寒烟。","萧然似欲来风雨，感慨愁心吊千古。","秦皇片石有孤峰，鲁国荒台无旧土。","玉罂春酒欲尽无，沈醉烟波兴未孤。","西风不过山阴道，枉向君王乞镜湖。"]},{"t":"九华山歌送施幼淳省元南还青阳省觐","f":"古风","c":["九峰名九子，幻作九莲花。","去天不知尺有几，晴空片片飞丹霞。","南宫才子江东客，笔带九华峰顶色。","学书欲作万人敌，一日声名倾上国。","青春谒帝入神京，黄石寻师驻谷城。","经术远宗燕太傅，门墙半列鲁诸生。","忽登泰岱看乡陌，望见江头云气白。","愁心一夜渡淮阳，不为莼鲈秋兴迫。","千里宁亲愿不违，西风萧瑟送将归。","尊前落木浑成雨，马上微霜欲点衣。","为君长歌劝君酒，便是别离未应久。","去日聊随朔雁飞，来时莫在春鸿后。","玉树青荧上苑栽，君王正忆子虚材。","好将九朵芙蓉露，泻向仙人掌上开。"]},{"t":"岁暮送汪山人敬仲南还","f":"七言古诗","c":["寒风飒飒愁云繁，江南浮客来到门。","手出瑶华八百片，雪花错落飞琼轩。","自言落魄无何有，湖海豪游成皓首。","竟陵学士座上宾，新都司马社中友。","燕南作客岁将阑，弹铗长歌道路难。","知公当代论风雅，曾向人家卷里看。","蓬门旧日不迎客，为君拂拭凝尘席。","谈诗静夜一炬红，呼酒高斋双眼白。","送君南去及新春，残雪初消路少尘。","行到石城应早渡，隔江桃叶唤归人。"]},{"t":"平倭奏捷歌","f":"七言古诗","c":["去年都护大徵兵，平壤岛寇皆扫平。","今年司马通和议，盖海鲸鲵不可制。","鱼服十万簸狂澜，千里腥风塞月寒。","不见降书来日窟，空令猎火照辰韩。","吾皇按剑赫威怒，独运神谟惩往误。","早传制府凿凶门，更诏中丞开武库。","材官负弩尽从征，慷慨辞家志不平。","杀气千寻飞浿水，军声一夜度龙城。","士马骖驔谁复数，青海原头昼伐鼓。","转旆横捎乐浪云，洗兵半染夫馀土。","陆营三路势已奔，水营大队赤云屯。","弓刀蹙沸鲛犀裂，戈甲抢攘日月昏。","小酋面缚大酋死，属国君臣歌燕喜。","羽书昨夜自东来，直入甘泉报天子。","论功大发水衡财，碣石关门日夜开。","符节星驰玄菟塞，金缯山累白龙堆。","十年馈师三百万，今日方闻博一战。","明王守禦在四夷，属国君臣尔莫玩。"]},{"t":"射覆谣戏作","f":"古风","c":["郭舍人，东方朔，来前射覆相为乐。","谓此金盂中，有何一蠕虫。","不是蜥蜴，亦非守宫。","中者赐帛，不中城旦舂。","舍人东方，相顾?咍，此胡为来哉。","谓之为龙，不能变化兴云雷。","谓之为蛇，又不能委蛇蒲伏与世谐。","此何物也，陛下幸发视，必是一蜗牛。","身似有所负，外又无所求。","不肯濡足，惟愿藏头。","循墙而走，面壁而修。","钟鼓不能享，鼎镬不能谋。","左角大胜，右角大败，未尝知喜，未尝知忧。","蘧庐为天地，混沌为春秋。","其觉如寐，其生若休。","此有巢氏之裔，无肠子之俦。","与圣人拊掌笑，是物安足收。","放之污渎中，使从蛭螾游。"]},{"t":"日观峰歌","f":"古风","c":["岱岳峰头一片石，天光杳杳连空碧。","我来夜扫石上云，未明看见海中日。","日出海东几千里，茫茫不辨云与水。","天鸡啁喔海上啼，东方霞气半边紫。","忽然潋滟琉璃丹，一泓捧出赤玉盘。","长绳斜挽不得上，半时方到扶桑端。","扶桑枝叶成五色，海水明灭一线白。","日旁云气如连山，目中欲识鲛人国。","平明日高海水乾，满天翕赩红气团。","三山金阙流安在，六鳌背骨秋霜寒。","忆昔秦帝东封年，欲浮白浪游灵仙。","驱石作桥不可涉，金支翠羽空西旋。","几时得见海中出日三千丈，脱屣妻子如浮烟。","眼前朱生信豪士，侧帽大叫石上眠。","我亦欲取巨石填东海，挥戈且止羲和鞭。","六龙不停日如矢，仰天呜呜酒热耳。"]},{"t":"泉林歌","f":"古风","c":["雷泽万顷波，澎渤如万马。","陪尾镇之不得溢，酾为灵渎出其下。","洞门喷薄泻飞泉，沸珠迸玉声潺湲。","天山雪花四月落，片片吹上春衣寒。","清流可漱复可枕，拍浮大白相对饮。","潭中石子成五色，荧荧细濯巴江锦。","行尽回溪地转偏，疑是镜湖春水旋。","深林蔽亏不见日，但闻杂树多鸣蝉。","树里泉声百道重，木根诘曲盘虬龙。","解衣罗坐汎流羽，天光水色何溶溶。","远峰隐见多明灭，残霞飞丹手可掇。","此时林壑瞑色来，呼酒弹琴望云月。","月上青山醉若何，临流垂手挹素波。","且歌白石吟渌水，红尘万事空蹉跎。","旭日高林送客子，清风四面松声起。","市桥一出到人世，武陵桃花空流水。"]},{"t":"峄山歌","f":"古风","c":["岱宗海上来，西塞中条路。","东南数峰青未了，凌波欲涉长河去。","似断不断走势回，结作芙蓉掌上开。","青冥浩荡何年裂，平地涌出金银台。","名山固多奇，此山奇欲绝。","累累万古石，谽谺成窦穴。","落星不到地，累丸不到天。","悬圃亦已碎，群玉亦已颠。","金华牧儿何婉娈，一入紫烟不复返。","世人谁者叱群羊，坐看蹄角生苔藓。","人行石中何盘珊，十步九折穿嵌岩。","顾见杂花开绮绣，又闻淙淙泉水声鸣环。","千峰冥密万壑逼，日光时向天窗滴。","深林已尽鸟不鸣，攀缘犹访白云迹。","白云在天何时还，洞门石扇开重关。","五花峰头一骋目，飘如乘虹驾鹤飞出天地间。","但闻长风飒飒万里至，使我四顾清心颜。","君不见沧海桑田年岁改，秦皇片石今安在。","万骑千乘化作灰，河声依旧东流海。","沈吟此事思欲飞，击节高歌泪满衣。","空怜世上浮沈子，白首红颜何所归。"]},{"t":"前赠李本宁歌","f":"古风","c":["一别十五年，再别十二春。","人生百岁苦不满，可堪几作别离人。","前年君入蜀，为李醉歌为陈哭。","酒挹玉华山色青，泪洒嘉陵江水绿。","去年君入越，曾讯朱公访禹穴。","邀欢又作湖上吟，沈侯细腰可已折。","今年君向燕京游，千骑朱衣唱八驺。","道旁忽问鲁狂叟，半夜停车南陌头。","我病伏床君坐膝，呼儿出酒陈曲室。","相看如梦烛影残，屈指良游话夙昔。","我年多君两岁强，君头如漆我如霜。","浮沈聚散不盈眦，回首万事空茫茫。","北风吹雪角晓寒，车帷欲裂嘶马酸。","莫言岁晏别离苦，更有时危道路难。","知君词赋满人口，六符鼎足多故友。","君王倘复问同时，旧日岁星人识否。"]},{"t":"后赠李本宁歌","f":"古风","c":["李君李君，汝今坎壈何甚哉。","七命藩臣二十载，朝天又奉除书回。","忆昔蓬莱开内院，翩翩二九凌霄汉。","大者为相小乃卿，君乎锻羽来何晏。","当代词场论作者，君及江东两司马。","误杀人间白眼儿，轻言侍从无风雅。","一去承明阅岁年，秦梁蜀越多邅延。","道高不容岂有以，异哉造物操微权。","我闻柱下之裔多才子，白也飘零贺折死。","今日得君而三矣，君今不夭复不贱，又无留滞安有此。","李君李君为我楚舞，我为君歌，岁云暮矣将如何。","天生豪俊必有用，如君不信长蹉跎。","泾水一斗泥，化为一斗谷。","清者受其名，浊者食其福。","翘翘常不足，碌碌常有馀。","人者歆其实，天者宝其虚。","请君还我凌云笔，我还君家禄万石。"]},{"t":"五大夫松歌为刘博士元阳赋","f":"古风","c":["爵名五大夫，其数不必五。","何知非二松，屑屑为之补。","二松五松俱莫论，秦人已没沙丘魂。","金椎驰道迹如扫，此中惟有松枝存。","我观此松颜色古，干如虬龙质如土。","鸾楼鹤舞几千秋，犹忆当年岩畔雨。","自有此山即有松，百木之长五岳宗。","秋声不断天门路，海气长悬日观峰。","亦不为封荣，亦不因封辱。","兴亡阅尽总无情，何况区区小除目。","济北刘生达者流，题诗旧向松间游。","岁寒岂欲联三友，道远还因寄四愁。","君为博士挂冠早，松号大夫今欲老。","浮名梦幻两茫茫，不须苦作秦松考。"]},{"t":"瀛海仙人歌为任丘刘翁双寿赋","f":"古风","c":["君不见碣石高悬海上台，九河之水昆崙来。","一入淮阳五百载，地灵犹向瀛州开。","瀛州云气何超忽，北拱渔阳连汉阙。","赤畿总号帝王州，瑶堂别有神仙窟。","仙人碧发更方瞳，天姥霓衣出阆风。","台上时骑双彩凤，垆边共跨两茅龙。","当年自种蓝田璧，瑶草琳华堂下植。","学士丝纶接上台，中丞节钺通南极。","宁亲暂许帝师旋，几道封函降自天。","上食分将仙禁酒，舞衣携得御炉烟。","七十已稀况八九，如此齐眉古未有。","蓬莱谩道枣如瓜，度索虚传桃似斗。","嗟乎仙人谁与俦，瀛州平地是瀛洲。","从今岁月真多少，海水还成浅碧流。"]},{"t":"寿封君邢翁九十长歌","f":"七言古诗","c":["翁年七十八十时，我曾两度为祝辞。","今翁算十复过九，我辞三祝翁许否。","济南古有九十人，辕生伏生席上珍。","辕生为郎官不进，伏生授女口不真。","翁今有官复有子，方瞳绿发身著紫。","江南辞客久停毫，惆怅山东邢柱史。","片纸真同片玉看，鸡林传宝出长安。","书法妙入钟王室，骚命卑陵屈宋坛。","苍梧碧竹复不少，何言玉山与琼岛。","人生百岁苦多愁，如翁千龄颜更好。","泲园东望是蓬瀛，清浅当年几度经。","自是泰阶多景瑞，珠躔已现老人星。"]},{"t":"渔阳老将行为郭总戎建安赋","f":"七言古诗","c":["渔阳老将名家子，少日趋庭弄文史。","操觚屡试不见收，投笔悲歌辞故里。","桂玉萧疏客帝城，游谈无术致公卿。","烟尘正满渔阳道，挟筴还为塞上行。","尔时戚侯镇北土，七校屯营开幕府。","江南剑客拥辕门，若个骁雄健如虎。","将军自臂六钧弓，玉帐分符细柳东。","新降部落连青海，见筑亭台跨远空。","蓟门论守不论战，十年左角无传箭。","一朝碣石见桑田，台上黄金颜色变。","归与弹铗罢登坛，手挽虹霓上钓竿。","东征西讨年来事，笑踞松根白眼观。","西京有班今有郭，文武声华何磊落。","君家难弟定远兄，一片燕然铭再凿。","闻君矍铄壮不如，八十欲近七十馀。","还看世业青云远，尽出兰台旧著书。"]},{"t":"夜雨呈候吴郎","f":"七言古诗","c":["城南学作瀼西屋，炎天试借吴郎宿。","不知有何光怪发，一夜蛟龙怒相逐。","雨声彻旦雷声奔，列缺不断高空痕。","崩涛万壑吼万马，此时已齧孤亭根。","为客睡眼不曾著，遣涉滂沱问安乐。","莫将风物动乡愁，且覆青州银凿落。"]},{"t":"吴郎歌送翁晋北游京师","f":"古风","c":["旧知吴郎名，不识吴郎面。","长帆忽卷大江云，炎风五月来相见。","披衣倒屣开我关，举杯熟视成潺湲。","身如海鹤目岩电，恍然再对吾师颜。","谓我垂髫称国士，于今垂白栖空山。","生死凄凉知已报，南望其如路阻艰。","吾师当日诗名起，后驾方称王与李。","庭前秀出琼树枝，复向骚坛执牛耳。","源泉万斛泻胸中，风雨千重飞笔底。","能以遗形貌古人，还将学步嗤馀子。","白眼情知礼法疏，神心不受风尘滓。","北游一泊汶阳船，小谷城东寄数椽。","几回暝色来新涨，几夜秋声听早蝉。","仰天击剑舍我去，又向长安大道边。","昭王台畔金精拄，邹衍宫前海气悬。","吊古应歌明月塞，忧时欲赋帝京篇。","江南才人满人口，目中如君不数有。","有衣莫染洛阳尘，有钱莫买新丰酒。","汉廷公卿多世交，燕市屠沽非素友。","君王正起通天台，子虚上林出君手。","男儿七尺遇有时，安得奇才长不偶。","归来为我一扫岱峰云，夜看海中赤丸跳如斗。"]},{"t":"出塞","f":"五言律诗","c":["万里关山道，苍茫玉塞秋。","沙飞晴作雨，雾结旦成楼。","羌管霜前怨，胡笳月下愁。","酬恩怀一剑，端不为封侯。"]},{"t":"入塞","f":"五言律诗","c":["度漠灭天骄，归来意气豪。","霓旌回瀚海，羽盖指临洮。","少妇迎珠勒，亲兵赐锦袍。","勋多明主记，不解假钱刀。"]},{"t":"君马黄","f":"五言律诗","c":["宝马来西极，龙闲服上箱。","浮云金勒影，飞雪玉珂光。","骨冻长城水，蹄翻大漠霜。","美人天路远，祇觉壮心伤。"]},{"t":"战城南","f":"五言律诗","c":["塞北朝传警，城南夜合围。","旗翻明月暗，剑落晓星微。","朔气声刁斗，边霜卷铁衣。","横行期万里，酣战不知归。"]},{"t":"巫山高","f":"五言律诗","c":["巫山峰十二，缥缈倚层空。","细雨猿声外，轻云鸟道中。","江流巴子国，月出楚王宫。","旧馆今何处，茫茫梦不通。"]},{"t":"陇头吟","f":"五言律诗","c":["陇头流水别，凄响自堪惊。","月散东西影，风传远近声。","傍侵疏勒道，斜入隗嚣营。","呜咽归肠断，何时到渭城。"]},{"t":"上之回","f":"五言律诗","c":["离宫陈上郡，御辇出回中。","七校长杨北，千官细柳东。","旄头悬塞月，漏箭杂边风。","却望单于幕，萧条万里空。"]},{"t":"长安道","f":"五言律诗","c":["晨光开紫陌，春气耀丹霞。","月落新丰树，烟笼上苑花。","金羁京兆马，绣毂富平车。","侠少逢何阔，相过赵李家。"]},{"t":"洛阳陌","f":"五言律诗","c":["东都佳丽地，共指斗鸡坊。","挟弹妖童骑，当垆小妇妆。","柳花金谷暗，槐影玉沟长。","愁望飞尘起，骄騧赭汗香。"]},{"t":"折杨柳","f":"五言律诗","c":["朱楼临大道，垂柳正依依。","叶浅低愁黛，花轻上舞衣。","三河春欲尽，五岭戍初归。","何地应肠断，关前雪正飞。"]},{"t":"关山月","f":"五言律诗","c":["三五关山月，天空万里秋。","影含青海动，光度玉门流。","晓角传军垒，寒烽隐戍楼。","阴山方接战，且莫视刀头。"]},{"t":"梅花落","f":"五言律诗","c":["肠断金闺妇，愁生画阁梅。","瑶华风里落，玉树雪前开。","拂影侵罗袂，飘香上镜台。","关河春色暮，鹤勒几时回。"]},{"t":"雨雪","f":"五言律诗","c":["阴山征战地，雨雪夜霏霏。","冻缩胡儿马，寒凝汉将衣。","范恭疏勒返，苏武漠南归。","颇怪关门柳，春前作絮飞。"]},{"t":"长干曲","f":"五言律诗","c":["妾住在长干，离居岁欲阑。","洞庭归客少，浦口去人难。","雨落吴天暮，云横楚岫寒。","含情何所待，憔悴碧江湍。"]},{"t":"江南曲","f":"五言律诗","c":["采采白蘋洲，兰桡忆远游。","日悬云梦阔，天隔洞庭秋。","风物三湘道，烟波万里愁。","离居逢岁宴，掩涕倚重楼。"]},{"t":"紫骝马","f":"五言律诗","c":["宝马蹀皋兰，红尘扑绣鞍。","追风珠汗落，踏雪玉蹄寒。","北地春方涩，长城冻未乾。","一鸣思报主，不取按图看。"]},{"t":"送陈春宇太史册封楚藩二首 其一","f":"五言律诗","c":["遥遥江浦去，望望洞庭西。","拥传过三楚，乘槎入五溪。","潮平津树杳，天阔浦云低。","想见花源里，渔家路不迷。"]},{"t":"送陈春宇太史册封楚藩二首 其二","f":"五言律诗","c":["持节金闺客，星华并列侯。","遥分鸾掖色，一作兔园游。","日暮湘潭雨，天寒梦泽秋。","岂应歌故里，白雪少人酬。"]},{"t":"送张洪阳太史请急南还","f":"五言律诗","c":["宁亲承予告，秋尽理行装。","橐载兰台笔，衣残粉署香。","酒边燕月近，帆外楚天长。","旧识张华剑，寒锋起豫章。"]},{"t":"寄送朱可大南还","f":"五言律诗","c":["自别春湖去，音书已隔年。","所嗟千里梦，常在五云天。","雨色维扬树，江声北固船。","经过多逸兴，佳句向谁传。"]},{"t":"同李前峰兵部赵竹里文学集侯氏东墅信宿二首 其一","f":"五言律诗","c":["十载谈经地，重来径已荒。","野花含宿雨，秋草上空墙。","客送新醅酒，楼悬旧卧床。","晓凉凭槛立，山色四苍苍。"]},{"t":"同李前峰兵部赵竹里文学集侯氏东墅信宿二首 其二","f":"五言律诗","c":["故人复此地，不醉欲如何。","世事杯中尽，年华镜里过。","孤云留阁树，残日挂烟萝。","惆怅王孙去，门前芳草多。"]},{"t":"少虚赵丈见过二首 其一","f":"五言律诗","c":["上客回高驾，过予松桂林。","题诗白云暮，对酒飞花深。","远树浮残雨，高城下夕阴。","草玄芸阁吏，寂寞此时心。"]},{"t":"少虚赵丈见过二首 其二","f":"五言律诗","c":["经春犹卧病，长日掩衡门。","岂谓山阴棹，能寻谷口村。","世情双白眼，生事一青尊。","不浅忘年契，千秋事可论。"]},{"t":"夜泊有怀","f":"五言律诗","c":["月白夜将阑，潮平两岸宽。","倚舟人语静，过雨树声寒。","戍鼓城隅觅，船灯水际看。","所期江路迥，何处采芳兰。"]},{"t":"天津观潮","f":"五言律诗","c":["六月天山雪，寒涛亦壮哉。","声疑吹地转，浪莫蹴天开。","估舶迎风住，渔舠弄水回。","方闻通海运，万橹日边来。"]},{"t":"泊潞河驿","f":"五言律诗","c":["行尽燕齐道，来从上国游。","饱经湖上雨，寒泊驿边舟。","朔气雄三辅，关门控九州。","五陵十万户，夹岸起朱楼。"]},{"t":"哭沈虹台太史二首 其一","f":"五言律诗","c":["故人忽云没，闻报涕汍澜。","今日吴江冷，当时易水寒。","青编门下受，丹旐路旁看。","夜雨玄猿啸，浮生梦已阑。"]},{"t":"哭沈虹台太史二首 其二","f":"五言律诗","c":["思君不忍问，河上返孤舟。","岂是怀沙怨，应非蹈海游。","花残吴苑暮，鹤唳月亭秋。","肠断论交地，宫城十二楼。"]},{"t":"雨","f":"五言律诗","c":["城夕凉风起，空堂飒似秋。","片云生远岫，骤雨过重楼。","暝色阶前树，寒声峡外舟。","鸥凫何自喜，汎汎满青流。"]},{"t":"告天台为赵瀫阳太史赋","f":"五言律诗","c":["邈矣高贤操，清风华胄传。","畏知严暮夜，考履质青天。","国史千秋在，家声异代悬。","只今台上月，犹照旧炉烟。"]},{"t":"夏日偕张洪阳殿读憩龙华寺寺在苑北湖上","f":"五言律诗","c":["同过湖上寺，伏日坐清凉。","云水浮仙阙，松杉荫讲堂。","雨归莲叶净，风起稻花香。","小借支公榻，人天午梦长。"]},{"t":"夏日进讲和张洪阳年丈韵","f":"五言律诗","c":["秉烛趋丹禁，横经侍法筵。","晓凉生殿阁，旭日动云烟。","佩委天香散，花深玉漏传。","非材惭献纳，鹄立细旃前。"]},{"t":"喜雨","f":"五言律诗","c":["春来全未雨，一夜雨成霖。","触石何时聚，崇朝已自阴。","锦林花气重，金阙漏声深。","润泽占天造，殷忧慰圣心。"]},{"t":"七夕","f":"五言律诗","c":["客中逢七夕，片月倚重楼。","静对星河夜，凉生枕簟秋。","人间浑是梦，天上亦多愁。","览镜惊双鬓，空悲岁序流。"]},{"t":"秋夜","f":"五言律诗","c":["虚阁夜沉沉，秋声在树林。","山中猿鹤梦，客里岁年心。","露下莲塘冷，萤流薜幌深。","坐来销万籁，隐几自成吟。"]},{"t":"送怀上人还金陵","f":"五言律诗","c":["空门无所住，亦复忆江乡。","半偈禅心定，孤舟别路长。","锡飞吴叶冷，笔拂楚花香。","又向秋山里，钟声闭夕阳。"]},{"t":"送张静峰年兄赴河南别驾二首 其一","f":"五言律诗","c":["十年南省客，半刺领东周。","马向雪中去，人称洛下游。","关河三辅道，云物二陵秋。","别思还萧索，寒塘水自流。"]},{"t":"送张静峰年兄赴河南别驾二首 其二","f":"五言律诗","c":["承宠无迟暮，褰帷意气生。","诸侯均揖让，长吏有逢迎。","郡阁山当户，河桥柳向城。","三川风日好，偏适宦游情。"]},{"t":"送李敏斋符卿奉使省觐","f":"五言律诗","c":["只今三省佩，又下五城楼。","蓟北霜初落，淮南桂已秋。","宫云随子舍，卿月引行舟。","可奈河桥柳，年年绾别愁。"]},{"t":"送邹进士南皋谪戍贵阳二首 其一","f":"五言律诗","c":["自怜焚草日，却送看花人。","迢递三危路，飘零万死身。","长沙悲贾傅，湘水吊灵均。","总是经过地，将谁采白蘋。"]},{"t":"送邹进士南皋谪戍贵阳二首 其二","f":"五言律诗","c":["纲常千古事，怜尔志如霜。","首欲阶前碎，珠凭颔下藏。","有生心尽折，纵死骨犹香。","不似青莲客，无端谪夜郎。"]},{"t":"送习豫南太史谪居闽中二首 其一","f":"五言律诗","c":["渺渺寒江路，君今岁晏游。","十年池上佩，万里雪中舟。","仕节人谁识，浮踪水自流。","含情无可道，不独为离忧。"]},{"t":"送习豫南太史谪居闽中二首 其二","f":"五言律诗","c":["对酒不能饮，心悲握手论。","如何同舍客，忽作远游人。","世态青云冷，交情白首新。","还知明主意，宣室待词臣。"]},{"t":"寄冯志方博士二首 其一","f":"五言律诗","c":["一别褒衣客，今来几岁星。","吴钩知射斗，鲁壁记传经。","对酒春云碧，题诗暮雨青。","向时游赏地，南北各飘萍。"]},{"t":"寄冯志方博士二首 其二","f":"五言律诗","c":["幽人渺何许，江上旧儒冠。","客舍蒹葭雨，堂餐苜蓿盘。","楚天秋水阔，燕阙晓钟残。","怀袖双纨扇，因风欲寄难。"]},{"t":"张洪阳殿读待舟潞渚寄送二首 其一","f":"五言律诗","c":["昨日横门道，魂消鬓欲秋。","寸心应未远，尺素已堪愁。","对酒青灯醉，看花紫禁游。","离情如潞水，连夜只东流。"]},{"t":"张洪阳殿读待舟潞渚寄送二首 其二","f":"五言律诗","c":["归梦春来剧，那堪送远游。","身悬蜗左角，家在海西头。","天地才难尽，风尘道不谋。","河堤杨柳绿，亦欲买归舟。"]},{"t":"暮春同朱可大廷尉游摩诃庵听无弦上人弹琴因饮南园二首 其一","f":"五言律诗","c":["福地开真境，萧辰款梵筵。","百花春夜雨，一饭讲堂烟。","妙法旃檀喻，空音绿绮传。","云床容卧起，随意检诗篇。"]},{"t":"暮春同朱可大廷尉游摩诃庵听无弦上人弹琴因饮南园二首 其二","f":"五言律诗","c":["别有祗园胜，春光象外幽。","人从莲社饮，地胜竹林游。","雨色阴萝幌，钟声度石楼。","不愁归路晚，乘月可淹留。"]},{"t":"告中同可大再游摩诃庵因赠静堂禅师","f":"五言律诗","c":["寺忆同游地，联镳许再过。","人行松院少，云闭竹房多。","岁月容高枕，乾坤足放歌。","逃禅吾不厌，病骨本维摩。"]},{"t":"寄庠师周介轩先生二首 其一","f":"五言律诗","c":["传经西楚客，垂老意何如。","湖上十年梦，灯前八月书。","秋心随过雁，旧事纪衔鱼。","门下垂髫士，翛翛两鬓疏。"]},{"t":"寄庠师周介轩先生二首 其二","f":"五言律诗","c":["望望徐方道，怀人白露秋。","湖光晴载酒，山色暮登楼。","倦迹看林鸟，閒情寄海鸥。","红颜殊未老，欲接羡门游。"]},{"t":"秋日寄侯少泉参戎黔中二首 其一","f":"五言律诗","c":["万里天南极，将军尚枕戈。","一醒燕市酒，五见洞庭波。","雾急鸢常堕，江深雁不过。","东山栖隐地，何日共烟萝。"]},{"t":"秋日寄侯少泉参戎黔中二首 其二","f":"五言律诗","c":["自尔乌蛮去，寒花几度开。","萍踪儿女大，华发岁时催。","别梦随关月，离愁落陇梅。","年年秋色里，一见尺书来。"]},{"t":"赠谈易王生","f":"五言律诗","c":["翛然江上客，读易旧儒生。","道自青囊秘，名因绿简成。","汉京谈季主，蜀肆隐君平。","为叩盈虚理，因探百物情。"]},{"t":"春半","f":"五言律诗","c":["卧病忽已久，閒房鸣素琴。","徘徊紫芝意，惆怅青春深。","芳草乱迷径，残花空满林。","凭轩送高鸟，驰思渺难任。"]},{"t":"望鹤","f":"五言律诗","c":["缥缈珠庭鹤，翻飞别禁林。","初盘仙阙远，渐入海云深。","忍负乘轩宠，应非避弋心。","瑶台多旧侣，愁绝玉笙音。"]},{"t":"河西务雨夜","f":"五言律诗","c":["归舟今信宿，犹倚潞河干。","树色春汀暗，鸡声夜雨寒。","孤帆灯际落，短剑酒中弹。","明发乘流进，沧波正渺漫。"]},{"t":"漷县道中","f":"五言律诗","c":["江草正萋萋，兰桡傍古堤。","淡烟高树杪，斜日乱帆西。","陇麦蒸云动，春鸠夹岸啼。","连朝隔城市，疑入武陵溪。"]},{"t":"天津夜月","f":"五言律诗","c":["放舟乘晚浪，伐鼓注归流。","明月千帆夜，长风万里秋。","篙师探渡口，津吏指潮头。","浩荡烟波里，应怜估客游。"]},{"t":"杨柳青道中","f":"五言律诗","c":["鸣榔凌海月，捩舵破江烟。","杨柳青垂驿，蘼芜绿刺船。","笛声邀落日，席影挂长天。","望望沧洲路，从兹遂渺然。"]},{"t":"德州舟中遇李户部两山北上别后却寄二首 其一","f":"五言律诗","c":["广川西渡口，倚棹此逢君。","别久情难喻，欢多酒易醺。","江声过暮雨，帆影夹残云。","蹢躅南枝鹊，能堪羽翮分。"]},{"t":"德州舟中遇李户部两山北上别后却寄二首 其二","f":"五言律诗","c":["君登兰省去，予汎镜湖归。","两桨还相背，双星竟不违。","心期鸥作侣，生事薜为衣。","只有空山梦，愁时少雁飞。"]},{"t":"武城怀古","f":"五言律诗","c":["停桡齐赵路，河上见孤城。","故国佳公子，高台亦已倾。","川光孤屿敛，暝色片云生。","呜咽清漳水，千秋恨未平。"]},{"t":"卧病","f":"五言律诗","c":["天地长贫日，风尘卧病年。","闭门春雨后，欹枕落花前。","石火应难驻，兰膏莫自煎。","无生如可悟，吾意欲逃禅。"]},{"t":"菊花","f":"五言律诗","c":["几年京洛客，不对故园花。","今日重阳酒，还过处士家。","娟娟霜蕊静，袅袅露枝斜。","自爱贞心苦，含香阅岁华。"]},{"t":"挽赵少虚先生四首 其一","f":"五言律诗","c":["去矣云林客，伤哉艺苑豪。","百年双白鬓，万事一青袍。","道自平生拙，名堪此日高。","所悲逢圣世，汩没掩蓬蒿。"]},{"t":"挽赵少虚先生四首 其二","f":"五言律诗","c":["文雅从兹尽，荣华亦有休。","吾徒还一涕，尔辈自千秋。","旧馆青山暮，重泉白日幽。","惟馀清汶水，长绕墓田流。"]},{"t":"挽赵少虚先生四首 其三","f":"五言律诗","c":["十里春风苑，年年出汉关。","调空高渌水，俗自薄朱颜。","星彩归天上，玄经播世间。","乞铭遗札在，一读泪潺湲。"]},{"t":"挽赵少虚先生四首 其四","f":"五言律诗","c":["浮沉千古事，无力念鸿钧。","陵替存吾道，穷愁竟尔身。","冯唐空自老，原宪不知贫。","他日山阳路，谁为笛里人。"]},{"t":"寄贾广文年伯兼谢惠毡","f":"五言律诗","c":["极目漳南道，相思正杳漫。","愁时明月近，别后素书难。","雪暗芙蓉阁，春生苜蓿盘。","一毡犹寄远，应惜玉堂寒。"]},{"t":"送林丈内艰南还二首 其一","f":"五言律诗","c":["惨淡归人意，春前问去舟。","参商初两地，胶漆已三秋。","雨色低津树，江光隐驿楼。","庭花多所恨，不是锦衣游。"]},{"t":"送林丈内艰南还二首 其二","f":"五言律诗","c":["把袂怜同舍，离愁可奈何。","定知秋雁少，惟有月明多。","江上思琼树，风前废蓼莪。","无令清夜梦，不入旧鸾坡。"]},{"t":"春日同于子冲上灵岩寺四首 其一","f":"五言律诗","c":["寺自高齐辟，山从岱岳盘。","云霞千嶂晓，风雨万松寒。","路绕泉声入，花分鸟道看。","忽闻钟磬发，作礼叩旃檀。"]},{"t":"春日同于子冲上灵岩寺四首 其二","f":"五言律诗","c":["为访名山胜，来参梵帝筵。","烟霞围宝地，龙象拥诸天。","喻法昙花落，翻经贝叶传。","朗公今化石，不转谒金仙。"]},{"t":"春日同于子冲上灵岩寺四首 其三","f":"五言律诗","c":["春阴连岳麓，法界满祗林。","巨壑浮云细，悬崖白日深。","野僧閒入定，山鸟静多音。","幸共齐年侣，同皈出世心。"]},{"t":"春日同于子冲上灵岩寺四首 其四","f":"五言律诗","c":["双峰最高顶，倚杖白云扉。","树杪看人出，山坳送鸟飞。","钟声众壑满，香霭下方微。","三观凭阑得，因风欲振衣。"]},{"t":"寄张玉阳年兄汴上","f":"五言律诗","c":["我行殊未久，君亦解朝衣。","世路无工拙，时名有是非。","莫谈温室树，聊采北山薇。","梦断夷门道，秋深雁不飞。"]},{"t":"阁夜","f":"五言律诗","c":["何处夜色好，月明独倚楼。","一声长笛起，吹裂万山秋。","风露凄以冷，星河静欲流。","怀人不可见，天末眇含愁。"]},{"t":"云翠山天观和朱可大韵","f":"五言律诗","c":["碧山吾欲隐，双屐且随君。","星斗岩前接，藤萝杖底分。","泉声浑作雨，岚气稍成云。","愁对仙坛月，鸾箫午夜闻。"]},{"t":"洪范池和韵","f":"五言律诗","c":["何地探灵境，仙泉旧有名。","天光金镜冷，潭影玉壶清。","溪鸟依人立，林蝉尽日鸣。","鱼龙今寂寞，不畏夜珠惊。"]},{"t":"秋日同朱令君泛舟西汀二首 其一","f":"五言律诗","c":["旧向沧洲隐，今陪茂宰游。","笛声催画鹢，帆影挂浮鸥。","酒对青山暮，歌翻白苧秋。","花源多少路，随处有渔舟。"]},{"t":"秋日同朱令君泛舟西汀二首 其二","f":"五言律诗","c":["荡漾千峰色，轻舠入翠微。","凫迎仙令舄，鸥拂野人衣。","岸柳晴犹湿，江云冷不飞。","天风乘醉起，吹送月中归。"]},{"t":"送崔亚沂博士游齐","f":"五言律诗","c":["共作名山隐，三秋采蕨薇。","宁辞今日别，袛恐故人稀。","斗酒不得醉，白云相与归。","秋来玄雁度，可向海门飞。"]},{"t":"楼居","f":"五言律诗","c":["楼居非有好，高枕自人间。","夜色尊前月，春阴槛外山。","目随归鸟尽，心与片云閒。","未遣浮名累，虚称善闭关。"]},{"t":"夏日閒居","f":"五言律诗","c":["空林销永日，不暑亦无喧。","种药时窥圃，摊书每闭门。","雨痕侵柱础，苔色上松根。","此意应谁识，惟偕静者论。"]},{"t":"东郭草堂即事","f":"五言律诗","c":["结庐非异境，负郭少将迎。","竹屿含云影，松窗落雨声。","片峰当户出，众鸟隔林鸣。","宴坐几无念，谁知绝世情。"]},{"t":"过雨","f":"五言律诗","c":["五月不知暑，虚堂飒似秋。","残虹挂溪水，片雨过城楼。","远树斜阳驻，深山夕翠流。","晚凉思枕簟，绝爱北窗幽。"]},{"t":"小楼","f":"五言律诗","c":["小楼常有伴，端不叹离群。","牖纳青溪月，檐飞翠岫云。","自藏东观草，谁勒北山文。","最怅霜空雁，寒声静夜闻。"]},{"t":"雨中东流泉上同可大赋","f":"五言律诗","c":["风雨鸣丹谷，林亭倚翠岑。","一尊今日酒，千里故人心。","树动三秋色，泉飞万壑音。","夜凉横吹起，直欲想龙吟。"]},{"t":"中秋小岱山对月","f":"五言律诗","c":["此夜寒无奈，瑶台近斗牛。","山名真小岱，月色正中秋。","影入河蟾湿，光翻树鹊愁。","只疑参岳顶，笙鹤上宫游。"]},{"t":"山庄即事","f":"五言律诗","c":["逃名天地阔，斗室寄山椒。","地僻常无客，林深亦有樵。","饭牛春待雨，放鹤夜闻箫。","不是淮南隐，淹留未可招。"]},{"t":"有怀苏八长史","f":"五言律诗","c":["三苏称大雅，季子复能文。","老作诸侯客，名高国士群。","别心燕塞雨，旅舍鹊湖云。","家学枚皋在，词坛已策勋。"]},{"t":"入都再游摩诃禅林","f":"五言律诗","c":["为忆青莲社，重寻旧法堂。","壁题存姓字，阶树阅行藏。","觉路人天迥，春辉佛日长。","尔时京落客，曾识雨花香。"]},{"t":"再至长安见无弦上人移住法藏庵因听弹琴赋赠","f":"五言律诗","c":["别来何所住，卓锡自成林。","幡影香台静，钟声竹院深。","一花开佛土，半偈定禅心。","挥手松风里，依然未鼓琴。"]},{"t":"春日同朱可大起部冯用韫太史同游恩隆观暨侍中园纪事二首 其一","f":"五言律诗","c":["常侍先朝贵，仙宫上苑西。","野分青嶂迥，路入白云迷。","深树花初发，閒阶草自萋。","当年供奉地，犹揭旧璇题。"]},{"t":"春日同朱可大起部冯用韫太史同游恩隆观暨侍中园纪事二首 其二","f":"五言律诗","c":["小有兰亭胜，临流一放歌。","酒边横落照，花底拂回波。","何地疏狂少，吾徒聚散多。","春衣浑欲绿，知是藉烟萝。"]},{"t":"同馆诸丈城西看花二首 其一","f":"五言律诗","c":["别苑惜春残，开尊聚旧欢。","花间张绮幕，柳外簇雕鞍。","飞雪歌中度，回风掌上看。","倚阑浑欲醉，犹索酒杯宽。"]},{"t":"同馆诸丈城西看花二首 其二","f":"五言律诗","c":["十载叹西东，欢娱此日同。","容华青镜里，身世绿尊中。","花气看无赖，莺歌听不穷。","何妨归骑缓，蹀躞受东风。"]},{"t":"朱可大邀同冯太史饮摩诃庵南园步至钓鱼台夜眺还宿法藏精舍次日观慈寿浮图纪游四首 其一 南园","f":"五言律诗","c":["胜会开芳苑，春愁入远峰。","壶觞连竹树，歌咏起鱼龙。","花落空林雨，风传别院钟。","淹留公子爱，移席转从容。"]},{"t":"朱可大邀同冯太史饮摩诃庵南园步至钓鱼台夜眺还宿法藏精舍次日观慈寿浮图纪游四首 其二 钓台","f":"五言律诗","c":["行歌随步远，已到水云天。","夜色千峰月，湖光万顷烟。","衔杯心跌宕，脱帽态蹁跹。","醉眼迷归径，相看枕腹眠。"]},{"t":"朱可大邀同冯太史饮摩诃庵南园步至钓鱼台夜眺还宿法藏精舍次日观慈寿浮图纪游四首 其三 法藏庵","f":"五言律诗","c":["何必耽丘壑，居然鹿苑栖。","片云双树顶，孤月上方西。","罢酒闻清梵，探诗见旧题。","归依空品相，不省在招提。"]},{"t":"朱可大邀同冯太史饮摩诃庵南园步至钓鱼台夜眺还宿法藏精舍次日观慈寿浮图纪游四首 其四 慈寿寺阁","f":"五言律诗","c":["隔夜忘醒醉，穷游别起端。","绀林重驻马，宝阁几凭阑。","飞刹金银涌，回峰紫翠盘。","皇都多钜丽，是处有奇观。"]},{"t":"三月廿八日葛龙池朱讷斋二工部冯琢吾葛凤池二太史同游城西黄侍中园林看花四首 其一","f":"五言律诗","c":["不奈连朝病，因看上苑春。","如何五侯第，又见百花新。","日映丹霞晕，烟凝绛幄尘。","狂来无藉在，帻岸白纶巾。"]},{"t":"三月廿八日葛龙池朱讷斋二工部冯琢吾葛凤池二太史同游城西黄侍中园林看花四首 其二","f":"五言律诗","c":["真赏谁应共，风流是旧欢。","藏书周太史，襆被汉郎官。","花气尊中满，松声座上寒。","相逢休惜醉，春色欲凋残。"]},{"t":"三月廿八日葛龙池朱讷斋二工部冯琢吾葛凤池二太史同游城西黄侍中园林看花四首 其三","f":"五言律诗","c":["改席临虚榭，为欢事每奇。","控弦天苑骑，跳剑内园儿。","小榻时欹枕，疏帘久对棋。","稍闻深树里，风送桔槔迟。"]},{"t":"三月廿八日葛龙池朱讷斋二工部冯琢吾葛凤池二太史同游城西黄侍中园林看花四首 其四","f":"五言律诗","c":["谁谓长安陌，风尘此地稀。","山光相映带，野色自芳菲。","旭日薰歌扇，轻花着舞衣。","马蹄归欲懒，为送惜春归。"]},{"t":"同可大用韫登毗卢阁","f":"五言律诗","c":["人天标胜境，暇日一衔杯。","烟树重城合，香花万井开。","怀乡游子念，作赋客卿才。","愁见门前道，车尘日夜催。"]},{"t":"毗卢阁送可大南旋","f":"五言律诗","c":["梵阁俯珠林，龙宫岁月深。","几人同啸咏，此日复登临。","画栋含朝雨，青峰起暮阴。","不堪欢会地，又怅别离心。"]},{"t":"朱大司空挽歌八首 其一","f":"五言律诗","c":["有伟生民杰，鸿名日月光。","三朝熙揆路，八座丽文昌。","尚想玄圭锡，俄惊白璧藏。","平生门下士，歌薤不成章。"]},{"t":"朱大司空挽歌八首 其二","f":"五言律诗","c":["此日飙轮远，何年画阁开。","勋猷金匮史，文赋柏梁才。","故事传西省，遗恩照夜台。","凄清华表月，不见鹤归来。"]},{"t":"朱大司空挽歌八首 其三","f":"五言律诗","c":["再领河堤节，三行海国春。","吏人虔俎豆，父老怆车尘。","百折风云地，诸艰社稷身。","祇今渠畔柳，游客亦沾巾。"]},{"t":"朱大司空挽歌八首 其四","f":"五言律诗","c":["缅想三朝事，声华似梦中。","职分虞百揆，爵视汉三公。","忼慨回天力，酸辛盖世功。","惟馀秋陇上，萧瑟白杨风。"]},{"t":"朱大司空挽歌八首 其五","f":"五言律诗","c":["十载江皋卧，苍生望更频。","如何三岛梦，忽断五湖春。","南岳收真气，中朝失旧臣。","尚方双赐履，犹觉上星辰。"]},{"t":"朱大司空挽歌八首 其六","f":"五言律诗","c":["真宅归丹府，蓬壶第几城。","化龙应是剑，跨鹤不闻笙。","旧戟朱门列，新阡紫气萦。","元公车服在，馀庆属玄成。"]},{"t":"朱大司空挽歌八首 其七","f":"五言律诗","c":["传道松台路，玄冬蜃卫张。","期门分羽骑，温室出黄肠。","日月悬天藻，螭龙护帝章。","从今鹑火次，夜夜有光芒。"]},{"t":"朱大司空挽歌八首 其八","f":"五言律诗","c":["凄凉知已报，旧事总堪愁。","问字春风馆，传经夜月楼。","十年违撰屦，一夕叹藏舟。","惟有延陵剑，堪悬宰树秋。"]},{"t":"浪迹","f":"五言律诗","c":["浪迹长安陌，修途日以难。","河流谁谓广，海水自知寒。","懒嫚存愚性，婆娑耻贵官。","春深湖上雨，何处少渔竿。"]},{"t":"春日寄题东郭草堂","f":"五言律诗","c":["长忆青门郭，芳菲此日殷。","花开三月雨，春隔万山云。","夜鹤应谁怨，汀鸥且自群。","主人有归梦，莫勒北山文。"]},{"t":"月夜舟行","f":"五言律诗","c":["烟江三五夜，独月引行舟。","野色推蓬合，波光进艇留。","银蟾天上湿，乌鹊渚边愁。","那听楼头笛，怀乡鬓欲秋。"]},{"t":"仪真野泊","f":"五言律诗","c":["潮平扬子渡，宿昔系扁舟。","日落波光敛，天长岛色浮。","雨侵依岸树，晴见隔江楼。","咫尺分吴楚，茫茫万古愁。"]},{"t":"金陵江口夜泊","f":"五言律诗","c":["孤舟江上宿，秋梦耿难成。","片月中流影，千帆夜半声。","地邻桃叶渡，山近石头城。","倚舵闻吴咏，偏令旅思生。"]},{"t":"舟中家报","f":"五言律诗","c":["泽国三千里，题书转自愁。","乡心河畔草，客梦雨边舟。","月落维扬夜，江深建业秋。","归程应未远，时抚大刀头。"]},{"t":"魏国东园宴集","f":"五言律诗","c":["华馆开名会，高城倚落曛。","林芳秋过雨，竹翠午侵云。","洞夹平台入，桥通曲水分。","太平多宴乐，胜地属元勋。"]},{"t":"天界寺禅房呈讱庵棠轩二丈","f":"五言律诗","c":["萧晨游法苑，迥眺出云峰。","秋色霜前雁，寒声雨后钟。","酒随陶令醉，谈许惠休从。","何意风尘地，居然白社踪。"]},{"t":"黄仪庭司城邀集冯虚阁","f":"五言律诗","c":["振衣山畔寺，载酒寺边楼。","笛散千峰雨，砧传万井秋。","地因邀月胜，人拟御风游。","不尽萧森气，寒江正北流。"]},{"t":"九月八日罗康洲宗伯黄仪庭司成田钟台宫谕习豫南司成会集朝天宫道院","f":"五言律诗","c":["仙台邻上苑，路出冶城边。","暝落珠宫雨，寒飞玉树烟。","雁来秋水外，人醉菊花前。","明日还重九，萸觞可更传。"]},{"t":"西园诸同年夜宴","f":"五言律诗","c":["欢剧西园会，衔杯夜色前。","池塘馀暮雨，竹柏净秋天。","月出三山树，钟销九市烟。","良游俱旧侣，把臂惜华年。"]},{"t":"南曹诸友邀游祖师堂","f":"五言律诗","c":["融公栖隐处，遥在翠微巅。","径折全无地，峰回半有天。","鸟啼云洞雨，花散石堂烟。","幸假登高会，同参最上禅。"]},{"t":"牛首东峰同诸君览眺","f":"五言律诗","c":["两峰原自对，万壑远相萦。","地尽芙蓉阁，岩开薜荔屏。","江光天际白，山色雨中青。","不浅凭阑兴，吴歌倚醉听。"]},{"t":"青溪","f":"五言律诗","c":["鸣珂传旧里，弥望总污莱。","片雨湖边落，重桥苑外开。","草荒江令宅，花覆陆机台。","尚想风流地，空悲异代才。"]},{"t":"房侍御邀登观音台","f":"五言律诗","c":["杰观俯重台，烟波四望开。","霞边千树没，杯底片帆来。","霜月寒相射，云鸿暮转哀。","滔滔大江水，到海几时回。"]},{"t":"摄山夜宿予怀上人","f":"五言律诗","c":["十年浑似梦，相见各依然。","僧腊青山老，诗名白社偏。","松间对微月，竹里听流泉。","预怅明朝别，西风送客船。"]},{"t":"摄山观无尽禅师入定","f":"五言律诗","c":["师今方入定，胜果几时成。","法向无空灭，心因不住生。","湿灰犹示相，稿木可为形。","恍忽莲台上，人天涌化城。"]},{"t":"京口赠邬山人汝翼","f":"五言律诗","c":["握手秋江上，依然旧布袍。","十年燕市酒，八月广陵涛。","侠骨贫逾健，狂歌醉正豪。","不缘湖海遇，何地见风骚。"]},{"t":"京口赠陈从训文学","f":"五言律诗","c":["陈生何磊落，一剑向飘零。","雅好词人赋，休传博士经。","蘼芜春渚绿，薜荔旧山青。","莫谓江天远，微垣现客星。"]},{"t":"滁阳道中迟李棠轩年兄未至题书驿壁","f":"五言律诗","c":["江楼三日别，相逐不相逢。","回首秋山路，寒云隔几峰。","乡心朝见雁，行色夜闻钟。","何地还杯酒，应寻放鹤踪。"]},{"t":"闰月朔日道中忆东园菊","f":"五言律诗","c":["今年九月菊，应自敛芳菲。","秋色未云暮，游子将欲归。","系心霜露满，凝恨雁鸿稀。","想到尊前见，寒香正点衣。"]},{"t":"挽中立宗侯四首 其一","f":"五言律诗","c":["彼美银潢彦，名高鲁国儒。","藏书淹四部，作赋侈三都。","日瑩瑶台雪，天沉碧海珠。","十年怀旧赏，肠断绿云孤。"]},{"t":"挽中立宗侯四首 其二","f":"五言律诗","c":["谁言天路远，倏尔赋游仙。","貌忆登龙日，神疑化鹤年。","墨堂苔藓闭，画阁网丝悬。","忍望邾城墓，萧萧宰树烟。"]},{"t":"挽中立宗侯四首 其三","f":"五言律诗","c":["斯人不可见，一代失风流。","未就黄金药，先成白玉楼。","才名留海内，宾客散池头。","此夜朱门月，空悲兔苑游。"]},{"t":"挽中立宗侯四首 其四","f":"五言律诗","c":["芳草春来绿，王孙去可伤。","凭谁传旧业，先自弃高堂。","笙鹤浑疑幻，人琴尽欲亡。","平生知己泪，一湿薜萝裳。"]},{"t":"怀寄张玉阳年丈二首 其一","f":"五言律诗","c":["怊怅前年别，绵绵岁月征。","积薪从古叹，投杼至今惊。","春雪梁园道，秋江建业城。","行踪何处问，愁绝雁来声。"]},{"t":"怀寄张玉阳年丈二首 其二","f":"五言律诗","c":["聚散年来事，茫然思不禁。","薄游交道浅，久宦世情深。","别日枫林梦，愁时桂树吟。","悠悠大河水，讵尽尺书心。"]},{"t":"蓟门行四首为于大夫子冲赋 其一","f":"五言律诗","c":["渔阳开幕府，授钺鲁诸生。","庙略鱼丽阵，军符骠骑营。","悬金亲教射，画地细论兵。","半醉歌声起，风高右北平。"]},{"t":"蓟门行四首为于大夫子冲赋 其二","f":"五言律诗","c":["少年多意气，仗节赴燕云。","晓月悬弓影，春星吐剑文。","防秋歌出塞，逐敌赋从军。","未许平阳骑，横邀万里勋。"]},{"t":"蓟门行四首为于大夫子冲赋 其三","f":"五言律诗","c":["九月平原猎，材官大合围。","雪凝骄马汗，铁涩侍儿衣。","塞雁连天起，征蓬卷地飞。","此时都胆落，前队射雕归。"]},{"t":"蓟门行四首为于大夫子冲赋 其四","f":"五言律诗","c":["边烽传大漠，一剑夜临关。","鸟道千重戍，龙城万仞山。","降兵旗下出，侯骑雪中还。","苦乐行间事，魂销壮士颜。"]},{"t":"奉寄李北山先生四首 其一","f":"五言律诗","c":["当代论骚雅，公存大国风。","源流千古见，才俊一时空。","岁月鸳行外，江湖鹤发中。","倚天长剑在，犹觉气成虹。"]},{"t":"奉寄李北山先生四首 其二","f":"五言律诗","c":["先朝老法从，白首卧岩阿。","避世交游简，藏山论著多。","醒酬渔父问，醉倚雪儿歌。","大有餐霞秘，红颜盛若何。"]},{"t":"奉寄李北山先生四首 其三","f":"五言律诗","c":["雅道何寥廓，时名易陆沉。","不因今日论，宁见异时心。","剪拂千金价，宫商万籁音。","故交芜没久，亦许附词林。"]},{"t":"奉寄李北山先生四首 其四","f":"五言律诗","c":["龙门何日御，流想碧山隅。","文雅从先进，声名避大巫。","白云康乐墅，春酒步兵厨。","早晚抽簪去，能容绛帐趋。"]},{"t":"同冯殿讲琢吾夜过东邻魏光禄见泉二首 其一","f":"五言律诗","c":["一曲宫城陌，君今几卜居。","小开蒋诩径，别作子云庐。","花落藏书后，风生漉酒初。","相逢殊恨晚，倾盖意何如。"]},{"t":"同冯殿讲琢吾夜过东邻魏光禄见泉二首 其二","f":"五言律诗","c":["旧好应无厌，新知亦已欢。","衔杯迟月上，挥麈惜灯残。","世态閒堪见，浮踪拙自安。","所欣东壁影，时近夜光寒。"]},{"t":"夏日过双寺赠宝藏法师","f":"五言律诗","c":["偶过城北寺，一憩宝公堂。","午饭青精滑，新茶玉乳香。","疏钟沉片雨，高树出斜阳。","为叩经行地，浮杯海路长。"]},{"t":"代书答陶比部兰亭","f":"五言律诗","c":["落魄佳公子，天涯可定居。","适来江上使，传得箧中书。","湖海名方盛，云霄事转疏。","沉冥吾所慕，数饮态何如。"]},{"t":"赠人为金吾郎二首 其一","f":"五言律诗","c":["侠少羽林郎，承恩直建章。","臂鹰驰道侧，调马御楼旁。","夜月烧灯苑，春风蹴鞠场。","锦鞲浑未脱，十日从长杨。"]},{"t":"可大邀游张常侍园二首 其一","f":"五言律诗","c":["夙慕名园胜，因君载酒看。","山容虚榭满，竹色小楼寒。","地主更新贵，游人续旧欢。","愁中春色过，才此一凭阑。"]},{"t":"可大邀游张常侍园二首 其二","f":"五言律诗","c":["五侯开别馆，平野碧湖东。","乳燕翻槐日，鸣鸠试麦风。","水穷千树里，亭隐百花中。","却忆山园路，芳菲正满丛。"]},{"t":"寿宝藏上人二首 其一","f":"五言律诗","c":["旧检高僧传，林公胜范稀。","安禅多宝座，印法六铢衣。","雨落时闻梵，花开自掩扉。","空门忘岁月，想见劫尘微。"]},{"t":"寿宝藏上人二首 其二","f":"五言律诗","c":["寿者原无相，何因證大龄。","阶前双树老，阁上片山青。","地傍苍龙阙，函开白马经。","应怜朝市客，几日鬓毛星。"]},{"t":"送侯六参军","f":"五言律诗","c":["燕城秋欲暮，疋马送君还。","投笔书生志，鸣鞘壮士颜。","边风吹锦带，海月落刀环。","慷慨匡时略，何年出玉关。"]},{"t":"送妹倩李子授侯门教读","f":"五言律诗","c":["天涯思弟妹，见尔帝京游。","捧檄趋军府，弹冠传子侯。","黄花征路晚，玄雁塞城秋。","那值池塘恨，临风涕泗流。"]},{"t":"出塞四首为辽左李大将军赋 其一","f":"五言律诗","c":["塞上发鸣笳，军声动地哗。","三秋徵彀骑，七校选良家。","晓月分弓影，秋霜吐剑花。","主恩何以报，急为扫边沙。"]},{"t":"出塞四首为辽左李大将军赋 其二","f":"五言律诗","c":["铜符天上至，汉将出龙城。","云鸟图成阵，河山幕作营。","日凝金玦色，碛冷铁衣声。","早报匈奴灭，西京甲第成。"]},{"t":"出塞四首为辽左李大将军赋 其三","f":"五言律诗","c":["元戎新授钺，侠少远从军。","菟塞秋山合，龙城旧路分。","角声吹冻雨，旗影乱浮云。","百战城南道，方成上将勋。"]},{"t":"出塞四首为辽左李大将军赋 其四","f":"五言律诗","c":["玉节君王诏，军中夜筑坛。","金人归少府，铁骑散材官。","远戍三秋断，严霜万里寒。","功成多意气，歌舞入长安。"]},{"t":"怀周公瑕","f":"五言律诗","c":["苦忆吴门隐，翛然一钓竿。","烟霞双鬓老，天地五湖宽。","阅世凭乌几，逃名著鹖冠。","何时燕市里，重逐酒人欢。"]},{"t":"周公瑕有书见问寄答","f":"五言律诗","c":["故人何所似，契阔已多年。","旧事閒应记，新诗老更传。","花开三径雨，门闭万峰烟。","犹采相思树，封题到远天。"]},{"t":"春日有怀东郭草堂","f":"五言律诗","c":["吾庐吾所爱，虽小却宜春。","草色常经雨，花香不受尘。","归期何日定，旅梦此时真。","怨杀烟皋鹤，临风待主人。"]},{"t":"阁夜","f":"五言律诗","c":["隐几虚堂夜，幽怀谁与论。","星河临九陌，钟漏彻千门。","黯淡伤春事，踟蹰念主恩。","蘼芜今已绿，归路滞王孙。"]},{"t":"报邬山人汝翼","f":"五言律诗","c":["念子不能寐，三年阙报书。","自缘归兴久，非是故情疏。","南北无宁岁，江湖有索居。","尔时吴市隐，寥落复何如。"]},{"t":"报云翠山道士许公","f":"五言律诗","c":["契阔茅山侣，书来见素心。","养砂还守灶，种树已成林。","月出岩泉冷，花飞石洞阴。","知君相忆久，日听晓猿吟。"]},{"t":"春暮","f":"五言律诗","c":["归心无可奈，先作送春归。","细草河堤合，残花苑路飞。","梦回双阙雨，思绕旧山薇。","想到征轮动，薰风已上衣。"]},{"t":"卧病","f":"五言律诗","c":["卧病已三月，归图犹未成。","慰留明主意，推挽故交情。","御路蘼芜发，春山杜若生。","湖边小行径，处处有鱼羹。"]},{"t":"闭门","f":"五言律诗","c":["闭门多所适，懒与病相宜。","岸帻全忘沐，匡床久未移。","酒醒微雨夜，衣减落花时。","只忆河桥柳，应馀未折枝。"]},{"t":"告中冯用韫宫谕朱可大丞卿见过","f":"五言律诗","c":["卧阁荒三径，惟容二仲过。","借书酬寂寞，说剑慰蹉跎。","未路交情少，他年别思多。","东门杨柳色，执袂可如何。"]},{"t":"小阁","f":"五言律诗","c":["小阁经时卧，琴书静不哗。","丹衷犹恋主，清梦已还家。","几对春城月，虚开杜曲花。","一床馀丈室，还似住毗邪。"]},{"t":"可大游摩诃庵有诗见示赋答","f":"五言律诗","c":["少壮欢娱地，怜君只自游。","一春全卧病，旧事几经秋。","听雨花间坐，飞觞石上流。","归心将别恨，忆此更悠悠。"]},{"t":"孤雁","f":"五言律诗","c":["池上孤鸣雁，因风忆断行。","凋萧形影共，蹢躅羽毛伤。","有恨惊霜露，无心慕稻粱。","如何笼伴鸟，噭噭主人傍。"]},{"t":"上书","f":"五言律诗","c":["上书书未报，旅思且盘桓。","天意高谁问，人情巧自看。","味兼甘苦尽，色并笑啼难。","耿耿孤臣志，惟馀一寸丹。"]},{"t":"雨中遣使买舟","f":"五言律诗","c":["时节忽复易，閒居事更幽。","微风吹木杪，片雨到床头。","未解虞卿印，先寻范蠡舟。","行装书数卷，沾湿不无愁。"]},{"t":"乞休","f":"五言律诗","c":["华发登朝列，承恩岁月深。","病酬吴客问，思作越人吟。","世事容萧散，时名任陆沉。","本无匡济略，报国在抽簪。"]},{"t":"听姜生弹琴","f":"五言律诗","c":["客来山水际，为我鼓鸣琴。","月泛三湘色，松流万壑音。","焚香消昼永，啜茗到更深。","莫漫弹招隐，方怀桂树吟。"]},{"t":"寄题杨梦山先生半间楼","f":"五言律诗","c":["旧有沧洲兴，今成绿野游。","桃花千树雨，月色半间楼。","隐几山光入，开帘海气收。","却令麟阁上，图画想风流。"]},{"t":"新城馆中夜坐","f":"五言律诗","c":["独坐燕南馆，桃灯坐自深。","还家游子路，去国迩臣心。","落月征车动，寒霜客袂侵。","陆沉非避世，吾道在云林。"]},{"t":"途中书怀二首 其一","f":"五言律诗","c":["圣代无高隐，行藏亦有因。","寡交思避世，多病学全身。","止足存微尚，安危付钜臣。","所惭恩礼重，雪涕念君亲。"]},{"t":"途中书怀二首 其二","f":"五言律诗","c":["太息宗祊计，回天事信难。","三年头欲白，八疏口将丹。","璇海波能润，瑶台月正安。","汉庭多彊项，谁敢测宸欢。"]},{"t":"单家桥","f":"五言律诗","c":["十载桥边路，巾车此重过。","秋声连渤海，寒色下滹沱。","避地红尘远，还家华发多。","来时道旁柳，生意稍婆娑。"]},{"t":"暮抵德州城下","f":"五言律诗","c":["瞥见漳河水，燕齐两界分。","郡楼融晚雪，津柳挂残云。","病骨寒应倦，乡音近稍闻。","明朝看海气，遥礼泰山君。"]},{"t":"茌平道中感怀","f":"五言律诗","c":["父老迎相问，君今华发归。","云霄身自贵，家国事多违。","具迩差皆尽，同游既已稀。","畏看旧门巷，先有涕沾衣。"]},{"t":"铜城望见云翠诸山","f":"五言律诗","c":["归途今日惬，凭轼见吾山。","以尔千岩翠，惭人两鬓斑。","向来多远梦，从此闭重关。","不似终南路，依栖慕世间。"]},{"t":"立春日杨户部庐山谪官河南枉道过访","f":"五言律诗","c":["轩车来远道，执手意何长。","喜对春盘酒，愁分画省香。","士龙名入洛，司马赋游梁。","莫漫悲岐路，雄心在四方。"]},{"t":"除夕前四日送杨户部之官河南","f":"五言律诗","c":["送子岁云晏，踟蹰可奈何。","酒边生白发，雪里渡黄河。","落魄才难尽，飞扬意故多。","春风洛阳道，早晚听鸣珂。"]},{"t":"抵舍承邢知吾侍御赐问裁答二首 其一","f":"五言律诗","c":["海畔投簪始，伊谁问索居。","长安千里使，济水数行书。","世事焚鱼外，时名梦鹿馀。","平生周柱史，避俗意何如。"]},{"t":"抵舍承邢知吾侍御赐问裁答二首 其二","f":"五言律诗","c":["海岳终堪隐，风尘几倦游。","采芝随绮季，种竹待羊求。","月迥春天树，江寒雪夜舟。","何时芳驾至，尊酒一淹留。"]},{"t":"归日王兴甫文学于子冲大参来视","f":"五言律诗","c":["山斋春欲尽，上客到羊求。","对月休愁思，看山且醉游。","蚁封知是梦，驹隙信如流。","不见芄兰侣，辞官已白头。"]},{"t":"挽赵秀才竹里二首 其一","f":"五言律诗","c":["别来能几日，溘已隔重泉。","不作鹏抟海，翻成鹤上天。","谈经溪阁月，对酒竹楼烟。","回首东山社，伤心涕泫然。"]},{"t":"挽赵秀才竹里二首 其二","f":"五言律诗","c":["连年家难剧，双泪日沾缨。","已叹无兄弟，谁堪丧友生。","延陵荒草合，管子旧台倾。","更甚山阳路，空闻笛里声。"]},{"t":"泰山道中","f":"五言律诗","c":["地僻尘踪少，山深石路斜。","雨中过佛院，云里见人家。","雊雉飞春麦，啼莺绕落花。","流亡今欲尽，几处有桑麻。"]},{"t":"泰山天门禅堂逢傅柱史金沙赠别","f":"五言律诗","c":["含桃花欲落，山下遇君时。","雨过空王殿，天晴岳帝祠。","相看芳杜色，各有白云期。","不似风尘路，偬偬叹别离。"]},{"t":"泰山绝顶对酒","f":"五言律诗","c":["茫茫今古事，欲问岱君灵。","汉柏虚称观，秦松枉勒铭。","此生游已倦，何地酒能醒。","杖底千峰色，依然未了青。"]},{"t":"下泰山游三阳观","f":"五言律诗","c":["半岭通仙界，萦回岳麓西。","已看三观迥，犹觉万峰低。","暮雨瑶华落，春云玉洞迷。","游情浑未减，缥缈望丹梯。"]},{"t":"饮三阳观绝顶对月","f":"五言律诗","c":["孤亭堪倚啸，一醉斗牛边。","袖拍千峰月，觞飞万树烟。","花前鸾吹度，海上鹤书传。","借问三宫路，今当几洞天。"]},{"t":"游仙词四首赠三阳观昝云山道士 其一","f":"五言律诗","c":["寰区不足步，聊作小游仙。","牒秘丹缯字，山藏绿玉篇。","石梁云外挂，瑶岛月中悬。","欲问餐桃客，蓬莱更几千。"]},{"t":"游仙词四首赠三阳观昝云山道士 其二","f":"五言律诗","c":["五游凌碧落，彷佛见乘鸾。","瑶水银为阙，蓬丘玉作坛。","飞尘成大药，毁灶出神丹。","旧遇华山博，曾将六箸看。"]},{"t":"游仙词四首赠三阳观昝云山道士 其三","f":"五言律诗","c":["由来称福地，自合有仙才。","萧史吹笙下，栾巴噀酒回。","云轩通紫阙，月宇逼丹台。","谢手尘中客，年光漫自颓。"]},{"t":"游仙词四首赠三阳观昝云山道士 其四","f":"五言律诗","c":["辞家慕冲举，名岳且依栖。","辽左迟归鹤，淮南见去鸡。","玄霜堪入药，白石总如泥。","试访清都宴，云门路欲迷。"]},{"t":"子冲携尊方山相候因谋卜筑","f":"五言律诗","c":["百里行厨至，追欢有报书。","春城开腊蚁，别墅罩河鱼。","白社能留客，青山可卜居。","未须烦地主，十笏是吾庐。"]},{"t":"灵岩竹房对雨","f":"五言律诗","c":["旧日题名处，山窗竹未残。","重游春欲暮，复向雨中看。","暝色来千嶂，寒声到万竿。","应添禅悦味，新笋入盘餐。"]},{"t":"灵岩主僧邀游五峰亭遇雨即事","f":"五言律诗","c":["已成三日醉，更上五峰亭。","岭外云犹碧，尊前雨半青。","唯然南岳偈，莞尔北山铭。","向夕传清梵，泠泠自可听。"]},{"t":"灵岩禅室子冲兴甫夜饮大醉","f":"五言律诗","c":["对酒不能醉，明星已在天。","放歌知爱客，纵饮是逃禅。","世事惊心后，时才屈指边。","乾坤吾党在，把臂意茫然。"]},{"t":"买洪范泉旁隙地规作园池","f":"五言律诗","c":["谁言泉上筑，不作辋川看。","山色宜书幌，溪阴可钓竿。","分流防短岸，樊圃避危湍。","稍待西畴毕，移家事未难。"]},{"t":"夏日黄石山庄即事","f":"五言律诗","c":["山居涉长日，散发不容簪。","酒熟床头漉，诗成枕上吟。","移花常待雨，种树稍成阴。","欲叩金闺侣，何须此陆沉。"]},{"t":"夏日山居周砺斋太史奉使周藩过邑见访赋赠二首 其一","f":"五言律诗","c":["送君远行役，六月过山城。","细雨钟前落，微风树里生。","茶瓜凉夜色，车马故交情。","却忆横门道，分途岁已更。"]},{"t":"夏日山居周砺斋太史奉使周藩过邑见访赋赠二首 其二","f":"五言律诗","c":["夏日门常掩，何因驻使车。","时同河朔饮，地似武陵渔。","天地容高枕，烟霞有定居。","莫将奇字问，独少著成书。"]},{"t":"因周太史使还海上寄杨鍊庵丈及澄上人一首","f":"五言律诗","c":["苦忆东林侣，逢人附报书。","花残陶令宅，月出远公庐。","世念归应尽，幽怀病未疏。","三山知有路，正拟戒游车。"]},{"t":"午日独酌","f":"五言律诗","c":["邑里逢佳节，无欢坐草亭。","年华双鬓白，心事一杯青。","柳畔惊鶗鴂，花前叹鹡鸰。","少人与同醉，不是独为醒。"]},{"t":"山庄独居","f":"五言律诗","c":["岂无山水慕，只是旧游孤。","陇上遭田父，垆边问酒徒。","颓年资药饵，野性适江湖。","回首鹓行地，春风满鹧鸪。"]},{"t":"闻胡竺西山人被絷有怀二首 其一","f":"五言律诗","c":["慷慨关东侠，词场旧所欢。","如何燕市筑，忽作楚臣冠。","翻覆人情险，倾危世路难。","夜来丰狱剑，虹色为君看。"]},{"t":"闻胡竺西山人被絷有怀二首 其二","f":"五言律诗","c":["长铗今何适，从军赴桂林。","谈天时网密，逐客庙谟深。","寥落词人赋，凄凉国士心。","沅湘何处望，愁绝雁书沉。"]},{"t":"十月四日张就山初至同饮东园菊花下作","f":"五言律诗","c":["上客来何暮，山斋菊欲残。","犹馀秋径色，聊待酒人欢。","艳蕊迎霜立，寒香浥露餐。","晚酣休便去，新月出林端。"]},{"t":"安我素吏部倚舟过访酬赠","f":"五言律诗","c":["沙边能系缆，相顾到林庐。","斗室虚高枕，衡门有驻车。","桃灯秋雨后，漉酒菊花初。","好在山公启，休忘北阙书。"]},{"t":"冬夜宿香山寺","f":"五言律诗","c":["一宿招提境，匡床坐夜分。","山深迟见月，石冷细生云。","仙梵林中发，名香座上焚。","老僧应出定，时觉语相闻。"]},{"t":"暮抵吴家渡杨令君携酒宿王户部别业","f":"五言律诗","c":["十月荒山道，迷茫起暮阴。","凄风吹古渡，寒雾结平林。","地主尊垒远，山家巷路深。","因过故人宅，怀旧一悲吟。"]},{"t":"往吊于子冲黄家渡口大雪","f":"五言律诗","c":["寒冬涉济水，雨雪满征裘。","欲解留徐剑，犹疑访戴舟。","马蹄临渡涩，人迹过山稠。","渐近齐州路，伤心触旧游。"]},{"t":"雪中济南道上携张就山同行忽失所在诗以觅之","f":"五言律诗","c":["雨雪携同好，行行失所如。","细寻东郭履，久驻信陵车。","误恐迷花径，寒应殢酒庐。","居然成间阔，暝色野踌蹰。"]},{"t":"张山人告行灯下言别","f":"五言律诗","c":["幽居无与晤，殊喜故人来。","秉烛频开卷，逢花数举杯。","寒云江上树，冻雪陇头梅。","明发黄山路，离愁不可裁。"]},{"t":"送张就山西游赵国及赴萧大司马之召","f":"五言律诗","c":["关河冰雪满，游子去何之。","长揖云中幕，高谈邺下诗。","西园飞盖夜，北塞勒铭时。","回首秋山赏，能忘桂树枝。"]},{"t":"查虞皋仪部道出济上遣书赐问赋答二首 其一","f":"五言律诗","c":["别绪三秋迥，书来慰梦思。","林中醒酒后，河畔倚舟时。","雪静关山影，云生涧壑姿。","岁寒无可赠，惟有折松枝。"]},{"t":"查虞皋仪部道出济上遣书赐问赋答二首 其二","f":"五言律诗","c":["有怀江左彦，夙昔共兰襟。","报国青萍器，承家玉树林。","郎曹双管旧，禁漏五云深。","无恙西山色，犹堪柱笏吟。"]},{"t":"壬辰冬月连营兄弟二葬抚今追昔潸然有感聊赋四首 其一","f":"五言律诗","c":["无限伤心地，连朝薤露吟。","仁兄归永夜，爱弟托荒岑。","华萼俱凋落，松楸渐郁森。","寸肠摧断久，犹自涕沾襟。"]},{"t":"壬辰冬月连营兄弟二葬抚今追昔潸然有感聊赋四首 其二","f":"五言律诗","c":["累岁遭家难，心悲不可论。","鲁门疑远梦，易水送归魂。","取次栽坟树，从新拭泪痕。","乞休曾有疏，酸侧动天阍。"]},{"t":"壬辰冬月连营兄弟二葬抚今追昔潸然有感聊赋四首 其三","f":"五言律诗","c":["门庭思往日，文雅盛当时。","共目三珠树，相辉五桂枝。","一朝虚枕被，万事罢埙篪。","怊怅馀生在，衰颜欲对谁。"]},{"t":"壬辰冬月连营兄弟二葬抚今追昔潸然有感聊赋四首 其四","f":"五言律诗","c":["久客归何倚，孤踪只自怜。","顾瞻鸿雁影，吟叹鹡鸰篇。","翰墨藏春雨，池塘惨暮烟。","经过酬倡地，无处不潸然。"]},{"t":"石门道中","f":"五言律诗","c":["风雨石门道，凄凄衣袖单。","人家烟树隔，山径草花寒。","萧索前朝寺，荒芜何代坛。","十年来往路，立马一长叹。"]},{"t":"再过汶上路凤冈民部出送河桥留别","f":"五言律诗","c":["邑里经年别，重逢春草芳。","一杯临汶水，三月绾垂杨。","豪侠齐公子，风流汉省郎。","乡山多胜赏，后会莫相忘。"]},{"t":"任城魏松轩山人携琴见过从游溪山数日书赠","f":"五言律诗","c":["自遣樊中累，常多物外游。","看君携绿绮，访我到沧洲。","月色和烟映，泉声作雨流。","吾庐山水际，是处可淹留。"]},{"t":"南溪石上听魏山人弹琴送别","f":"五言律诗","c":["溪树午萧森，因君理素琴。","乍将流水引，写作落霞吟。","别鹤飞何远，游鱼跃自深。","只今怀往路，何处觅知音。"]},{"t":"吴门周画师从游溪上数日赋赠","f":"五言律诗","c":["林壑看如画，幽人此地过。","弹琴流水近，对酒暮云多。","地僻无来往，山深足啸歌。","床头有匹练，试为扫烟萝。"]},{"t":"秋日从诸亲友饮城南溪上遇雨呈亭山周师二首 其一","f":"五言律诗","c":["雨后南溪水，新添几尺流。","壶觞陪父老，笑语到林邱。","扫石聊施簟，烹鱼旋摘钩。","酒阑更坐起，随意看凫鸥。"]},{"t":"秋日从诸亲友饮城南溪上遇雨呈亭山周师二首 其二","f":"五言律诗","c":["阔略师生礼，相将把钓竿。","青山閒共适，白发醉同欢。","雨色尊前近，滩声树杪寒。","踏泥连骑缓，归路不知难。"]},{"t":"六月十二夜可大小酌即事","f":"五言律诗","c":["客乘残雨至，席对晚凉开。","酒畔移灯去，花间送月来。","风流河朔会，倡和柏梁才。","更忆长杨路，青葱玉树栽。"]},{"t":"七夕可大小会即事和韵","f":"五言律诗","c":["小阁驱残暑，当筵夜色青。","楼头生片月，河畔度双星。","桃叶虚称扇，松枝戏作屏。","秋声惊白纻，沉醉不能听。"]},{"t":"和可大七夕书怀","f":"五言律诗","c":["新凉浮玉宇，客馆易为愁。","天上明河夜，人间白露秋。","逃名惟对酒，乞巧讵登楼。","自有丰城气，迢迢映斗牛。"]},{"t":"江右黄淮朐文学可大客也以书授其弟侄东游赋赠","f":"五言律诗","c":["南州有高士，邂逅见风流。","雅醉荆卿酒，常随郭泰舟。","穷经探鲁壁，作客佩吴钩。","门下推师授，名成两夏侯。"]},{"t":"陪朱可大丈游陶山幽栖寺绝顶同张士师李鸿胪黄文学赋","f":"五言律诗","c":["幽栖真此地，绝壁到人稀。","石角斜钩杖，藤稍曲桂衣。","壶飧高洞险，钟磬下方微。","共有登临兴，谁能不醉归。"]},{"t":"陶山怀古","f":"五言律诗","c":["越相何年隐，齐山旧有名。","地连肥子国，路出铸乡城。","洞杳秋云白，岩深古木平。","临池怀往迹，颇识种鱼情。"]},{"t":"陶山赠张东山士师","f":"五言律诗","c":["陶朱今不见，君是鲁朱家。","侠骨千金剑，仙炉五色霞。","生涯随畜牧，乡语话桑麻。","早结东山隐，惊看鬓有华。"]},{"t":"游云台山","f":"五言律诗","c":["窈窕黄山路，秋云入几重。","寒声泉上竹，古色寺前松。","地隐秦时洞，天连月观峰。","由来真迹秘，不许世人逢。"]},{"t":"同可大宿黄山张氏精舍","f":"五言律诗","c":["谷口隔疏篱，林深鸟不啼。","石泉萦户转，山果亚枝低。","涧壑参差映，藤萝咫尺迷。","苦无向平累，聊可共依栖。"]},{"t":"同可大对饮黄山玉龙峡上","f":"五言律诗","c":["看山意不厌，复此濯尘缨。","涧落飞虹影，泉飘喷玉声。","隔花分送酒，凿石共题名。","相对濠梁意，翛然少世情。"]},{"t":"泰山客馆送朱可大登岳","f":"五言律诗","c":["息驾泰山麓，何以慰所思。","送君九节杖，拄上五松枝。","涧底出云处，夜中观海时。","同游不同醉，应忆旧题诗。"]},{"t":"重游三阳观宿","f":"五言律诗","c":["曾向春山宿，重来似旧青。","坛风落橡栗，岩雨长芝苓。","试觅长生药，聊翻内景经。","不知凉夜永，星斗挂疏棂。"]},{"t":"三阳观木末亭晚眺因迟可大未至","f":"五言律诗","c":["木末堪凭槛，秋空四望开。","晚烟迷汶水，落日满徂徕。","酒忆垆头醉，人从岳顶回。","那逢摇落候，萧瑟易悲来。"]},{"t":"傲来山","f":"五言律诗","c":["不断青螺色，依然万仞峰。","云间翔鷟鸑，天杪秀芙蓉。","岳界三千里，仙闾十二重。","神功何处敛，此地宅蛟龙。"]},{"t":"同诸君饮竹林寺树下","f":"五言律诗","c":["灵岳多真境，禅宫路更深。","五峰常隐日，双树自成林。","涉涧逢瑶草，临流漱玉琴。","晚钟归骑缓，沉醉北山岑。"]},{"t":"观泰山百丈崖瀑布","f":"五言律诗","c":["尽日水声中，还看匹练空。","盘涡喧万马，削壁斗双虹。","派抉天河落，源从月窟通。","固知灵境异，融结骇神功。"]},{"t":"望仙影岩","f":"五言律诗","c":["何劫飞来影，分明鹤上仙。","侧身疑面壁，作礼似朝天。","观化兴云雨，凭虚阅岁年。","扶桑终日在，几见海成田。"]},{"t":"西汀临汎呈印泉舅氏二首 其一","f":"五言律诗","c":["秋水寒塘净，兰樯别渚通。","林端悬片雨，蘋末起微风。","孤屿浮波外，长天一棹中。","渔竿堪自老，不是慕非熊。"]},{"t":"西汀临汎呈印泉舅氏二首 其二","f":"五言律诗","c":["西汀怀旧隐，秋杪片帆来。","落照樽前树，寒烟水上台。","舟移明镜转，云尽画屏开。","笑语淹吾舅，浮槎夜未回。"]},{"t":"乙未十月傅金沙侍御殷洗心舍人过访山中赋赠","f":"五言律诗","c":["命驾何相值，开尊夜向寒。","风高边雁尽，霜冷菊花寒。","天地吾徒在，江湖此会难。","占星应有地，总傍少微看。"]},{"t":"冬初傅金沙侍御过访因韵赋和","f":"五言律诗","c":["百里寒山道，劳君问隐居。","玄言聆喻马，往事笑焚鱼。","岳色青尊外，秋声白苧馀。","良游知不厌，卜筑意何如。"]},{"t":"秋日閒居有怀黄大宗伯","f":"五言律诗","c":["万里温陵道，含情忆旧游。","梦迷明月夜，人老白蘋秋。","海阔休看雁，山深自倚楼。","何时江路柳，重见木兰舟。"]},{"t":"山中寄徐少宰丈","f":"五言律诗","c":["契阔同心侣，多年叹索居。","吴门遥系马，鲁国久悬舆。","岁晚怜交态，天长阙报书。","悠悠清汶水，一为觅双鱼。"]},{"t":"暮春邢子愿侍御过访邀登虎窟山洞遇雨和韵","f":"五言律诗","c":["春尽无登眺，留山待客来。","残花岩际落，野席雨边开。","雾合峰阴树，云飞洞口台。","醉忘归路远，昏夜踏泥回。"]},{"t":"子愿过宿云楼小酌用韵","f":"五言律诗","c":["看山常独醉，无奈索居何。","那值春光暮，能邀上客过。","钩帘芳树近，挥麈白云多。","欲似南楼月，胡床发啸歌。"]},{"t":"子愿饮东流池上","f":"五言律诗","c":["春入桃源路，飞觞日未斜。","溪头逢燕子，池面落杨花。","听树萧萧雨，看山片片霞。","与君忘世虑，沈醉即为家。"]},{"t":"子愿饮天柱峰下赠吴人薛文学南旋","f":"五言律诗","c":["缥缈高峰下，相从蹑屐来。","攀崖行觅草，欹石坐传杯。","半岭开琼观，中天倚玉台。","吴门应系马，有客岱宗回。"]},{"t":"倚槛","f":"五言律诗","c":["倚槛多佳气，高峰敛夕曛。","林梢斜上月，麦陇细蒸云。","宵柝连城动，田歌隔舍闻。","空岩响麋鹿，地僻亦惊群。"]},{"t":"忆鹤","f":"五言律诗","c":["独鹤曾为友，翩飞已隔年。","几时归华表，何处觅青田。","影断空山月，声凄远树烟。","瑶台应有伴，宁忆旧林泉。"]},{"t":"放鹿","f":"五言律诗","c":["园鹿知无恙，羁栖亦自愁。","本非笼槛物，岂有稻粱谋。","缥缈云中驾，虚无海上游。","只应常放汝，相伴踏林丘。"]},{"t":"楼月","f":"五言律诗","c":["小楼凉不寐，白月静娟娟。","半岭含秋气，千林灭晚烟。","海边烽火动，塞上羽书传。","此夜关山曲，寒光万里悬。"]},{"t":"萝轩","f":"五言律诗","c":["室成无四壁，为藉绿萝阴。","五月清风至，空庭白日深。","野花犹恋树，径竹未成林。","幸少藩篱隔，长堪对远岑。"]},{"t":"田父","f":"五言律诗","c":["欣承田父过，相对亦陶然。","泥客携村酒，迎神醵社钱。","禾麻新受雨，桑柘远成烟。","解问兰台史，还书大有年。"]},{"t":"晓望","f":"五言律诗","c":["早凉开野曙，迥眺出岩扉。","日旭风吹面，林香露湿衣。","流莺深树语，掉雀野田飞。","来往逢村叟，相将荷蓧归。"]},{"t":"偶成","f":"五言律诗","c":["传道东封事，扶桑路渺漫。","不成威百粤，何取度三韩。","零落王人节，低垂大将坛。","可怜当日画，犹欲斩楼兰。"]},{"t":"漫题","f":"五言律诗","c":["安东通汉节，消息久茫茫。","事异降疏勒，名殊受越裳。","先朝多典故，属国有彝章。","何太苍黄甚，为谋但可伤。"]},{"t":"白庄对雨","f":"五言律诗","c":["山楼三日雨，御祫不胜寒。","积水深苔径，颓墙损药栏。","牛羊邻巷狭，凫鹭野塘宽。","想见清溪涨，应难著钓竿。"]},{"t":"悯雨","f":"五言律诗","c":["七日复七夜，雨声檐际悬。","遥山开复隐，野水断仍连。","禾实真生耳，苔文漫作钱。","为农资百亩，不是敢忧天。"]},{"t":"晚霁","f":"五言律诗","c":["忽看云雾敛，返照逐归鸦。","壅水笼漂麦，分畦护种瓜。","楼阴新见月，山气渐成霞。","远忆辽阳戍，军声急暮笳。"]},{"t":"雨中谢周师送酒","f":"五言律诗","c":["积雨不出户，空斋自检书。","如何陶令酒，亦到子云庐。","闭阁青山少，开帘远树疏。","沈冥应独醉，无计屈高车。"]},{"t":"寄儿纬京师","f":"五言律诗","c":["炎风吹去马，几日到长安。","要识人间路，休怀膝下欢。","夙宵常展卷，凉燠自加餐。","世业馀丛桂，还从上苑看。"]},{"t":"閒居","f":"五言律诗","c":["野筑千林敞，閒居万事慵。","朝廷疏记忆，里巷少过从。","雨急萧萧柳，风疏落落松。","传呼何太剧，海上举边烽。"]},{"t":"七夕溪舟初成同施还初文学王改予武元游汎","f":"五言律诗","c":["为嗜城南隐，临溪理钓舟。","适逢河鼓会，小试武陵游。","斜日悬渔网，凉风激棹讴。","冯君槎上汉，吾道在沧洲。"]},{"t":"八月十三日诸亲溪亭汎舟二首 其一","f":"五言律诗","c":["远集亭边骑，新成槛外舟。","岁时开小会，信宿是中秋。","倚杖迎岚气，褰裳渡石流。","泠然尘外赏，无谢竹林游。"]},{"t":"八月十三日诸亲溪亭汎舟二首 其二","f":"五言律诗","c":["晚凉人未醉，移席汎烟波。","酒远杯常待，舟平岸易过。","鸟边浮晚吹，花底度轻歌。","早见东林月，秋光逼绛河。"]},{"t":"中秋同施还初文学携门下诸友汎舟南溪","f":"五言律诗","c":["别馆依泉石，方舟集俊英。","陈诗吴季子，讲业鲁诸生。","云树空中影，笙歌水上声。","回桡应已夜，山月好相迎。"]},{"t":"中秋同诸友南溪望月","f":"五言律诗","c":["此际秋无奈，停舟望碧岑。","月华岩际满，夜色水边深。","影灭银河浪，光团桂树林。","南楼闻啸咏，谁识庾公心。"]},{"t":"九日无菊","f":"五言律诗","c":["山斋逢九日，怅望晚天霞。","去岁曾飞雪，今年未见花。","秋声风落木，寒色雨侵沙。","幸有杯中物，犹同处士家。"]},{"t":"送武举王生北上","f":"五言律诗","c":["侠少多奇节，悲歌气不平。","偶探黄石简，欲赴白登城。","锦瑟垆头醉，雕戈马上横。","功成报明主，耻作鲁诸生。"]},{"t":"寄吴观我太史","f":"五言律诗","c":["闻道金闺侣，名山住已深。","淹留依桂树，栖息傍祗林。","真偈閒常讽，新诗静自吟。","论思虚上列，悬切故交心。"]},{"t":"秋日寄邹南皋吏部","f":"五言律诗","c":["美人南国渺，江上有枫林。","道为谈天重，名因避地深。","十年曾酒会，千里片鸿音。","念尔关隆替，能忘报国心。"]},{"t":"对雪闻方子公行赋送","f":"五言律诗","c":["寥寥逢岁宴，飞雪逗年华。","霰薄初成雨，风高渐作花。","寒光连兔苑，朔气度龙沙。","游子今何适，关山路正赊。"]},{"t":"雪中独酌","f":"五言律诗","c":["北风一以凛，雨雪昼霏霏。","酒畔疑花落，春前学絮飞。","田家占岁事，海国念戎机。","万里三韩道，征人几队归。"]},{"t":"冯用韫宗伯订约西游登岱过期未至怀望遣闷二首 其一","f":"五言律诗","c":["自得高丘约，脂车已隔年。","如何期屡易，直作信空传。","海色云门上，秋光日观前。","侧身凝望眼，端拟四愁篇。"]},{"t":"冯用韫宗伯订约西游登岱过期未至怀望遣闷二首 其二","f":"五言律诗","c":["海上碧云断，佳期谁为留。","已看过九日，原约近中秋。","岁晚常思会，身轻未厌游。","迟回应有为，无处问书邮。"]},{"t":"上坤山月岩寺陈铁峰孟我疆诸君会讲处也","f":"五言律诗","c":["何代标金刹，层崖半倚天。","松门低落日，石窦泻鸣泉。","野旷寒烟积，山高细路悬。","因怀莲社客，惆怅讲堂前。"]},{"t":"过阳谷店山下问小洞庭遗迹是唐时东平太守苏源明宴处","f":"五言律诗","c":["蚕尾峰头路，当年小洞庭。","污邪馀水国，文物闭山灵。","野草微茫白，川云黤惨青。","犹疑歌舞地，笳鼓震空溟。"]},{"t":"送吴澄阳文学还越","f":"五言律诗","c":["翩翩江左彦，藻思薄云天。","观乐重游鲁，谈经旧客燕。","归舟鸿雁后，别酒菊花前。","明岁长杨猎，看君赋草传。"]},{"t":"哭元戎少泉侯兄八首 其一","f":"五言律诗","c":["故国逢今日，元枢失旧臣。","人间销电露，天上化星辰。","磊落英雄气，悲凉骨肉亲。","哀歌转难就，握管涕盈巾。"]},{"t":"哭元戎少泉侯兄八首 其二","f":"五言律诗","c":["少年抛翰墨，笑入五陵场。","一剑横秋色，千金去故乡。","韬钤分禁旅，节钺奠夷荒。","何意将军树，风残一夜霜。"]},{"t":"哭元戎少泉侯兄八首 其三","f":"五言律诗","c":["男儿身手健，壮岁握兵符。","试买千金骏，轻关十石弧。","登坛名已遂，裹革志犹孤。","回首黔中路，年年泣鹧鸪。"]},{"t":"哭元戎少泉侯兄八首 其四","f":"五言律诗","c":["羽书今正急，谁勒玉关铭。","穷海缠兵气，中原落将星。","侠场思意槩，蛮府慑威灵。","尚欲随风雨，鞭螭下紫庭。"]},{"t":"哭元戎少泉侯兄八首 其五","f":"五言律诗","c":["少小追游地，今来白发新。","半生羁仕路，垂老恋交亲。","间阔无经月，欢娱得几春。","可怜花底醉，已作梦中人。"]},{"t":"哭元戎少泉侯兄八首 其六","f":"五言律诗","c":["吾家门巷改，池草尽成尘。","念我歼同气，依君岂异人。","徵歌花坞夜，载酒竹溪春。","旧侣无多在，相看涕泗频。"]},{"t":"哭元戎少泉侯兄八首 其七","f":"五言律诗","c":["朝来过旧馆，遗迹总堪嗟。","晓月沈弓影，秋霜涩剑花。","护羌元入塞，去病不为家。","素业青门外，惟馀数亩瓜。"]},{"t":"哭元戎少泉侯兄八首 其八","f":"五言律诗","c":["摄提星入次，单阏鸟来旋。","正近悬弧旦，翻成挂剑年。","祠方同畏垒，冢得象祁连。","汗血俱龙种，青箱事可传。"]},{"t":"秋日荅常心吾中丞寄问二首 其一","f":"五言律诗","c":["别后渺愁予，秋来得报书。","未过衡渚雁，早下武昌鱼。","天地方多难，江湖有索居。","间踪休更问，头白侣樵渔。"]},{"t":"秋日荅常心吾中丞寄问二首 其二","f":"五言律诗","c":["何地容高隐，江楼万竹青。","晓猿谙报客，夜鹤解听经。","天迥悬卿月，山深阅岁星。","会传宣室召，莫勒草堂铭。"]},{"t":"赠诗僧","f":"五言律诗","c":["拥锡来吴岳，诠经住鲁城。","王孙除馆待，郡牧扫门迎。","藻思烟霞润，风神水月清。","谈诗吾已倦，亦欲学无生。"]},{"t":"送朱元长北试京兆","f":"五言律诗","c":["西风吹桂树，欲发上林枝。","河畔停舟夜，花前对酒时。","愁深谈旧事，别久见新诗。","几日泥金到，山中有梦思。"]},{"t":"送方胥成山人南游淮上","f":"五言律诗","c":["君行复几岁，今夕问归舟。","客久黄金尽，天寒白露秋。","寸心酬侠气，斗酒结离愁。","莫叩淮南幕，中丞抱国忧。"]},{"t":"赠邬章甫道契","f":"五言律诗","c":["翛然林壑秀，家学似枚皋。","作客怀长铗，惊人试彩毫。","旅愁沧海月，归梦广陵涛。","努力攻骚雅，时名尔易高。"]},{"t":"雪中杏花","f":"五言律诗","c":["春寒无可奈，愁思入韶华。","更落瑶台雪，还添上苑花。","凝妆聊傅粉，待晕始成霞。","试汎山阴棹，东风满若邪。"]},{"t":"雪后杏花","f":"五言律诗","c":["花时惊雪落，雪后见花开。","夜色梁园度，春香汉苑来。","飘帘还似雨，闻笛半疑梅。","冻涩枝头燕，依然社日回。"]},{"t":"送徐南龙令君南旋","f":"五言律诗","c":["君行良不住，河上理兰樯。","客梦齐山隔，乡心楚塞长。","春归见芳草，人去思甘棠。","日望双凫影，翩飞近尚方。"]},{"t":"赠余古仙山人","f":"五言律诗","c":["别久鬓如丝，金门老画师。","相逢春雨夜，正是落花时。","能事江湖得，浮踪岁月私。","旧游今欲尽，君去可依谁。"]},{"t":"三月廿八日饮侯六山庄四首 其一","f":"五言律诗","c":["问讯东山馆，名花几树开。","不愁春色去，自有故人来。","淑影明衣袖，香风近酒杯。","未须尊俎具，且共倚亭台。"]},{"t":"三月廿八日饮侯六山庄四首 其二","f":"五言律诗","c":["地僻宜佳会，春归待主人。","蝶惊红雨骤，莺狎录条新。","但听歌盈耳，休辞酒入唇。","不堪回首地，万里一风尘。"]},{"t":"三月廿八日饮侯六山庄四首 其三","f":"五言律诗","c":["少小欢游地，君家旧竹林。","每逢春酒夜，常醉绿萝阴。","树密云过慢，楼高月上深。","婆娑看老态，颇识故交心。"]},{"t":"三月廿八日饮侯六山庄四首 其四","f":"五言律诗","c":["闻钟人未散，倚席兴偏长。","曲按新声度，花从静夜香。","青尊何地少，白发几人狂。","更订明朝约，过予旧草堂。"]},{"t":"东园牡丹小会四首 其一","f":"五言律诗","c":["老去怜交态，春归念岁华。","还将今日酒，同对故年花。","色染丹台露，香流玉洞霞。","惟应栏槛小，不似五侯家。"]},{"t":"东园牡丹小会四首 其二","f":"五言律诗","c":["园林刚半亩，木药满亭台。","向日朝犹敛，迎风夜尽开。","酒从新岁待，客是隔城来。","俗杀平章第，朱门锁绣堆。"]},{"t":"东园牡丹小会四首 其三","f":"五言律诗","c":["多少东风恨，天香正满林。","影摇春酒艳，色傍玉楼深。","乐曲临时制，花名按谱寻。","清平当日调，回忆久沈吟。"]},{"t":"东园牡丹小会四首 其四","f":"五言律诗","c":["倾国俱名品，呈姿媚一堂。","倚阑浑欲醉，入座转闻香。","月下千金笑，灯前百宝装。","夜深春更暖，忍负紫霞觞。"]},{"t":"夏日饮表弟刘敬宇水亭四首 其一","f":"五言律诗","c":["水际芙蓉馆，芳辰每见招。","车停林外雨，人过竹边桥。","树影侵杯动，花香入眼飘。","坐来閒白羽，秋气已萧萧。"]},{"t":"夏日饮表弟刘敬宇水亭四首 其二","f":"五言律诗","c":["别业中丞旧，新塘凿更奇。","亭深凫雁渚，树老凤凰枝。","惜往宁多日，徵欢又一时。","洗杯酬爱弟，偏忆渭阳诗。"]},{"t":"夏日饮表弟刘敬宇水亭四首 其三","f":"五言律诗","c":["亦有池台胜，如君结搆稀。","横槎能作榭，蟠木可为矶。","漫取花行酒，真愁露湿衣。","层轩销暑气，赤日石林微。"]},{"t":"夏日饮表弟刘敬宇水亭四首 其四","f":"五言律诗","c":["晚凉犹未倦，改席倚亭阑。","脍鲤银丝细，调冰玉椀寒。","笑开桃叶扇，醉岸竹皮冠。","杯底中天月，还应勒马看。"]},{"t":"寄题新蔡水亭二首 其一","f":"五言律诗","c":["闻道名王馆，深依上第开。","花间分岛屿，云里出亭台。","夏洞藏阴雪，晴流激暗雷。","不因人境近，只拟是天台。"]},{"t":"寄题新蔡水亭二首 其二","f":"五言律诗","c":["主君宾客盛，何处席长筵。","门簇看花骑，池通送酒船。","星霞垂夜彩，凫雁下秋烟。","未觉淮山远，空吟桂树篇。"]},{"t":"汎溪","f":"五言律诗","c":["一曲无多路，洄沿自觉长。","近人堤柳细，隔水岸花香。","放鹤遵莎径，观鱼坐石梁。","不教渔父问，此地即沧浪。"]},{"t":"寄题贞白王孙赤霞馆","f":"五言律诗","c":["藉甚天潢彦，才名满帝家。","书藏东观草，馆号赤城霞。","梦里常吞锦，毫端自吐花。","不知银汉水，几日见浮槎。"]},{"t":"五月十三日南溪会集","f":"五言律诗","c":["高会南溪始，芳尊午日同。","登亭来暮雨，敞阁受林风。","岁月飞花好，河山醉眼中。","莫閒青玉盏，俱是白头翁。"]},{"t":"七日南溪会集","f":"五言律诗","c":["七夕始迎秋，溪亭复此游。","午凉慵举扇，夕雨罢登舟。","倚杖窥云树，停杯待女牛。","只怜天上夜，亦向此时愁。"]},{"t":"七日夜雨","f":"五言律诗","c":["佳期方待夜，雨气转氤氲。","愁望明河影，翻成楚岫云。","鹊梁何地驾，笙鹤会能闻。","未悟阴晴理，休将巧拙分。"]},{"t":"中贞王孙过访少岱山房酬赠二首 其一","f":"五言律诗","c":["秋气飒萧森，亭皋夕坐深。","美人沧洲兴，过我青枫林。","倚剑冲星气，停杯待月阴。","小山丛桂在，端复为谁吟。"]},{"t":"中贞王孙过访少岱山房酬赠二首 其二","f":"五言律诗","c":["池阁三秋别，山斋七月过。","车尘花际少，云气酒边多。","客路搴芳草，征衣带女萝。","一欢吾欲醉，且莫促鸣珂。"]},{"t":"寺山秋望","f":"五言律诗","c":["平楚净寒烟，高丘望渺然。","日斜虹带雨，野阔水浮天。","绝塞南来雁，长河北去船。","荒台题仲父，芜没几千年。"]},{"t":"山亭","f":"五言律诗","c":["雨晴多物态，秋敞坐山亭。","旧竹泠泠翠，新萝裔裔青。","荷锄分药径，散帙闭柴扃。","挂树双言鸟，繁辞尽日听。"]},{"t":"南溪秋汎","f":"五言律诗","c":["野馆无停辙，秋塘有系舟。","怯同俗客饮，且唤老妻游。","蝶欲疑红树，鸥应笑白头。","渔人休借问，此是鹿门俦。"]},{"t":"小坐","f":"五言律诗","c":["小坐霜天夕，空庭竹树深。","城笳凝暮霭，楼月敛秋阴。","渐老消尘虑，长贫现道心。","摩婆旧如意，懒击唾壶吟。"]},{"t":"东园即事","f":"五言律诗","c":["蓬门长日闭，俛仰自为欢。","酹酒邀花饮，分鱼唤鹤餐。","閒看秋水淡，老觉世涂宽。","不是无萧索，人间事更难。"]},{"t":"中秋东园小集","f":"五言律诗","c":["渐上千峰月，真销万里云。","秋从今夜半，人是旧时群。","桂影寒应湿，箫声静欲闻。","相看疑白发，总似兔毫分。"]},{"t":"九日登小岱山","f":"五言律诗","c":["九日罢徵欢，孤尊眺岳坛。","晚烟千室翠，落日万峰丹。","已有鸿堪听，还无菊可餐。","江湖回白首，愁见是长安。"]},{"t":"木芙蓉","f":"五言律诗","c":["一本芙蓉树，三秋觅地栽。","尚逢南客问，果向北亭开。","色落仙人掌，香浮太乙杯。","可怜霜夜月，华艳满池台。"]},{"t":"九月廿五日东园菊下小集四首 其一","f":"五言律诗","c":["朝来全罢酒，秋尽复看花。","布席轻张幔，题名细剪纱。","开时团玉露，餐处带明霞。","萧瑟还怜汝，含芳绾岁华。"]},{"t":"九月廿五日东园菊下小集四首 其二","f":"五言律诗","c":["今岁重阳菊，翻迎十月看。","犹馀秋日映，已近北风寒。","冻蕊开逾艳，贞心抱自完。","搴芳思有赠，惆怅倚亭阑。"]},{"t":"九月廿五日东园菊下小集四首 其三","f":"五言律诗","c":["花开原五色，色色断人肠。","浴出俱含雨，妆成总奈霜。","凄凉倾国品，酷烈岁寒香。","回笑春桃李，随风委艳阳。"]}]};